  revision_reason, revision_type, ai_review_status, thinking_level, knowledge_type, concepts, source_page, memo_pages, memo_coverage, memo_note,
  duplicate_of, review_status, reviewed_at) values
(401101, 4011, 'K3-C1-L1-O01', null, 1, 'أن يعرف الطالب المخلوط', 'أن يعرّف الطالب المخلوط.', '[]'::jsonb, 'أن يعرّف الطالب المخلوط.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المخلوط","المادة النقية"]'::jsonb, null, '[14]'::jsonb, 'مغطى', 'يذكّر الكتاب بأن المخلوط «مزيج من مادتين نقيتين أو أكثر، تحتفظ فيه كل مادة بخصائصها». يرد التعريف تذكيرًا في مقدمة الدرس لا تعريفًا جديدًا.', null, 'approved', '2026-10-16'::timestamptz),
(401102, 4011, 'K3-C1-L1-O02', null, 2, 'أن يذكر الطالب أنواع المخاليط', 'أن يذكر الطالب نوعَي المخاليط (المتجانسة وغير المتجانسة).', '[]'::jsonb, 'أن يذكر الطالب نوعَي المخاليط (المتجانسة وغير المتجانسة).', 'تحديد المطلوب ليصبح قابلًا للقياس وفق الفكرة الرئيسة للدرس.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["المخاليط المتجانسة","المخاليط غير المتجانسة","المحاليل"]'::jsonb, null, '[14,18]'::jsonb, 'مغطى', 'الفكرة الرئيسة: «المخاليط إما متجانسة أو غير متجانسة». غير المتجانسة نوعان هما المعلق والغروي، والمتجانسة هي المحاليل.', null, 'approved', '2026-10-16'::timestamptz),
(401103, 4011, 'K3-C1-L1-O03', null, 3, 'أن يعرف الطالب المخلوط غير المتجانس', 'أن يعرّف الطالب المخلوط غير المتجانس.', '[]'::jsonb, 'أن يعرّف الطالب المخلوط غير المتجانس.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["المخلوط غير المتجانس"]'::jsonb, null, '[14]'::jsonb, 'مغطى', 'المخاليط غير المتجانسة «لا تمتزج مكوناتها تمامًا معًا؛ أي يمكن تمييز كل منها»، وهي نوعان: المعلق والغروي.', null, 'approved', '2026-10-16'::timestamptz),
(401104, 4011, 'K3-C1-L1-O04', null, 4, 'أن يذكر الطالب أمثلة على المخاليط غير المتجانسة', 'أن يذكر الطالب أمثلة على المخاليط غير المتجانسة (المعلقة والغروية).', '[]'::jsonb, 'أن يذكر الطالب أمثلة على المخاليط غير المتجانسة (المعلقة والغروية).', 'ربط الأمثلة بنوعَي المخاليط غير المتجانسة كما في الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["المخلوط المعلق","المخلوط الغروي","الوحل","الحليب"]'::jsonb, null, '[14,15]'::jsonb, 'مغطى', 'من أمثلة المعلق الوحل (الشكل 1-1). ويعرض الجدول 1-1 أمثلة على الغروي: الأحجار الكريمة الملونة (صلب في صلب)، والدم والجيلاتين (صلب في سائل)، والزبد والجبن (مستحلب صلب)، والحليب والمايونيز (مستحلب)، وحلوى الخطمي والصابون الطافي (رغوة صلبة)، والدخان والغبار في الهواء (هباء جوي صلب)، والغيوم والضباب (هباء جوي سائل).', null, 'approved', '2026-10-16'::timestamptz),
(401105, 4011, 'K3-C1-L1-O05', null, 5, 'أن يصنف الطالب المحاليل بالاعتماد على حالة المذيب', 'أن يصنّف الطالب المحاليل بالاعتماد على الحالة الفيزيائية للمذيب.', '[]'::jsonb, 'أن يصنّف الطالب المحاليل بالاعتماد على الحالة الفيزيائية للمذيب.', 'ضبط «يصنّف» بالشدة وإضافة «الفيزيائية» كما في نص الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["أنواع المحاليل","المذيب","المذاب","الحالة الفيزيائية"]'::jsonb, null, '[16,17,18]'::jsonb, 'مغطى', 'قد يكون المحلول غازيًا أو سائلًا أو صلبًا اعتمادًا على الحالة الفيزيائية للمذيب، وقد يكون المذاب غازًا أو سائلًا أو صلبًا. أمثلة الجدول 1-2: الهواء (غاز)، والماء الغازي ومانع التجمد وماء البحر (سائل)، والفولاذ ولغم الأسنان (صلب)، وسبيكة النيتينول في تقويم الأسنان (صلب).', null, 'approved', '2026-10-16'::timestamptz),
(401106, 4011, 'K3-C1-L1-O06', null, 6, 'أن يقارن الطالب بين المخلوط الحقيقي والمعلق والغروي', 'أن يقارن الطالب بين المحلول والمخلوط المعلق والمخلوط الغروي.', '[]'::jsonb, 'أن يقارن الطالب بين المحلول والمخلوط المعلق والمخلوط الغروي.', 'عبارة «المخلوط الحقيقي» غير مستعملة في الكتاب؛ الصواب «المحلول» (المحلول الحقيقي).', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["المحلول","المخلوط المعلق","المخلوط الغروي","حجم الجسيمات","تأثير تندال"]'::jsonb, null, '[14,15,16,18]'::jsonb, 'مغطى', 'المعلق: جسيماته كبيرة وتترسب بالترويق وتُفصل بالترشيح. الغروي: أقطار جسيماته بين 1 nm و1000 nm ولا تترسب ولا تُفصل بالترويق أو الترشيح. المعلق والغروي يُظهران تأثير تندال، أما المحلول فلا يُظهره ولا يمكن فيه التمييز بين المذاب والمذيب. السؤال 8 في التقويم 1-1 يطلب جدولًا للمقارنة.', null, 'approved', '2026-10-16'::timestamptz),
(401107, 4011, 'K3-C1-L1-O07', null, 7, 'أن يعرف الطالب الترويق', 'أن يوضّح الطالب المقصود بالترويق بوصفه طريقة لفصل مكونات المخلوط المعلق.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالترويق بوصفه طريقة لفصل مكونات المخلوط المعلق.', 'الكتاب لا يعرّف الترويق مصطلحًا مستقلًا بل يذكره طريقةً لترسيب جسيمات المعلق؛ فيُربط الهدف بسياقه.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["الترويق","المخلوط المعلق","الترشيح"]'::jsonb, null, '[14]'::jsonb, 'جزئي', 'يرد الترويق في تعريف المعلق فقط: «يحتوي على جسيمات يمكن أن تترسب بالترويق؛ وذلك بتركه فترة دون تحريك» (الشكل 1-1). لا يوجد تعريف مستقل للمصطلح ضمن مفردات الدرس.', null, 'approved', '2026-10-16'::timestamptz),
(401108, 4011, 'K3-C1-L1-O08', null, 8, 'أن يوضح الطالب ظاهرة تندال', 'أن يوضّح الطالب تأثير تندال.', '[]'::jsonb, 'أن يوضّح الطالب تأثير تندال.', 'توحيد المصطلح مع الكتاب («تأثير تندال») وضبط الفعل.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["تأثير تندال","تشتت الضوء","المخلوط الغروي"]'::jsonb, null, '[16]'::jsonb, 'مغطى', 'تأثير تندال هو تشتيت جسيمات المخلوط الغروي المنتشرة للضوء (الشكل 1-3). تُظهره المخاليط المعلقة أيضًا، ولا تُظهره المحاليل. أمثلته: مرور أشعة الشمس خلال الهواء المشبع بالدخان، وضوء خلال الضباب. ويُستخدم لتحديد كمية الجسيمات في المعلق.', null, 'approved', '2026-10-16'::timestamptz),
(401109, 4011, 'K3-C1-L1-O09', null, 9, 'أن يفسر الطالب سبب بقاء جسيمات المذاب في المخلوط الغروي', 'أن يفسّر الطالب سبب عدم ترسّب الجسيمات المنتشرة في المخلوط الغروي.', '[]'::jsonb, 'أن يفسّر الطالب سبب عدم ترسّب الجسيمات المنتشرة في المخلوط الغروي.', 'الكتاب يسمي هذه الجسيمات «الجسيمات المنتشرة» لا «جسيمات المذاب»، والسؤال نفسه في «ماذا قرأت؟» ص 16.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["الجسيمات المنتشرة","وسط الانتشار","الطبقات الكهروستاتيكية","الحركة البراونية"]'::jsonb, null, '[15,16]'::jsonb, 'مغطى', 'سببان: (1) للجسيمات المنتشرة مجموعات قطبية أو مشحونة على سطحها تجذب جسيمات وسط الانتشار فتتكون حولها طبقات كهروستاتيكية تتنافر عند التصادم (الشكل 1-2). (2) الحركة البراونية، وهي تصادمات جسيمات الوسط بالجسيمات المنتشرة. إضافة مادة متأينة أو التسخين يُتلف الغروي فتترسب جسيماته.', null, 'approved', '2026-10-16'::timestamptz),
(401110, 4011, 'K3-C1-L1-O10', null, 10, 'أن يفسر الطالب صعوبة قيادة السيارة خلال أجواء الضباب', 'أن يفسّر الطالب صعوبة قيادة السيارة في أجواء الضباب، ولا سيما باستخدام الأنوار العالية، مستخدمًا تأثير تندال.', '[]'::jsonb, 'أن يفسّر الطالب صعوبة قيادة السيارة في أجواء الضباب، ولا سيما باستخدام الأنوار العالية، مستخدمًا تأثير تندال.', 'ربط الهدف بالمفهوم العلمي (تأثير تندال) كما في سؤال التقويم.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مبادئ وتعميمات', '["تأثير تندال","الضباب","الهباء الجوي السائل"]'::jsonb, null, '[15,16,18]'::jsonb, 'جزئي', 'لا يشرح المتن هذه الحالة مباشرة، بل ترد سؤالًا تطبيقيًا (التقويم 1-1، س4). المتن يذكر أن الضباب هباء جوي سائل (الجدول 1-1)، وأن تأثير تندال يُلاحظ عند مرور الضوء خلال الضباب. التفسير المتوقع: قطيرات الضباب تشتت الضوء، والأنوار العالية تزيد الضوء المشتت المرتد نحو السائق.', null, 'approved', '2026-10-16'::timestamptz),
(401111, 4011, 'K3-C1-L1-O11', null, 11, 'أن يعرّف الطالب الحركة البراونية.', 'أن يعرّف الطالب الحركة البراونية.', '[]'::jsonb, 'أن يعرّف الطالب الحركة البراونية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الحركة البراونية","المخلوط الغروي","وسط الانتشار"]'::jsonb, null, '[16,18]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الحركة البراونية حركة عشوائية غير منتظمة ومستمرة لجسيمات المخلوط الغروي السائل، لاحظها أول مرة عالم النبات الإسكتلندي روبرت براون (1773–1858) في حبوب اللقاح المنتشرة في الماء، وتنتج عن تصادم جسيمات وسط الانتشار مع الجسيمات المنتشرة. ترد ضمن المفردات الجديدة وخلاصة الدرس، والسؤال 7 في التقويم 1-1: «ما الذي يسبب الحركة البراونية؟».', null, 'approved', '2026-10-16'::timestamptz),
(401112, 4011, 'K3-C1-L1-O12', null, 12, 'أن يصنّف الطالب المخاليط الغروية تبعًا للحالة الفيزيائية لكل من الجسيمات المنتشرة ووسط الانتشار.', 'أن يصنّف الطالب المخاليط الغروية تبعًا للحالة الفيزيائية لكل من الجسيمات المنتشرة ووسط الانتشار.', '[]'::jsonb, 'أن يصنّف الطالب المخاليط الغروية تبعًا للحالة الفيزيائية لكل من الجسيمات المنتشرة ووسط الانتشار.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الجسيمات المنتشرة","وسط الانتشار","المستحلب","الرغوة","الهباء الجوي","الصل","المادة الهلامية"]'::jsonb, null, '[15,18]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تُسمى المادة الأكثر توافرًا في المخلوط الغروي وسط الانتشار، وتُصنّف المخاليط الغروية تبعًا للحالة الفيزيائية لكل من الجسيمات المنتشرة ووسط الانتشار؛ فالحليب مستحلب لأن جسيماته المنتشرة السائلة تنتشر في وسط انتشار سائل. الجدول 1-1 «أنواع المخاليط الغروية وأمثلة عليها»: صل صلب (صلب في صلب)، صل (صلب في سائل)، مستحلب صلب (سائل في صلب)، مستحلب (سائل في سائل)، رغوة صلبة (غاز في صلب)، رغوة (غاز في سائل)، هباء جوي صلب (صلب في غاز)، هباء جوي سائل (سائل في غاز). السؤال 5 في التقويم: «اذكر الأنواع المختلفة للمخاليط الغروية».', null, 'approved', '2026-10-16'::timestamptz),
(401113, 4011, 'K3-C1-L1-O13', null, 13, 'أن يفسّر الطالب تلف المخلوط الغروي وترسّب جسيماته عند إضافة مادة متأينة إليه أو تسخينه.', 'أن يفسّر الطالب تلف المخلوط الغروي وترسّب جسيماته عند إضافة مادة متأينة إليه أو تسخينه.', '[]'::jsonb, 'أن يفسّر الطالب تلف المخلوط الغروي وترسّب جسيماته عند إضافة مادة متأينة إليه أو تسخينه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["المخلوط الغروي","الطبقات الكهروستاتيكية","المادة المتأينة","التسخين"]'::jsonb, null, '[15]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). إذا تدخلنا في الطبقات الكهروستاتيكية فسوف تترسب الجسيمات المنتشرة؛ فعند تحريك مادة متأينة (إلكتروليتية) في مخلوط غروي تتجمع الجسيمات المنتشرة معًا ويتلف المخلوط الغروي، كما أن التسخين يتلفه لأن الحرارة تعطي الجسيمات المتصادمة طاقة حركية كافية للتغلب على القوى الكهروستاتيكية فتترسب (الشكل 1-2).', null, 'approved', '2026-10-16'::timestamptz),
(401114, 4011, 'K3-C1-L1-O14', null, 14, 'أن يميّز الطالب بين السوائل الممتزجة والسوائل غير الممتزجة مع ذكر أمثلة عليها.', 'أن يميّز الطالب بين السوائل الممتزجة والسوائل غير الممتزجة مع ذكر أمثلة عليها.', '[]'::jsonb, 'أن يميّز الطالب بين السوائل الممتزجة والسوائل غير الممتزجة مع ذكر أمثلة عليها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["السوائل الممتزجة","السوائل غير الممتزجة","مانع التجمد","الزيت والخل"]'::jsonb, null, '[17]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تُسمى المادتان السائلتان اللتان تذوب إحداهما في الأخرى بأي نسبة المواد القابلة للامتزاج (الممتزجة)، ومنها مانع التجمد المذكور في الجدول 1-2 (الإيثيلين جلايكول في الماء). وتُسمى السوائل التي تمتزج معًا فترة قصيرة عند خلطها ثم تنفصل بعدها السوائل غير الممتزجة؛ فالزيت مثلًا لا يمتزج مع الخل، أي لا يذوب فيه.', null, 'approved', '2026-10-16'::timestamptz),
(401115, 4011, 'K3-C1-L1-O15', null, 15, 'أن يفرّق الطالب بين المادة الذائبة والمادة غير الذائبة.', 'أن يفرّق الطالب بين المادة الذائبة والمادة غير الذائبة.', '[]'::jsonb, 'أن يفرّق الطالب بين المادة الذائبة والمادة غير الذائبة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المادة الذائبة","المادة غير الذائبة","المذيب"]'::jsonb, null, '[16,17]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تُسمى المادة التي تذوب في المذيب المادة الذائبة، كذوبان السكر في الماء لعمل شراب محلّى كالشاي، وتُسمى المادة التي لا تذوب في المذيب المادة غير الذائبة؛ فالرمل مثلًا لا يذوب في الماء. والمصطلحان من المفردات الجديدة للدرس 1-1.', null, 'approved', '2026-10-16'::timestamptz),
(401201, 4012, 'K3-C1-L2-O01', null, 1, 'ان يعرف الطالب تركيز المحلول', 'أن يعرّف الطالب تركيز المحلول.', '[]'::jsonb, 'أن يعرّف الطالب تركيز المحلول.', 'إضافة همزة «أن» وضبط «يعرّف».', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["التركيز","محلول مركز","محلول مخفف"]'::jsonb, null, '[19]'::jsonb, 'مغطى', 'تركيز المحلول «مقياس يعبر عن كمية المذاب الذائبة في كمية محددة من المذيب أو المحلول». يمكن وصفه نوعيًا بكلمتي «مركز» و«مخفف» (الشكل 1-4، الشاي)، أو كميًا.', null, 'approved', '2026-10-16'::timestamptz),
(401202, 4012, 'K3-C1-L2-O02', null, 2, 'أن يعدد الطالب طرق التعبير عن تركيز المحلول ( كميا)', 'أن يعدّد الطالب طرائق التعبير الكمي عن تركيز المحلول.', '[]'::jsonb, 'أن يعدّد الطالب طرائق التعبير الكمي عن تركيز المحلول.', 'حذف القوسين ودمج القيد «كميًا» في العبارة، وضبط الفعل.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["النسبة المئوية بالكتلة","النسبة المئوية بالحجم","المولارية","المولالية","الكسر المولي"]'::jsonb, null, '[19]'::jsonb, 'مغطى', 'الجدول 1-3 يعرض خمس طرائق مع نسبها: النسبة المئوية بدلالة الكتلة = (كتلة المذاب/كتلة المحلول)×100، والنسبة المئوية بدلالة الحجم = (حجم المذاب/حجم المحلول)×100، والمولارية M = مولات المذاب/حجم المحلول (L)، والمولالية m = مولات المذاب/كتلة المذيب (kg)، والكسر المولي = مولات المذاب أو المذيب/(مولات المذاب + مولات المذيب).', null, 'approved', '2026-10-16'::timestamptz),
(401203, 4012, 'K3-C1-L2-O03', null, 3, 'أن يفرق الطالب بين النسبة المئوية الكتلية والحجمية', 'أن يفرّق الطالب بين النسبة المئوية بدلالة الكتلة والنسبة المئوية بدلالة الحجم.', '[]'::jsonb, 'أن يفرّق الطالب بين النسبة المئوية بدلالة الكتلة والنسبة المئوية بدلالة الحجم.', 'استعمال مصطلح الكتاب «بدلالة الكتلة/الحجم» وضبط الفعل.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["النسبة المئوية بدلالة الكتلة","النسبة المئوية بدلالة الحجم"]'::jsonb, null, '[20,21]'::jsonb, 'مغطى', 'النسبة بدلالة الكتلة هي نسبة كتلة المذاب إلى كتلة المحلول (كتلة المحلول = كتلة المذاب + كتلة المذيب) مضروبة في 100. النسبة بدلالة الحجم تصف عادة المحاليل التي يكون فيها المذيب والمذاب سائلين، وهي نسبة حجم المذاب إلى حجم المحلول مضروبة في 100. سؤال «ماذا قرأت؟» ص 21: قارن بينهما.', null, 'approved', '2026-10-16'::timestamptz),
(401204, 4012, 'K3-C1-L2-O04', null, 4, 'أن يحسب الطالب النسبة المئوية الكتلية و الحجمية لمحلول', 'أن يحسب الطالب النسبة المئوية بدلالة الكتلة والنسبة المئوية بدلالة الحجم لمحلول.', '["أن يحسب الطالب النسبة المئوية بدلالة الكتلة لمحلول.","أن يحسب الطالب النسبة المئوية بدلالة الحجم لمحلول."]'::jsonb, 'أن يحسب الطالب النسبة المئوية بدلالة الكتلة والنسبة المئوية بدلالة الحجم لمحلول.', 'الهدف يجمع مهارتين حسابيتين مستقلتين لكل منهما مثال ومسائل في الكتاب.', 'تقسيم', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["النسبة المئوية بدلالة الكتلة","النسبة المئوية بدلالة الحجم"]'::jsonb, null, '[20,21]'::jsonb, 'مغطى', 'مثال 1-1: 3.6 g NaCl في 100.0 g ماء، فكتلة المحلول 103.6 g والنسبة 3.5%. مسائل 9–12 على النسبة بالكتلة. مسائل 13–15 على النسبة بالحجم، مثل 35 mL إيثانول في 155 mL ماء.', null, 'approved', '2026-10-16'::timestamptz),
(401205, 4012, 'K3-C1-L2-O05', null, 5, 'أن يعرف الطالب المولارية', 'أن يعرّف الطالب المولارية.', '[]'::jsonb, 'أن يعرّف الطالب المولارية.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["المولارية","التركيز المولاري"]'::jsonb, null, '[21]'::jsonb, 'مغطى', 'المولارية (M) هي عدد مولات المذاب الذائبة في لتر من المحلول، وتُعرف بالتركيز المولاري. M = عدد مولات المذاب (mol)/حجم المحلول (L). مثال: لتر يحتوي 1 mol مذاب تركيزه 1.0 M.', null, 'approved', '2026-10-16'::timestamptz),
(401206, 4012, 'K3-C1-L2-O06', null, 6, 'أن يحسب الطالب مولارية محلول', 'أن يحسب الطالب مولارية محلول.', '[]'::jsonb, 'أن يحسب الطالب مولارية محلول.', '', '', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["المولارية","عدد المولات","الكتلة المولية"]'::jsonb, null, '[21,22]'::jsonb, 'مغطى', 'مثال 1-2: 5.10 g جلوكوز (الكتلة المولية 180.16 g/mol) في 100.5 mL محلول، فعدد المولات 0.0283 mol والحجم 0.1005 L، ومن ثم M = 0.282 M. مسائل 16–19، منها حساب كتلة Ca(OH)2 اللازمة لتحضير 1.5 L بتركيز 0.25 M.', null, 'approved', '2026-10-16'::timestamptz),
(401207, 4012, 'K3-C1-L2-O07', null, 7, 'أن يعرف الطالب المحلول القياسي', 'أن يعرّف الطالب المحلول القياسي.', '[]'::jsonb, 'أن يعرّف الطالب المحلول القياسي.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المحلول القياسي"]'::jsonb, null, '[23]'::jsonb, 'مغطى', 'المحاليل القياسية «محاليل لها تراكيز محددة تُستعمل في المختبر»، ومنها محلول HCl الذي تركيزه 1M. خطوات التحضير في الشكل 1-5: تُقاس كتلة المذاب، وتُذاب في دورق حجمي بأقل كمية ماء، ثم يُضاف الماء حتى العلامة.', null, 'approved', '2026-10-16'::timestamptz),
(401208, 4012, 'K3-C1-L2-O08', null, 8, 'أن يحسب الطالب حجم محلول قياسي بمعلومية مولاريته', 'أن يحسب الطالب حجم المحلول القياسي اللازم لتحضير محلول مخفف باستعمال معادلة التخفيف M1V1 = M2V2.', '[]'::jsonb, 'أن يحسب الطالب حجم المحلول القياسي اللازم لتحضير محلول مخفف باستعمال معادلة التخفيف M1V1 = M2V2.', 'العبارة الأصلية غامضة؛ الكتاب يحسب حجم المحلول القياسي في سياق التخفيف، فتُحدَّد المعادلة.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["المحلول القياسي","التخفيف","M1V1 = M2V2"]'::jsonb, null, '[23,24,25]'::jsonb, 'مغطى', 'لأن عدد مولات المذاب لا يتغير بالتخفيف، فإن M1V1 = M2V2، حيث M1 وV1 مولارية المحلول القياسي وحجمه، وM2 وV2 مولارية المحلول المخفف وحجمه. مثال 1-3: V1 = 0.50 L × 0.300 M/2.00 M = 0.075 L = 75 mL من CaCl2. مسائل 24–26. وص 23 تتضمن حساب كتلة المذاب: 37.5 g CuSO4·5H2O لتحضير 100 mL بتركيز 1.5 M.', null, 'approved', '2026-10-16'::timestamptz),
(401209, 4012, 'K3-C1-L2-O09', null, 9, 'أن يعرف الطالب المولالية', 'أن يعرّف الطالب المولالية.', '[]'::jsonb, 'أن يعرّف الطالب المولالية.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["المولالية","التركيز المولالي"]'::jsonb, null, '[26]'::jsonb, 'مغطى', 'المولالية (m) هي عدد مولات المذاب في 1 kg من المذيب: m = عدد مولات المذاب/كتلة المذيب (kg). تُفضَّل أحيانًا لأن كتل المواد لا تتأثر بدرجة الحرارة، بخلاف الحجم الذي يؤثر في المولارية.', null, 'approved', '2026-10-16'::timestamptz),
(401210, 4012, 'K3-C1-L2-O10', null, 10, 'أن يحسب الطالب مولالية محلول', 'أن يحسب الطالب مولالية محلول.', '[]'::jsonb, 'أن يحسب الطالب مولالية محلول.', '', '', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["المولالية"]'::jsonb, null, '[26]'::jsonb, 'مغطى', 'مثال 1-4: 4.5 g NaCl (0.077 mol) في 100.0 g ماء (0.1000 kg)، فتكون m = 0.77 mol/kg. مسائل 27–28.', null, 'approved', '2026-10-16'::timestamptz),
(401211, 4012, 'K3-C1-L2-O11', null, 11, 'أن يعرف الطالب الكسر المولي', 'أن يعرّف الطالب الكسر المولي.', '[]'::jsonb, 'أن يعرّف الطالب الكسر المولي.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["الكسر المولي"]'::jsonb, null, '[27]'::jsonb, 'مغطى', 'الكسر المولي هو نسبة عدد مولات المذاب أو المذيب في المحلول إلى عدد المولات الكلية للمذيب والمذاب، ويُرمز له X: XA = nA/(nA+nB) وXB = nB/(nA+nB)، ومجموع الكسور المولية = 1.', null, 'approved', '2026-10-16'::timestamptz),
(401212, 4012, 'K3-C1-L2-O12', null, 12, 'أن يحسب الطالب الكسر المولي', 'أن يحسب الطالب الكسر المولي لكل من المذاب والمذيب في محلول.', '[]'::jsonb, 'أن يحسب الطالب الكسر المولي لكل من المذاب والمذيب في محلول.', 'تحديد المطلوب حسابه ليكون الهدف قابلًا للقياس.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["الكسر المولي"]'::jsonb, null, '[27]'::jsonb, 'مغطى', 'مثال المتن: 36 g HCl (0.99 mol) و64 g H2O (3.6 mol)، فيكون X(HCl) = 0.22 وX(H2O) = 0.78 (الشكل 1-7). مسائل 29–30.', null, 'approved', '2026-10-16'::timestamptz),
(401213, 4012, 'K3-C1-L2-O13', null, 13, 'أن يصف الطالب خطوات تحضير محلول قياسي معلوم المولارية باستعمال الدورق الحجمي، بدءًا بحساب كتلة المذاب اللازمة.', 'أن يصف الطالب خطوات تحضير محلول قياسي معلوم المولارية باستعمال الدورق الحجمي، بدءًا بحساب كتلة المذاب اللازمة.', '[]'::jsonb, 'أن يصف الطالب خطوات تحضير محلول قياسي معلوم المولارية باستعمال الدورق الحجمي، بدءًا بحساب كتلة المذاب اللازمة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["المحلول القياسي","الدورق الحجمي","المولارية","كتلة المذاب"]'::jsonb, null, '[23]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). قسم «تحضير المحاليل القياسية»: لتحضير 1.0 L من محلول CuSO4·5H2O تركيزه 1.5 M تُحسب الكتلة اللازمة (1.50 mol × 249.7 g/mol = 375 g)، ثم الخطوات في الشكل 1-5: (1) تُقاس كتلة المذاب وتُضاف إلى دورق حجمي مناسب، (2) يُذاب المذاب في أقل كمية من الماء المقطر، (3) يُضاف الماء المقطر حتى يصل مستوى المحلول إلى العلامة المحددة على الدورق. ولتحضير 100 mL من المحلول نفسه تلزم 37.5 g. تعليق الشكل: لا يمكن وضع 375 g في 1.0 L من الماء مباشرة لتحضير محلول 1.5 M. مسائل تدريبية 20–23.', null, 'approved', '2026-10-16'::timestamptz),
(401301, 4013, 'K3-C1-L3-O01', null, 1, 'أن يعرف الطالب الذوبان', 'أن يعرّف الطالب الذوبان.', '[]'::jsonb, 'أن يعرّف الطالب الذوبان.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["الذوبان","المذيب يذيب شبيهه"]'::jsonb, null, '[29]'::jsonb, 'مغطى', 'الذوبان هو «عملية إحاطة جسيمات المذاب بجسيمات المذيب» (الشكل 1-8). يحدث إذا كانت قوى التجاذب بين المذاب والمذيب أكبر من قوى التجاذب بين جسيمات المذاب نفسه. القاعدة العامة: «المذيب يذيب شبيهه» بحسب القطبية ونوع الروابط بين الجزيئية.', null, 'approved', '2026-10-16'::timestamptz),
(401302, 4013, 'K3-C1-L3-O02', null, 2, 'أن يفسر الطالب سبب ذوبان المركبات الايونية في الماء', 'أن يفسّر الطالب آلية ذوبان المركبات الأيونية في الماء.', '[]'::jsonb, 'أن يفسّر الطالب آلية ذوبان المركبات الأيونية في الماء.', 'إضافة همزة «الأيونية»، وتبديل «سبب» بـ«آلية» لأن الكتاب يشرح الخطوات.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["المركبات الأيونية","قطبية الماء","الذوبان"]'::jsonb, null, '[30]'::jsonb, 'مغطى', 'جزيئات الماء القطبية تصطدم بسطح بلورة NaCl وتجذب أقطابها أيونات Na+ وCl-. التجاذب بين الأقطاب والأيونات أكبر من التجاذب بين الأيونات في البلورة، فتنفصل الأيونات وتحيط بها جزيئات الماء (الشكل 1-9). بعض المركبات الأيونية لا تذوب، كالجبس، لقوة التجاذب بين أيوناته.', null, 'approved', '2026-10-16'::timestamptz),
(401303, 4013, 'K3-C1-L3-O03', null, 3, 'أن يفسر الطالب سبب ذوبان المركبات الجزيئية في الماء', 'أن يفسّر الطالب آلية ذوبان المركبات الجزيئية في الماء.', '[]'::jsonb, 'أن يفسّر الطالب آلية ذوبان المركبات الجزيئية في الماء.', 'تبديل «سبب» بـ«آلية» لتوافق عرض الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["المركبات الجزيئية","الروابط الهيدروجينية","السكروز"]'::jsonb, null, '[31]'::jsonb, 'مغطى', 'جزيء السكروز القطبي يحتوي 8 روابط O–H، وتصبح كل منها موقعًا لتكوين روابط هيدروجينية مع الماء. تتغلب قوى التجاذب بين السكروز والماء على قوى التجاذب بين جزيئات السكروز، فتترك الجزيئات البلورة وتذوب (الشكل 1-11).', null, 'approved', '2026-10-16'::timestamptz),
(401304, 4013, 'K3-C1-L3-O04', null, 4, 'أن يوضح الطالب أثر التحريك في سرعة الذوبان', 'أن يوضّح الطالب أثر التحريك في سرعة الذوبان.', '[]'::jsonb, 'أن يوضّح الطالب أثر التحريك في سرعة الذوبان.', 'ضبط الفعل «يوضّح».', 'إملائي', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["سرعة الذوبان","التحريك"]'::jsonb, null, '[32]'::jsonb, 'مغطى', 'يعمل التحريك على إبعاد جسيمات المذاب عن سطوح التماس بسرعة أكبر، فيسمح بتصادمات أخرى بين المذاب والمذيب وتزداد سرعة الذوبان. ودون تحريك تتحرك الجسيمات الذائبة بعيدًا ببطء (الشكل 1-12).', null, 'approved', '2026-10-16'::timestamptz),
(401305, 4013, 'K3-C1-L3-O05', null, 5, 'أن يوضح الطالب أثر مساحة السطح في سرعة الذوبان', 'أن يوضّح الطالب أثر مساحة السطح في سرعة الذوبان.', '[]'::jsonb, 'أن يوضّح الطالب أثر مساحة السطح في سرعة الذوبان.', 'ضبط الفعل «يوضّح».', 'إملائي', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["سرعة الذوبان","مساحة السطح"]'::jsonb, null, '[32]'::jsonb, 'مغطى', 'تكسير المذاب إلى قطع صغيرة يزيد مساحة سطحه، فيزداد عدد التصادمات بين جسيماته وجسيمات المذيب. لذلك يذوب السكر المطحون أسرع من مكعبات السكر. ملاحظة: الكتاب يتناول أيضًا أثر درجة الحرارة ولا يقابله هدف.', null, 'approved', '2026-10-16'::timestamptz),
(401306, 4013, 'K3-C1-L3-O06', null, 6, 'أن يعرف الطالب قانون هنري', 'أن يذكر الطالب نص قانون هنري.', '[]'::jsonb, 'أن يذكر الطالب نص قانون هنري.', 'القانون يُذكر نصه ولا يُعرَّف؛ و«يذكر» أدق في القياس.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مبادئ وتعميمات', '["قانون هنري","ذائبية الغاز","الضغط"]'::jsonb, null, '[35,36]'::jsonb, 'مغطى', 'نص قانون هنري: «تتناسب ذائبية الغاز في سائل (S) تناسبًا طرديًا مع ضغط الغاز (P) الموجود فوق السائل عند ثبوت درجة الحرارة»، أي S1/P1 = S2/P2. ويبقى ناتج قسمة الذائبية على الضغط ثابتًا عند درجة حرارة معينة.', null, 'approved', '2026-10-16'::timestamptz),
(401307, 4013, 'K3-C1-L3-O07', null, 7, 'أن يفسر الطالب سبب اندفاع غاز ثاني اكسيد الكربون من علبة المشروب الغازي عند فتحها.', 'أن يفسّر الطالب سبب تصاعد غاز ثاني أكسيد الكربون من علبة المشروب الغازي عند فتحها.', '[]'::jsonb, 'أن يفسّر الطالب سبب تصاعد غاز ثاني أكسيد الكربون من علبة المشروب الغازي عند فتحها.', 'إضافة همزة «أكسيد»، و«تصاعد» أقرب إلى لفظ الكتاب.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["قانون هنري","الضغط","ذائبية الغاز"]'::jsonb, null, '[35,36]'::jsonb, 'مغطى', 'المشروب يحتوي CO2 مذابًا تحت ضغط أعلى من الضغط الجوي. عند الفتح يقل الضغط فوق السائل فتقل ذائبية CO2، فتتصاعد الفقاعات وتتطاير حتى يفقد المحلول الغاز تقريبًا (الشكل 1-17). يُفسَّر ذلك بقانون هنري.', null, 'approved', '2026-10-16'::timestamptz),
(401308, 4013, 'K3-C1-L3-O08', null, 8, 'أن يحسب الطالب ذائبية غاز في سائل', 'أن يحسب الطالب ذائبية غاز في سائل عند ضغط معين باستعمال قانون هنري.', '[]'::jsonb, 'أن يحسب الطالب ذائبية غاز في سائل عند ضغط معين باستعمال قانون هنري.', 'تحديد الأداة (قانون هنري) والشرط (ضغط معين) كما في أمثلة الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["قانون هنري","الذائبية","الضغط"]'::jsonb, null, '[36,37]'::jsonb, 'مغطى', 'S2 = S1 × P2/P1. مثال 1-5: S1 = 0.85 g/L عند 4.0 atm، فتكون الذائبية عند 1.0 atm هي S2 = 0.21 g/L. مسائل 36–38 (منها إيجاد الضغط بمعلومية الذائبية).', null, 'approved', '2026-10-16'::timestamptz),
(401309, 4013, 'K3-C1-L3-O09', null, 9, 'أن يعرف الطالب المحلول غير المشبع', 'أن يعرّف الطالب المحلول غير المشبع.', '[]'::jsonb, 'أن يعرّف الطالب المحلول غير المشبع.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["المحلول غير المشبع","المحلول المشبع","الذائبية"]'::jsonb, null, '[33]'::jsonb, 'مغطى', 'المحلول غير المشبع يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين، أي يمكن إذابة مزيد من المذاب فيه. ملاحظة: المشبع وفوق المشبع والذائبية (ص 33–35) لا يقابلها أهداف.', null, 'approved', '2026-10-16'::timestamptz),
(401310, 4013, 'K3-C1-L3-O10', null, 10, 'أن يفسّر الطالب كون عملية الذوبان طاردة للطاقة أو ماصة لها اعتمادًا على مفهوم حرارة الذوبان.', 'أن يفسّر الطالب كون عملية الذوبان طاردة للطاقة أو ماصة لها اعتمادًا على مفهوم حرارة الذوبان.', '[]'::jsonb, 'أن يفسّر الطالب كون عملية الذوبان طاردة للطاقة أو ماصة لها اعتمادًا على مفهوم حرارة الذوبان.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["حرارة الذوبان","طاقة الشبكة البلورية","طاقة التميه","طارد للطاقة","ماص للطاقة"]'::jsonb, null, '[32]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يلزم طاقة للتغلب على قوى التجاذب بين جسيمات المذاب (طاقة الشبكة البلورية U°) وبين جسيمات المذيب، فكلتا الخطوتين ماصة للطاقة، وعند تجاذب جسيمات المذيب والمذاب تنطلق طاقة التميه (Hhyd) فهذه الخطوة طاردة. يُسمى التغير الكلي للطاقة خلال تكون المحلول حرارة الذوبان. مثال: ذوبان نترات الأمونيوم في الماء يجعل الوعاء باردًا (ماص)، وذوبان كلوريد الكالسيوم يجعله ساخنًا (طارد). سؤال «ماذا قرأت؟» يطلب التفسير.', null, 'approved', '2026-10-16'::timestamptz),
(401311, 4013, 'K3-C1-L3-O11', null, 11, 'أن يتنبأ الطالب بإمكانية ذوبان مادة في مذيب معين بتطبيق قاعدة «المذيب يذيب شبيهه» اعتمادًا على القطبية.', 'أن يتنبأ الطالب بإمكانية ذوبان مادة في مذيب معين بتطبيق قاعدة «المذيب يذيب شبيهه» اعتمادًا على القطبية.', '[]'::jsonb, 'أن يتنبأ الطالب بإمكانية ذوبان مادة في مذيب معين بتطبيق قاعدة «المذيب يذيب شبيهه» اعتمادًا على القطبية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وتعميمات', '["المذيب يذيب شبيهه","القطبية","القوى بين الجزيئية","المذيب غير القطبي"]'::jsonb, null, '[29,31]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). «المذيب يذيب شبيهه like dissolves like» قاعدة عامة تُستعمل لتحديد ما إذا كانت عملية الذوبان تحدث في مذيب معين، ولتحديد تماثل المذيب والمذاب تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها (ص 29). مثال: الزيت يتكون من الكربون والهيدروجين ولا يكوّن محلولًا مع الماء لأن قوى التجاذب بين جزيئات الماء القطبية وجزيئات الزيت غير القطبية ضعيفة، لذا يذوب الزيت في مذيب غير قطبي (ص 31).', null, 'approved', '2026-10-16'::timestamptz),
(401312, 4013, 'K3-C1-L3-O12', null, 12, 'أن يوضّح الطالب أثر درجة حرارة المذيب في سرعة الذوبان.', 'أن يوضّح الطالب أثر درجة حرارة المذيب في سرعة الذوبان.', '[]'::jsonb, 'أن يوضّح الطالب أثر درجة حرارة المذيب في سرعة الذوبان.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["سرعة الذوبان","درجة الحرارة","التصادمات"]'::jsonb, null, '[32]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يبين الشكل 1-12 ثلاث طرائق لزيادة التصادمات وسرعة الذوبان: التحريك، وزيادة مساحة السطح، ورفع درجة حرارة المذيب. تتأثر سرعة الذوبان بدرجة الحرارة؛ فالمذيب الساخن يذيب كمية أكبر من المذاب مقارنة بالبارد ويذيب أسرع، فالسكر المطحون يذوب بسرعة كبيرة جدًّا في الشاي الساخن مقارنة بالشاي المثلج. (يقابل هدفي التحريك ومساحة السطح القائمين، والعامل الثالث بلا هدف.)', null, 'approved', '2026-10-16'::timestamptz),
(401313, 4013, 'K3-C1-L3-O13', null, 13, 'أن يعرّف الطالب الذائبية.', 'أن يعرّف الطالب الذائبية.', '[]'::jsonb, 'أن يعرّف الطالب الذائبية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الذائبية","المذاب","المذيب","درجة الحرارة"]'::jsonb, null, '[33]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تُعرّف الذائبية بأنها أقصى كمية من المذاب يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة معينة، وتعتمد على طبيعة كل من المذاب والمذيب. وحدتها في الجدول 1-4: g/100 g H2O، وفي مثال قانون هنري g/L. السؤال 40 في التقويم: «عرّف الذائبية».', null, 'approved', '2026-10-16'::timestamptz),
(401314, 4013, 'K3-C1-L3-O14', null, 14, 'أن يعرّف الطالب المحلول المشبع مفسّرًا حالة الاتزان الديناميكي بين الذوبان والتبلور فيه.', 'أن يعرّف الطالب المحلول المشبع مفسّرًا حالة الاتزان الديناميكي بين الذوبان والتبلور فيه.', '[]'::jsonb, 'أن يعرّف الطالب المحلول المشبع مفسّرًا حالة الاتزان الديناميكي بين الذوبان والتبلور فيه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المحلول المشبع","الاتزان الديناميكي","سرعة الذوبان","سرعة التبلور"]'::jsonb, null, '[33]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). مع زيادة عدد الجسيمات الذائبة يزداد تصادمها ببقية البلورة فيلتصق بعضها بسطحها (يتبلور)، فتزداد سرعة التبلور حتى تتساوى سرعتا الذوبان والتبلور، ويصل المحلول إلى حالة اتزان ديناميكي إذا بقيت درجة الحرارة ثابتة (الشكل 1-13). المحلول المشبع يحتوي على أكبر كمية من المذاب ذائبة في كمية محددة من المذيب عند درجة حرارة وضغط معينين، وتبقى فيه كمية المذاب الذائبة ثابتة.', null, 'approved', '2026-10-16'::timestamptz),
(401315, 4013, 'K3-C1-L3-O15', null, 15, 'أن يعرّف الطالب المحلول فوق المشبع.', 'أن يعرّف الطالب المحلول فوق المشبع.', '[]'::jsonb, 'أن يعرّف الطالب المحلول فوق المشبع.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المحلول فوق المشبع","المحلول المشبع"]'::jsonb, null, '[34]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يحتوي المحلول فوق المشبع على كمية أكبر من المادة المذابة مقارنة بمحلول مشبع عند درجة الحرارة نفسها. المصطلح من المفردات الجديدة للدرس 1-3.', null, 'approved', '2026-10-16'::timestamptz),
(401316, 4013, 'K3-C1-L3-O16', null, 16, 'أن يصف الطالب طريقة تحضير محلول فوق مشبع، ويفسّر ما يحدث عند إضافة نواة تبلور إليه.', 'أن يصف الطالب طريقة تحضير محلول فوق مشبع، ويفسّر ما يحدث عند إضافة نواة تبلور إليه.', '[]'::jsonb, 'أن يصف الطالب طريقة تحضير محلول فوق مشبع، ويفسّر ما يحدث عند إضافة نواة تبلور إليه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'إجراءات', '["المحلول فوق المشبع","نواة التبلور","التبريد البطيء","استمطار الغيوم"]'::jsonb, null, '[34,35,37]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). لعمل محلول فوق مشبع يُحضّر محلول مشبع عند درجة حرارة عالية ثم يبرّد تدريجيًّا وببطء، فيسمح التبريد البطيء للمادة الزائدة بأن تبقى مذابة. المحاليل فوق المشبعة غير ثابتة؛ فعند إضافة نواة تبلور تترسب المادة المذابة الزائدة بسرعة (الشكل 1-15، محلول السكروز)، وقد يحدث التبلور بكشط الوعاء أو بالحركة أو الرج. تطبيقات: استمطار الغيوم باستعمال يوديد الفضة AgI، وسكر النبات، والرواسب المعدنية حول الينابيع الحارة كعيون الليث (الشكل 1-16). السؤال 43 في التقويم: «ماذا يحدث إذا أُضيفت نواة تبلور إلى محلول فوق مشبع؟».', null, 'approved', '2026-10-16'::timestamptz),
(401317, 4013, 'K3-C1-L3-O17', null, 17, 'أن يستعمل الطالب منحنيات الذائبية وجداولها لتحديد ذائبية مادة عند درجة حرارة معينة ومقارنة أثر الحرارة في ذائبية المواد المختلفة.', 'أن يستعمل الطالب منحنيات الذائبية وجداولها لتحديد ذائبية مادة عند درجة حرارة معينة ومقارنة أثر الحرارة في ذائبية المواد المختلفة.', '[]'::jsonb, 'أن يستعمل الطالب منحنيات الذائبية وجداولها لتحديد ذائبية مادة عند درجة حرارة معينة ومقارنة أثر الحرارة في ذائبية المواد المختلفة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["منحنى الذائبية","الذائبية","درجة الحرارة"]'::jsonb, null, '[33,34,37]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الشكل 1-14 منحنيات ذائبية CaCl2 وKCl وNaCl وKClO3 وCe2(SO4)3 بين 0 و100 °C، و«اختبار الرسم البياني»: حدد ذائبية NaCl عند 80 °C. الجدول 1-4 «الذائبية في الماء عند درجات حرارة مختلفة» (g/100 g H2O) عند 0 و20 و60 و100 °C؛ مثال: السكروز 203.9 g عند 20 °C و487.2 g عند 100 °C (زيادة نحو 140%)، وCaCl2 من 64 g عند 10 °C إلى نحو 100 g عند 27 °C، وكبريتات السيريوم تقل ذائبيتها بزيادة الحرارة. السؤال 44 في التقويم: رسم منحنيات ذائبية Al2(SO4)3 وLi2SO4 وKCl من الجدول 1-4 وتحديد أكثرها تأثرًا بالحرارة.', null, 'approved', '2026-10-16'::timestamptz),
(401318, 4013, 'K3-C1-L3-O18', null, 18, 'أن يفسّر الطالب نقصان ذائبية الغازات في السوائل بارتفاع درجة الحرارة.', 'أن يفسّر الطالب نقصان ذائبية الغازات في السوائل بارتفاع درجة الحرارة.', '[]'::jsonb, 'أن يفسّر الطالب نقصان ذائبية الغازات في السوائل بارتفاع درجة الحرارة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["ذائبية الغازات","الطاقة الحركية","درجة الحرارة"]'::jsonb, null, '[32,34,35]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تقل ذائبية غازي الأكسجين وثاني أكسيد الكربون عند درجات الحرارة المرتفعة مقارنة بالمنخفضة، وهذا سلوك متوقع لجميع الغازات المذابة في المذيبات السائلة؛ لأن الطاقة الحركية لجسيمات الغاز تسمح لها بالتحرر من المحلول بسهولة أكبر عند درجات الحرارة المرتفعة. بيانات الجدول 1-4: CO2 من 1.713 إلى 0.359 وO2 من 0.048 إلى 0.019 (من 0 إلى 60 °C)، وNH3 من 1130 إلى 200. لذلك تفقد المشروبات الغازية طعمها اللاذع أسرع عند درجة حرارة الغرفة (ص 32).', null, 'approved', '2026-10-16'::timestamptz),
(401401, 4014, 'K3-C1-L4-O01', null, 1, 'أن يعرف الطالب الخواص الجامعة للمحاليل', 'أن يعرّف الطالب الخواص الجامعة للمحاليل.', '[]'::jsonb, 'أن يعرّف الطالب الخواص الجامعة للمحاليل.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["الخواص الجامعة","عدد جسيمات المذاب"]'::jsonb, null, '[38]'::jsonb, 'مغطى', 'الخواص الجامعة هي «الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها». الفكرة الرئيسة: «تعتمد الخواص الجامعة على عدد جسيمات المذاب في المحلول».', null, 'approved', '2026-10-16'::timestamptz),
(401402, 4014, 'K3-C1-L4-O02', null, 2, 'أن يعدد الطالب الخواص الجامعة للمحاليل', 'أن يعدّد الطالب الخواص الجامعة الأربع للمحاليل.', '[]'::jsonb, 'أن يعدّد الطالب الخواص الجامعة الأربع للمحاليل.', 'تحديد عدد الخواص (أربع) ليكون الهدف قابلًا للقياس.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الانخفاض في الضغط البخاري","الارتفاع في درجة الغليان","الانخفاض في درجة التجمد","الضغط الأسموزي"]'::jsonb, null, '[38,39,40,41,44]'::jsonb, 'مغطى', 'الخواص الجامعة: الانخفاض في الضغط البخاري، والارتفاع في درجة الغليان، والانخفاض في درجة التجمد، والضغط الأسموزي.', null, 'approved', '2026-10-16'::timestamptz),
(401403, 4014, 'K3-C1-L4-O03', null, 3, 'أن يوضح الطالب أثر التركيز على درجة الغليان', 'أن يوضّح الطالب أثر تركيز المحلول (مولاليته) في الارتفاع في درجة غليانه.', '[]'::jsonb, 'أن يوضّح الطالب أثر تركيز المحلول (مولاليته) في الارتفاع في درجة غليانه.', 'تصحيح حرف الجر («في» بدل «على») وتحديد نوع التركيز المستعمل في الكتاب (المولالية).', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["الارتفاع في درجة الغليان","المولالية","Kb"]'::jsonb, null, '[40]'::jsonb, 'مغطى', 'قيمة الارتفاع في درجة الغليان ΔTb تتناسب طرديًا مع مولالية المحلول: ΔTb = Kb·m. كلما زاد عدد جسيمات المذاب زاد الارتفاع. Kb للماء = 0.512 °C/m، فمحلول 1 m من مذاب غير متطاير وغير متأين يغلي عند 100.512 °C. المواد المتأينة تُحسب بالمولالية الفعلية للجسيمات.', null, 'approved', '2026-10-16'::timestamptz),
(401404, 4014, 'K3-C1-L4-O04', null, 4, 'أن يفسر الطالب درجة غليان المحلول أعلى من درجة غليان المذيب النقي', 'أن يفسّر الطالب ارتفاع درجة غليان المحلول عن درجة غليان المذيب النقي.', '[]'::jsonb, 'أن يفسّر الطالب ارتفاع درجة غليان المحلول عن درجة غليان المذيب النقي.', 'العبارة الأصلية ناقصة («يفسر درجة غليان المحلول أعلى...»)؛ أعيدت صياغتها لتكون سليمة.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["الارتفاع في درجة الغليان","الضغط البخاري","المذاب غير المتطاير"]'::jsonb, null, '[39,40]'::jsonb, 'مغطى', 'المذاب غير المتطاير يقلل الضغط البخاري للمذيب لأن جسيماته تشغل جزءًا من سطح السائل. السائل يغلي عندما يعادل ضغطه البخاري الضغط الجوي، فيلزم تسخين المحلول إلى درجة أعلى ليتساوى ضغطه البخاري مع الضغط الجوي. والفرق بين درجتي الغليان هو الارتفاع في درجة الغليان.', null, 'approved', '2026-10-16'::timestamptz),
(401405, 4014, 'K3-C1-L4-O05', null, 5, 'أن يحسب الطالب درجة الغليان ودرجة تجمد محلول في مذيب', 'أن يحسب الطالب درجة غليان محلول ودرجة تجمده باستعمال العلاقتين ΔTb = Kb·m وΔTf = Kf·m.', '["أن يحسب الطالب درجة غليان محلول باستعمال العلاقة ΔTb = Kb·m.","أن يحسب الطالب درجة تجمد محلول باستعمال العلاقة ΔTf = Kf·m."]'::jsonb, 'أن يحسب الطالب درجة غليان محلول ودرجة تجمده باستعمال العلاقتين ΔTb = Kb·m وΔTf = Kf·m.', 'الهدف يجمع حسابين لخاصيتين مختلفتين؛ يحسن فصلهما مع تحديد العلاقات. وعبارة «محلول في مذيب» زائدة.', 'تقسيم', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["ΔTb = Kb·m","ΔTf = Kf·m","المولالية","المواد المتأينة"]'::jsonb, null, '[40,42,43]'::jsonb, 'مغطى', 'Kb للماء 0.512 °C/m وKf للماء 1.86 °C/m (الجدولان 1-5 و1-6). مثال 1-6: NaCl بتركيز 0.029 m مادة متأينة قوية، فالمولالية الفعلية 0.058 m، وΔTb = 0.030 °C فـTb = 100.030 °C، وΔTf = 0.11 °C فـTf = -0.11 °C. مسائل 45–47.', null, 'approved', '2026-10-16'::timestamptz),
(401406, 4014, 'K3-C1-L4-O06', null, 6, 'أن يعرف الطالب الضغط الأسموزي', 'أن يعرّف الطالب الضغط الأسموزي.', '[]'::jsonb, 'أن يعرّف الطالب الضغط الأسموزي.', 'ضبط الفعل «يعرّف» بالشدة لرفع اللبس مع «يعرِف».', 'إملائي', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["الخاصية الأسموزية","الضغط الأسموزي","الغشاء شبه المنفذ"]'::jsonb, null, '[44]'::jsonb, 'مغطى', 'الخاصية الأسموزية هي انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى الأعلى تركيزًا. الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز (الشكل 1-22). ويعتمد على عدد جسيمات المذاب في كمية محددة من المحلول، فهو خاصية جامعة.', null, 'approved', '2026-10-16'::timestamptz),
(401407, 4014, 'K3-C1-L4-O07', null, 7, 'أن يميّز الطالب بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة.', 'أن يميّز الطالب بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة.', '[]'::jsonb, 'أن يميّز الطالب بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المواد المتأينة القوية","المواد المتأينة الضعيفة","المواد غير المتأينة","التوصيل الكهربائي"]'::jsonb, null, '[38,39]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). المواد التي تتأين في الماء وتوصل محاليلها التيار الكهربائي تسمى مواد متأينة (إلكتروليتية)، والتي لا توصله مواد غير متأينة. المواد المتأينة التي تنتج أيونات كثيرة في المحلول متأينة قوية، والتي تنتج عددًا قليلًا من الأيونات متأينة ضعيفة. الشكل 1-18: محلول NaCl موصل جيد للكهرباء، ومحلول السكروز لا يوصل التيار. السكروز مادة غير متأينة تذوب جزيئاتها ولا تتفكك.', null, 'approved', '2026-10-16'::timestamptz),
(401408, 4014, 'K3-C1-L4-O08', null, 8, 'أن يحدّد الطالب عدد مولات جسيمات المذاب الناتجة عن إذابة مادة متأينة، ويتنبأ بأثرها النسبي في الخواص الجامعة مقارنة بالمواد غير المتأينة.', 'أن يحدّد الطالب عدد مولات جسيمات المذاب الناتجة عن إذابة مادة متأينة، ويتنبأ بأثرها النسبي في الخواص الجامعة مقارنة بالمواد غير المتأينة.', '[]'::jsonb, 'أن يحدّد الطالب عدد مولات جسيمات المذاب الناتجة عن إذابة مادة متأينة، ويتنبأ بأثرها النسبي في الخواص الجامعة مقارنة بالمواد غير المتأينة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'مبادئ وتعميمات', '["عدد جسيمات المذاب","المولالية الفعالة","المواد المتأينة","المواد غير المتأينة"]'::jsonb, null, '[39,43]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). إذابة 1 mol من NaCl في 1 kg من الماء لا تنتج محلولًا 1 m من الجسيمات بل 2 mol (Na+ وCl-) وفق NaCl(s) → Na+(aq) + Cl-(aq)، بينما يحتوي محلول السكروز 1 m على 1 mol فقط من الجزيئات. تأثير 1 mol من المواد غير المتأينة (الجلوكوز، السكروز، الإيثانول) واحد في الضغط البخاري، ويزداد تأثير 1 mol من NaCl وNa2SO4 وAlCl3 بتزايد أعداد الأيونات. مثال 1-6: NaCl بتركيز 0.029 m يعطي مولالية جسيمات 0.058 m.', null, 'approved', '2026-10-16'::timestamptz),
(401409, 4014, 'K3-C1-L4-O09', null, 9, 'أن يفسّر الطالب الانخفاض في الضغط البخاري للمحلول المحتوي على مذاب غير متطاير مقارنة بالمذيب النقي.', 'أن يفسّر الطالب الانخفاض في الضغط البخاري للمحلول المحتوي على مذاب غير متطاير مقارنة بالمذيب النقي.', '[]'::jsonb, 'أن يفسّر الطالب الانخفاض في الضغط البخاري للمحلول المحتوي على مذاب غير متطاير مقارنة بالمذيب النقي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["الضغط البخاري","الانخفاض في الضغط البخاري","المذاب غير المتطاير"]'::jsonb, null, '[39,44]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الضغط البخاري هو الضغط الناتج عن بخار السائل عندما يكون في حالة اتزان ديناميكي مع سائله في وعاء مغلق. إضافة مذاب غير متطاير تقلل الضغط البخاري للمذيب، لأن جسيمات المذاب تشغل جزءًا من سطح السائل فيقل عدد جسيمات المذيب التي تتبخر (الشكل 1-19 a وb). وكلما ازداد عدد جسيمات المذاب قل الضغط البخاري، فالانخفاض في الضغط البخاري خاصية جامعة. خلاصة الدرس: «تقلل المواد المذابة غير المتطايرة الضغط البخاري للمحلول».', null, 'approved', '2026-10-16'::timestamptz),
(401410, 4014, 'K3-C1-L4-O10', null, 10, 'أن يفسّر الطالب انخفاض درجة تجمد المحلول عن درجة تجمد المذيب النقي.', 'أن يفسّر الطالب انخفاض درجة تجمد المحلول عن درجة تجمد المذيب النقي.', '[]'::jsonb, 'أن يفسّر الطالب انخفاض درجة تجمد المحلول عن درجة تجمد المذيب النقي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["الانخفاض في درجة التجمد","ΔTf","مخطط تغير الحالة"]'::jsonb, null, '[41,44]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). عند التجمد تترتب جسيمات المذيب في بنية أكثر تنظيمًا في الحالة الصلبة، أما في المحلول فتعمل جسيمات المذاب على إضعاف قوى التجاذب بين جسيمات المذيب، مما يمنع المذيب من الوصول إلى الحالة الصلبة عند درجة تجمده، فتكون درجة تجمد المحلول دائمًا أقل من درجة تجمد المذيب النقي. الانخفاض في درجة التجمد ΔTf هو درجة تجمد المذيب النقي مطروحًا منها درجة تجمد المحلول. الشكل 1-20 مخطط تغير الحالة للماء النقي والمحلول المائي، ونطاق الحالة السائلة للمحلول أكبر منه للماء النقي، و«اختبار الرسم البياني» يطلب تفسير الفرق بين الخطين المتصل والمتقطع. خلاصة الدرس: «يكون الانخفاض في درجة التجمد للمحلول أقل من درجة تجمد المذيب النقي».', null, 'approved', '2026-10-16'::timestamptz),
(401411, 4014, 'K3-C1-L4-O11', null, 11, 'أن يذكر الطالب تطبيقات حياتية للانخفاض في درجة التجمد.', 'أن يذكر الطالب تطبيقات حياتية للانخفاض في درجة التجمد.', '[]'::jsonb, 'أن يذكر الطالب تطبيقات حياتية للانخفاض في درجة التجمد.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الانخفاض في درجة التجمد","إذابة الجليد بالأملاح","صنع الآيس كريم"]'::jsonb, null, '[41]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الشكل 1-21: إضافة الأملاح إلى الجليد تقلل درجة تجمده فينصهر الجليد على الطرق، وإضافة الملح إلى الجليد عند صنع الآيس كريم تقلل درجة التجمد فيتجمد الآيس كريم. وفي «الكيمياء في واقع الحياة»: المحافظة على التركيز الملحي مهمة للأسماك في المياه المالحة؛ فوجود الملح في المناطق القطبية من المحيط ضروري لمنع المياه من التجمد، مما يسمح بالمحافظة على الحياة البحرية.', null, 'approved', '2026-10-16'::timestamptz),
(401412, 4014, 'K3-C1-L4-O12', null, 12, 'أن يفسّر الطالب الخاصية الأسموزية موضحًا اتجاه انتقال جزيئات المذيب عبر الغشاء شبه المنفذ.', 'أن يفسّر الطالب الخاصية الأسموزية موضحًا اتجاه انتقال جزيئات المذيب عبر الغشاء شبه المنفذ.', '[]'::jsonb, 'أن يفسّر الطالب الخاصية الأسموزية موضحًا اتجاه انتقال جزيئات المذيب عبر الغشاء شبه المنفذ.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الخاصية الأسموزية","الغشاء شبه المنفذ","الانتشار","المحلول المخفف","المحلول المركز"]'::jsonb, null, '[44]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الانتشار هو اختلاط الغازات أو السوائل الناتج عن حركتها العشوائية، أما الخاصية الأسموزية فهي انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا. الأغشية شبه المنفذة حواجز تسمح لبعض الجسيمات بالعبور، وتحيط بالخلايا الحية جميعها. في الشكل 1-22 تتحرك جزيئات الماء في الاتجاهين لكن صافي حركتها من المخفف إلى المركز، وجزيئات المذاب لا تعبر. للخاصية الأسموزية دور مهم في العمليات الحيوية كامتصاص الغذاء في النباتات. (الهدف القائم L4-O06 يقتصر على تعريف الضغط الأسموزي.)', null, 'approved', '2026-10-16'::timestamptz),
(402101, 4021, 'K3-C2-L1-O01', null, 1, 'أن يعدد الطالب خواص الاحماض الفيزيائية', 'أن يعدّد الطالب الخواص الفيزيائية للأحماض والقواعد.', '[]'::jsonb, 'أن يعدّد الطالب الخواص الفيزيائية للأحماض والقواعد.', 'تصحيح الهمزة («الأحماض») وإضافة القواعد لأن الكتاب يعرض خواص الصنفين معًا ضمن الهدف نفسه.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الخواص الفيزيائية","الطعم اللاذع","الطعم المر والملمس الزلق","التوصيل الكهربائي"]'::jsonb, null, '[56,57]'::jsonb, 'مغطى', 'الكتاب: المحاليل الحمضية طعمها لاذع (المشروبات الغازية لاحتوائها H2CO3 وH3PO4، الليمون لاحتوائه حمضي الستريك والأسكوربيك، الخل)، والقاعدية طعمها مر وملمسها زلق (الصابون)؛ ومن الخواص الأخرى توصيل محاليلها للكهرباء بسبب تأينها، والماء النقي غير موصل. مع تحذير: لا تحاول تعرّف حمض أو قاعدة بتذوقها أو لمسها.', null, 'approved', '2026-10-16'::timestamptz),
(402102, 4021, 'K3-C2-L1-O02', null, 2, 'أن يعدد الطالب خواص الاحماض الكيميائية', 'أن يعدّد الطالب الخواص الكيميائية للأحماض والقواعد.', '[]'::jsonb, 'أن يعدّد الطالب الخواص الكيميائية للأحماض والقواعد.', 'تصحيح الهمزة وإضافة القواعد (تأثيرها في ورق تبّاع الشمس) اتساقًا مع الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الخواص الكيميائية","ورق تبّاع الشمس","تفاعل الأحماض مع الفلزات","تفاعل الأحماض مع الكربونات"]'::jsonb, null, '[57]'::jsonb, 'مغطى', 'الأحماض تحوّل ورق تبّاع الشمس الأزرق إلى الأحمر والقواعد تحوّل الأحمر إلى الأزرق؛ تتفاعل الأحماض مع Mg وZn منتجة غاز H2 (Zn + 2HCl → ZnCl2 + H2)، ومع الكربونات والكربونات الهيدروجينية منتجة CO2 (NaHCO3 + CH3COOH → CH3COONa + H2O + CO2)، ويُستعمل HCl لتعرّف الصخر الجيري CaCO3.', null, 'approved', '2026-10-16'::timestamptz),
(402103, 4021, 'K3-C2-L1-O03', null, 3, 'أن يفسر الطالب محلول حمض الكلور موصل جيد للكهرباء', 'أن يفسّر الطالب توصيل محلول حمض الهيدروكلوريك للتيار الكهربائي جيدًا.', '[]'::jsonb, 'أن يفسّر الطالب توصيل محلول حمض الهيدروكلوريك للتيار الكهربائي جيدًا.', 'تصحيح اسم الحمض («حمض الكلور» ← حمض الهيدروكلوريك) وإكمال التركيب النحوي للعبارة.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["التوصيل الكهربائي","التأين الكلي","الحمض القوي","أيون الهيدرونيوم"]'::jsonb, null, '[57,59,66,67]'::jsonb, 'مغطى', 'المحاليل الحمضية توصل الكهرباء بسبب تأينها؛ يتأين HCl في الماء كليًا (HCl + H2O → H3O+ + Cl−) فيحتوي المحلول على عدد كبير من الأيونات، لذا يتوهج المصباح بقوة في محلول HCl تركيزه 0.10 M مقارنة بتوهج خافت في CH3COOH بالتركيز نفسه (الشكلان 2-11 و2-12).', null, 'approved', '2026-10-16'::timestamptz),
(402104, 4021, 'K3-C2-L1-O04', null, 4, 'أن يفسر الطالب محلول هيدروكسيد الصوديوم موصل جيد للكهرباء', 'أن يفسّر الطالب توصيل محلول هيدروكسيد الصوديوم للتيار الكهربائي جيدًا.', '[]'::jsonb, 'أن يفسّر الطالب توصيل محلول هيدروكسيد الصوديوم للتيار الكهربائي جيدًا.', 'إكمال التركيب النحوي للعبارة (يفسّر توصيلَ...).', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["التوصيل الكهربائي","التفكك","القاعدة القوية","أيون الهيدروكسيد"]'::jsonb, null, '[57,59,70]'::jsonb, 'مغطى', 'إضافة قاعدة إلى الماء تنتج أيونات تجعل المحلول موصلًا؛ NaOH مركب أيوني يتفكك كليًا في الماء (NaOH → Na+ + OH−) فهو قاعدة قوية، ويعتمد توصيل القاعدة للتيار على مقدار ما تطلقه من أيونات OH− في المحلول.', null, 'approved', '2026-10-16'::timestamptz),
(402105, 4021, 'K3-C2-L1-O05', null, 5, 'أن يعرف الطالب المحلول الحمضي', 'أن يعرّف الطالب المحلول الحمضي.', '[]'::jsonb, 'أن يعرّف الطالب المحلول الحمضي.', 'إضافة الشدة في «يعرّف».', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["المحلول الحمضي","المحلول القاعدي","المحلول المتعادل","[H+] و[OH−]"]'::jsonb, null, '[58]'::jsonb, 'مغطى', 'المحلول الحمضي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد، والقاعدي يحتوي على أيونات هيدروكسيد أكثر، والمتعادل يحتوي تركيزين متساويين منهما (الشكل 2-3)؛ وينتج الماء النقي أعدادًا متساوية من H+ وOH− بالتأين الذاتي: H2O + H2O ⇌ H3O+ + OH−.', null, 'approved', '2026-10-16'::timestamptz),
(402106, 4021, 'K3-C2-L1-O06', null, 6, 'أن يعرف الطالب الحمض حسب نموذج أرهينيوس', 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية أرهينيوس.', '[]'::jsonb, 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية أرهينيوس.', 'إضافة الشدة، واستعمال «نظرية» كما في الكتاب، وإضافة القاعدة لأن التعريفين متلازمان في الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["نظرية أرهينيوس","حمض أرهينيوس","قاعدة أرهينيوس"]'::jsonb, null, '[59,64]'::jsonb, 'مغطى', 'نظرية أرهينيوس (1883م): الحمض مادة تحتوي على الهيدروجين وتتأين في المحاليل المائية منتجة أيونات الهيدروجين (HCl → H+ + Cl−)، والقاعدة مادة تحتوي على مجموعة الهيدروكسيد وتتفكك في المحلول المائي منتجة أيون الهيدروكسيد (NaOH → Na+ + OH−)؛ الجدول 2-2: حمض أرهينيوس منتج H+ وقاعدته منتجة OH−.', null, 'approved', '2026-10-16'::timestamptz),
(402107, 4021, 'K3-C2-L1-O07', null, 7, 'أن يعدد الطالب قصور نموذج أرهينيوس', 'أن يوضّح الطالب قصور نظرية أرهينيوس في تفسير سلوك بعض القواعد.', '[]'::jsonb, 'أن يوضّح الطالب قصور نظرية أرهينيوس في تفسير سلوك بعض القواعد.', '«يعدّد» لا تناسب لأن الكتاب يقدّم قصورًا رئيسًا واحدًا، و«نظرية» بدل «نموذج» اتساقًا مع الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["نظرية أرهينيوس","قصور النظرية","الأمونيا","كربونات الصوديوم"]'::jsonb, null, '[59,65]'::jsonb, 'مغطى', 'على الرغم من أن نظرية أرهينيوس تفسر كثيرًا من المحاليل، فإن الأمونيا NH3 وكربونات الصوديوم Na2CO3 لا تحتويان على مجموعة الهيدروكسيد ومع ذلك تنتجان OH− عند ذوبانهما في الماء (Na2CO3 سبب قاعدية بحيرة ناترون في تنزانيا)، لذا احتاج العلماء نظرية أشمل؛ وفي التقويم سؤال عن سبب عدم تصنيف مركبات كثيرة تحتوي الهيدروجين أحماضًا لأرهينيوس.', null, 'approved', '2026-10-16'::timestamptz),
(402108, 4021, 'K3-C2-L1-O08', null, 8, 'أن يعرف الطالب الحمض حسب نظرية لوري – برونشتد', 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية برونستد – لوري.', '[]'::jsonb, 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية برونستد – لوري.', 'إضافة الشدة وإضافة القاعدة لتلازم التعريفين.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["نظرية برونستد – لوري","مانح أيون الهيدروجين","مستقبل أيون الهيدروجين"]'::jsonb, null, '[60,64]'::jsonb, 'مغطى', 'وفق برونستد – لوري الحمض هو المادة المانحة لأيون الهيدروجين H+ والقاعدة هي المادة المستقبلة له؛ مثال: HX + H2O ⇌ H3O+ + X− حيث يسلك الماء سلوك القاعدة. الأمونيا قاعدة برونستد – لوري وليست قاعدة أرهينيوس (NH3 + H2O ⇌ NH4+ + OH−).', null, 'approved', '2026-10-16'::timestamptz),
(402109, 4021, 'K3-C2-L1-O09', null, 9, 'أن يحدد الطالب القاعدة المقترنة للحمض', 'أن يحدّد الطالب القاعدة المرافقة (المقترنة) لحمض معلوم في معادلة برونستد – لوري.', '[]'::jsonb, 'أن يحدّد الطالب القاعدة المرافقة (المقترنة) لحمض معلوم في معادلة برونستد – لوري.', 'إضافة المصطلح المعتمد في الكتاب «المرافقة» وسياق الأداء.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مفاهيم', '["القاعدة المرافقة","الأزواج المترافقة","نظرية برونستد – لوري"]'::jsonb, null, '[60,61,63]'::jsonb, 'مغطى', 'القاعدة المرافقة هي المركب الكيميائي الذي ينتج عندما يمنح الحمض أيون الهيدروجين (HX → X−، HF → F−)؛ الجدول 2-1 يعطي أحماضًا شائعة وقواعدها المرافقة (HCl/Cl−، H2SO4/HSO4−، HSO4−/SO4 2−، H3PO4/H2PO4−، H2CO3/HCO3−، HCO3−/CO3 2− ...).', null, 'approved', '2026-10-16'::timestamptz),
(402110, 4021, 'K3-C2-L1-O10', null, 10, 'أن يحدد الطالب الحمض المقترن للقاعدة.', 'أن يحدّد الطالب الحمض المرافق (المقترن) لقاعدة معلومة في معادلة برونستد – لوري.', '[]'::jsonb, 'أن يحدّد الطالب الحمض المرافق (المقترن) لقاعدة معلومة في معادلة برونستد – لوري.', 'إضافة المصطلح المعتمد «المرافق» وسياق الأداء.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مفاهيم', '["الحمض المرافق","الأزواج المترافقة","أيون الهيدرونيوم","أيون الأمونيوم"]'::jsonb, null, '[60,61]'::jsonb, 'مغطى', 'الحمض المرافق هو المركب الكيميائي الذي ينتج عندما تستقبل القاعدة أيون الهيدروجين؛ H3O+ حمض مرافق للقاعدة H2O، وNH4+ حمض مرافق للقاعدة NH3، ويتكون الزوج المترافق من مادتين ترتبطان بمنح أو استقبال أيون هيدروجين واحد (تشبيه الأب والابن والكرة، الشكل 2-6).', null, 'approved', '2026-10-16'::timestamptz),
(402111, 4021, 'K3-C2-L1-O11', null, 11, 'أن يعرف الطالب الحمض حسب نظرية لويس', 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية لويس.', '[]'::jsonb, 'أن يعرّف الطالب الحمض والقاعدة وفق نظرية لويس.', 'إضافة الشدة وإضافة القاعدة لتلازم التعريفين.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["نظرية لويس","مستقبل زوج الإلكترونات","مانح زوج الإلكترونات"]'::jsonb, null, '[63,64]'::jsonb, 'مغطى', 'حمض لويس مادة مستقبلة لزوج من الإلكترونات (أيون أو جزيء فيه مدار ذري فارغ)، وقاعدة لويس مادة مانحة لزوج من الإلكترونات (لها زوج إلكترونات حر)، ونظرية لويس تشمل جميع أحماض وقواعد برونستد – لوري وغيرها.', null, 'approved', '2026-10-16'::timestamptz),
(402112, 4021, 'K3-C2-L1-O12', null, 12, 'أن يصنف الطالب المواد إلى حمض وقاعدة بموجب نظرية لويس', 'أن يصنّف الطالب المواد المتفاعلة إلى أحماض وقواعد وفق نظرية لويس.', '[]'::jsonb, 'أن يصنّف الطالب المواد المتفاعلة إلى أحماض وقواعد وفق نظرية لويس.', 'إضافة الشدة وتحسين الصياغة («وفق» بدل «بموجب»، الجمع).', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مفاهيم', '["حمض لويس","قاعدة لويس","تراكيب لويس"]'::jsonb, null, '[64,65]'::jsonb, 'مغطى', 'أمثلة الكتاب: H+ حمض لويس وF− قاعدة لويس في تكوين HF؛ BF3 حمض لويس (للبورون ستة إلكترونات تكافؤ ومدار فارغ) وNH3 قاعدة لويس في تكوين BF3NH3؛ SO3 حمض لويس وأيون O2− من MgO قاعدة لويس في SO3 + MgO → MgSO4؛ وسؤال تقويم عن PCl3.', null, 'approved', '2026-10-16'::timestamptz),
(402113, 4021, 'K3-C2-L1-O13', null, 13, 'أن يعرف الطالب المواد المترددة ( أمفوتيرية )', 'أن يعرّف الطالب المواد المترددة (الأمفوتيرية) مع ذكر أمثلة عليها.', '[]'::jsonb, 'أن يعرّف الطالب المواد المترددة (الأمفوتيرية) مع ذكر أمثلة عليها.', 'إضافة الشدة وتصويب الكتابة، وإضافة المثال لأن الكتاب يبني المفهوم على سلوك الماء.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["المواد المترددة (الأمفوتيرية)","الماء","أيون HCO3−"]'::jsonb, null, '[60,61]'::jsonb, 'مغطى', 'يسلك الماء سلوك القاعدة عند ذوبان HF فيه وسلوك الحمض عند ذوبان NH3 فيه، ويُسمى الماء والمواد الأخرى التي تستطيع أن تسلك سلوك الأحماض والقواعد مواد مترددة (أمفوتيرية) Amphoteric؛ وفي «ماذا قرأت؟» يُسأل كيف يكون HCO3− حمضًا وقاعدة في آن واحد.', null, 'approved', '2026-10-16'::timestamptz),
(402114, 4021, 'K3-C2-L1-O14', null, 14, 'أن يعرف الطالب أحماض أحادية البروتون', 'أن يعرّف الطالب الحمض الأحادي البروتون.', '[]'::jsonb, 'أن يعرّف الطالب الحمض الأحادي البروتون.', 'إضافة الشدة وضبط التركيب («الحمض الأحادي البروتون»).', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الحمض الأحادي البروتون","ذرة الهيدروجين القابلة للتأين","الكهروسالبية"]'::jsonb, null, '[62]'::jsonb, 'مغطى', 'الحمض الذي يستطيع أن يمنح أيون هيدروجين واحدًا فقط لكل جزيء يسمى حمضًا أحادي البروتون؛ وذرة الهيدروجين القابلة للتأين ترتبط بذرة عالية الكهروسالبية (O أو F) برابطة قطبية، لذا يتأين H واحد فقط من أربع ذرات في CH3COOH، والبنزين C6H6 ليس حمضًا (الشكل 2-9).', null, 'approved', '2026-10-16'::timestamptz),
(402115, 4021, 'K3-C2-L1-O15', null, 15, 'ان يذكر الطالب أمثلة على أحماض أحادية البروتون', 'أن يذكر الطالب أمثلة على الأحماض الأحادية البروتون.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على الأحماض الأحادية البروتون.', 'تصحيح الهمزة («أن»، «الأحماض»).', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الأحماض الأحادية البروتون","HCl","HF","HNO3","CH3COOH"]'::jsonb, null, '[62,63]'::jsonb, 'مغطى', 'أمثلة الكتاب: HCl، HF، حمض البيركلوريك HClO4، النيتريك HNO3، الهيدروبروميك HBr، الإيثانويك CH3COOH (تكتب صيغته CH3COOH تأكيدًا أن ذرة H واحدة فقط قابلة للتأين).', null, 'approved', '2026-10-16'::timestamptz),
(402116, 4021, 'K3-C2-L1-O16', null, 16, 'ان يذكر الطالب أمثلة على الاحماض متعددة البروتونات', 'أن يذكر الطالب أمثلة على الأحماض المتعددة البروتونات (الثنائية والثلاثية).', '[]'::jsonb, 'أن يذكر الطالب أمثلة على الأحماض المتعددة البروتونات (الثنائية والثلاثية).', 'تصحيح الهمزة، وتحديد نوعي الأحماض المتعددة كما في الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الأحماض المتعددة البروتونات","الأحماض الثنائية البروتونات","الأحماض الثلاثية البروتونات","التأين على خطوات"]'::jsonb, null, '[62,63]'::jsonb, 'مغطى', 'ثنائية البروتونات: H2SO4 وH2CO3 (ذرتا H قابلتان للتأين)؛ ثلاثية البروتونات: H3PO4 والبوريك H3BO3؛ ومصطلح «متعدد البروتونات» لأي حمض فيه أكثر من H قابلة للتأين، وتتأين جميعها على أكثر من خطوة (H3PO4 ⇌ H2PO4− ⇌ HPO4 2− ⇌ PO4 3−). الموضوع في الدرس 2-1 فعلًا.', null, 'approved', '2026-10-16'::timestamptz),
(402117, 4021, 'K3-C2-L1-O17', null, 17, 'أن يعرف الطالب أنهيدريد حمضي مع ذكر مثال', 'أن يعرّف الطالب الأنهيدريد الحمضي مع ذكر مثال عليه.', '[]'::jsonb, 'أن يعرّف الطالب الأنهيدريد الحمضي مع ذكر مثال عليه.', 'إضافة الشدة و«ال» التعريف وتحسين الصياغة.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["الأنهيدريد الحمضي","أكاسيد اللافلزات","ثاني أكسيد الكربون","المطر الحمضي"]'::jsonb, null, '[65]'::jsonb, 'مغطى', 'في «الربط مع علم الأرض» (الدرس 2-1): ثاني أكسيد الكربون أنهيدريد حمضي (حمض منزوع منه جزيء ماء)، وهو أكسيد يستطيع أن يتحد مع الماء ليكوّن حمضًا (CO2 + H2O → H2CO3) الذي يذيب الصخور الجيرية مكوّنًا الكهوف والهوابط والصواعد؛ وعمومًا تكوّن أكاسيد اللافلزات الأحماض (كذلك SO3 يكوّن H2SO4 في المطر الحمضي).', null, 'approved', '2026-10-16'::timestamptz),
(402118, 4021, 'K3-C2-L1-O18', null, 18, 'أن يعرف الطالب أنهيدريد قاعدي مع ذكر مثال', 'أن يوضّح الطالب تكوين أكاسيد الفلزات للقواعد عند اتحادها بالماء مع ذكر مثال.', '[]'::jsonb, 'أن يوضّح الطالب تكوين أكاسيد الفلزات للقواعد عند اتحادها بالماء مع ذكر مثال.', 'مصطلح «أنهيدريد قاعدي» لا يرد في الكتاب صراحةً؛ الكتاب يصف أكاسيد الفلزات التي تكوّن قواعد مع الماء.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["الأنهيدريد القاعدي","أكاسيد الفلزات","أكسيد الكالسيوم","هيدروكسيد الكالسيوم"]'::jsonb, null, '[65]'::jsonb, 'جزئي', 'الكتاب لا يستعمل مصطلح «أنهيدريد قاعدي» بل يذكر أن هناك أكاسيد أخرى تتحد مع الماء مكوّنة قواعد: أكسيد الكالسيوم CaO (الجير الحي) يكوّن عند ذوبانه في الماء هيدروكسيد الكالسيوم Ca(OH)2 (الجير المطفأ)، وعمومًا تكوّن أكاسيد العناصر الفلزية القواعد؛ يحتاج المصطلح نفسه إلى إثراء إن أُبقي.', null, 'approved', '2026-10-16'::timestamptz),
(402119, 4021, 'K3-C2-L1-O19', null, 19, 'أن يعرف الطالب ملح إبسوم', 'أن يتعرّف الطالب ملح إبسوم بصيغته واستعمالاته.', '[]'::jsonb, 'أن يتعرّف الطالب ملح إبسوم بصيغته واستعمالاته.', '«يعرّف» تحتاج إلى تحديد ما يُعرّف؛ الكتاب يقدّم صيغة الملح واستعمالاته ولا يقدّم تعريفًا اصطلاحيًا.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["ملح إبسوم","كبريتات الماغنسيوم المائية","MgSO4·7H2O"]'::jsonb, null, '[65]'::jsonb, 'مغطى', 'ملح إبسوم هو بلورات كبريتات الماغنسيوم MgSO4·7H2O الناتجة عن تفاعل SO3 مع MgO، وله استعمالات كثيرة منها تخفيف آلام العضلات، وهو مغذٍّ للنباتات. (الموضوع ضمن نظرية لويس في الدرس 2-1).', null, 'approved', '2026-10-16'::timestamptz),
(402120, 4021, 'K3-C2-L1-O20', null, 20, 'أن يوضح الطالب تكوين ملح إبسوم', 'أن يوضّح الطالب تكوين ملح إبسوم بوصفه تفاعل حمض لويس مع قاعدة لويس.', '[]'::jsonb, 'أن يوضّح الطالب تكوين ملح إبسوم بوصفه تفاعل حمض لويس مع قاعدة لويس.', 'تحديد السياق العلمي الذي يقدّمه الكتاب (تفاعل لويس) ليصبح الهدف قابلًا للقياس.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["ملح إبسوم","حمض لويس","قاعدة لويس","ثالث أكسيد الكبريت","أكسيد الماغنسيوم"]'::jsonb, null, '[64,65]'::jsonb, 'مغطى', 'SO3(g) + MgO(s) → MgSO4(s): يمثل SO3 حمض لويس (يستقبل زوج إلكترونات) وأيون الأكسيد O2− من MgO قاعدة لويس، والناتج أيون الكبريتات؛ ويُستفاد من التفاعل بيئيًا بحقن MgO في غازات مداخن محطات الطاقة العاملة بالفحم لانتزاع SO3 ومنع تكوّن المطر الحمضي (الشكل 2-10).', null, 'approved', '2026-10-16'::timestamptz),
(402121, 4021, 'K3-C2-L1-O21', null, 21, 'أن يميّز الطالب بين المحلول الحمضي والمحلول القاعدي والمحلول المتعادل بمقارنة تراكيز أيونات الهيدروجين H⁺ وأيونات الهيدروكسيد OH⁻.', 'أن يميّز الطالب بين المحلول الحمضي والمحلول القاعدي والمحلول المتعادل بمقارنة تراكيز أيونات الهيدروجين H⁺ وأيونات الهيدروكسيد OH⁻.', '[]'::jsonb, 'أن يميّز الطالب بين المحلول الحمضي والمحلول القاعدي والمحلول المتعادل بمقارنة تراكيز أيونات الهيدروجين H⁺ وأيونات الهيدروكسيد OH⁻.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["المحلول الحمضي","المحلول القاعدي","المحلول المتعادل","أيون الهيدروجين","أيون الهيدروكسيد"]'::jsonb, null, '[58]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص58: «تحدد الكميات النسبية من الأيونين ما إذا كان المحلول حمضيًا أو قاعديًا أو متعادلًا»؛ المحلول الحمضي يحتوي أيونات H⁺ أكثر من OH⁻، والقاعدي يحتوي OH⁻ أكثر من H⁺، والمتعادل يحتوي تركيزين متساويين؛ ويمثل الشكل 2-3 هذه العلاقات (والهدف K3-C2-L1-O05 يقتصر على تعريف المحلول الحمضي).', null, 'approved', '2026-10-16'::timestamptz),
(402122, 4021, 'K3-C2-L1-O22', null, 22, 'أن يفسّر الطالب قابلية ذرة الهيدروجين للتأين في الحمض عندما ترتبط بذرة عالية الكهروسالبية برابطة قطبية، وعدم تأين ذرات الهيدروجين المرتبطة بذرة الكربون.', 'أن يفسّر الطالب قابلية ذرة الهيدروجين للتأين في الحمض عندما ترتبط بذرة عالية الكهروسالبية برابطة قطبية، وعدم تأين ذرات الهيدروجين المرتبطة بذرة الكربون.', '[]'::jsonb, 'أن يفسّر الطالب قابلية ذرة الهيدروجين للتأين في الحمض عندما ترتبط بذرة عالية الكهروسالبية برابطة قطبية، وعدم تأين ذرات الهيدروجين المرتبطة بذرة الكربون.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["ذرة الهيدروجين القابلة للتأين","الكهروسالبية","الرابطة القطبية"]'::jsonb, null, '[62]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص62 (ذرات الهيدروجين القابلة للتأين، الشكل 2-9): ذرة الهيدروجين القابلة للتأين في حمض الإيثانويك مرتبطة بالأكسجين الأعلى كهروسالبية فتكون الرابطة O–H قطبية، وكذلك H–F في فلوريد الهيدروجين، أما ذرات الهيدروجين في البنزين C6H6 فمرتبطة بكربون كهروسالبيته تقارب كهروسالبية الهيدروجين فالروابط غير قطبية والبنزين غير حمضي.', null, 'approved', '2026-10-16'::timestamptz),
(402123, 4021, 'K3-C2-L1-O23', null, 23, 'أن يقارن الطالب بين نظريات أرهينيوس وبرونستد – لوري ولويس في تعريف الحمض والقاعدة.', 'أن يقارن الطالب بين نظريات أرهينيوس وبرونستد – لوري ولويس في تعريف الحمض والقاعدة.', '[]'::jsonb, 'أن يقارن الطالب بين نظريات أرهينيوس وبرونستد – لوري ولويس في تعريف الحمض والقاعدة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["نظرية أرهينيوس","نظرية برونستد – لوري","نظرية لويس"]'::jsonb, null, '[63,64]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص63–64 والجدول 2-2 «ملخص النظريات الثلاث للأحماض والقواعد»: أرهينيوس (الحمض منتج H⁺، القاعدة منتجة OH⁻)، برونستد – لوري (مانح H⁺ / مستقبل H⁺)، لويس (مستقبل زوج إلكترونات / مانح زوج إلكترونات)؛ ويبين الكتاب أن كل حمض وقاعدة وفق أرهينيوس هما كذلك وفق برونستد – لوري، وأن نظرية لويس أشمل وتضم جميع المواد المصنفة وفق برونستد – لوري وغيرها.', null, 'approved', '2026-10-16'::timestamptz),
(402201, 4022, 'K3-C2-L2-O01', null, 1, 'أن يعرف الطالب الاحماض القوية', 'أن يعرّف الطالب الأحماض القوية والأحماض الضعيفة.', '[]'::jsonb, 'أن يعرّف الطالب الأحماض القوية والأحماض الضعيفة.', 'تصحيح الهمزة والشدة، وإضافة الأحماض الضعيفة لأن الكتاب يعرّفهما متقابلين ولا يوجد هدف آخر لتعريف الضعيفة.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["الحمض القوي","الحمض الضعيف","التأين الكلي","التأين الجزئي"]'::jsonb, null, '[66,67,68]'::jsonb, 'مغطى', 'الأحماض التي تتأين كليًا تسمى أحماضًا قوية وتنتج أكبر عدد من الأيونات فهي موصلات جيدة للكهرباء (HCl، HI، HClO4، HNO3، H2SO4 في الجدول 2-3)، والحمض الذي يتأين جزئيًا فقط في المحلول المائي المخفف يسمى حمضًا ضعيفًا (HF، CH3COOH، H2S، H2CO3، HClO)؛ ويُفسَّر ذلك ببرونستد – لوري: القاعدة المرافقة للحمض القوي ضعيفة.', null, 'approved', '2026-10-16'::timestamptz),
(402202, 4022, 'K3-C2-L2-O02', null, 2, 'أن يقارن الطالب بين الحموض الضعيفة من خلال معرفة قيم Ka', 'أن يقارن الطالب بين قوى الأحماض الضعيفة باستعمال قيم ثابت تأين الحمض Ka.', '[]'::jsonb, 'أن يقارن الطالب بين قوى الأحماض الضعيفة باستعمال قيم ثابت تأين الحمض Ka.', 'تحسين الصياغة وتوحيد المصطلح («الأحماض»، «ثابت تأين الحمض»).', 'صياغة', 'يحتاج تعديلًا', 'تحليل', 'مبادئ وتعميمات', '["ثابت تأين الحمض Ka","قوة الحمض","الأحماض الضعيفة"]'::jsonb, null, '[68,69]'::jsonb, 'مغطى', 'Ka = Keq[H2O]، وهو قيمة ثابت الاتزان لتأين الحمض الضعيف؛ مثال HCN: Ka = [H3O+][CN−]/[HCN] = 6.2×10⁻¹⁰. كلما صغرت Ka كان الحمض أضعف. الجدول 2-4 (298 K): H2S 8.9×10⁻⁸، HS− 1×10⁻¹⁹، HF 6.3×10⁻⁴، HCN 6.2×10⁻¹⁰، CH3COOH 1.8×10⁻⁵، H2CO3 4.5×10⁻⁷، HCO3− 4.7×10⁻¹¹.', null, 'approved', '2026-10-16'::timestamptz),
(402203, 4022, 'K3-C2-L2-O03', null, 3, 'أن يكتب الطالب معادلات التأين القواعد الضعيفة', 'أن يكتب الطالب معادلات تأيّن القواعد الضعيفة في الماء وتعابير ثوابت تأيّنها Kb.', '[]'::jsonb, 'أن يكتب الطالب معادلات تأيّن القواعد الضعيفة في الماء وتعابير ثوابت تأيّنها Kb.', 'تصحيح التركيب («معادلات تأيّن» لا «معادلات التأين القواعد») وإضافة تعبير Kb الذي يطلبه الكتاب في المسائل.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["القاعدة الضعيفة","معادلة التأين","ثابت تأين القاعدة Kb"]'::jsonb, null, '[70,71]'::jsonb, 'مغطى', 'القواعد الضعيفة تتأين جزئيًا مكوّنة مخلوط اتزان، مثل CH3NH2 + H2O ⇌ CH3NH3+ + OH− وKb = [CH3NH3+][OH−]/[CH3NH2]؛ وكلما صغرت Kb كانت القاعدة أضعف. الجدول 2-6: إيثيل أمين 5.0×10⁻⁴، ميثيل أمين 4.3×10⁻⁴، الأمونيا 2.5×10⁻⁵، الأنيلين 4.3×10⁻¹⁰.', null, 'approved', '2026-10-16'::timestamptz),
(402204, 4022, 'K3-C2-L2-O04', null, 4, 'أن يكتب الطالب معادلات التأين الاحماض الضعيفة', 'أن يكتب الطالب معادلات تأيّن الأحماض الضعيفة في الماء وتعابير ثوابت تأيّنها Ka.', '[]'::jsonb, 'أن يكتب الطالب معادلات تأيّن الأحماض الضعيفة في الماء وتعابير ثوابت تأيّنها Ka.', 'تصحيح الهمزة والتركيب وإضافة تعبير Ka الذي يطلبه الكتاب في المسائل.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["الحمض الضعيف","معادلة التأين","سهم الاتزان","ثابت تأين الحمض Ka"]'::jsonb, null, '[67,68,69]'::jsonb, 'مغطى', 'تُكتب معادلات الأحماض الضعيفة بسهمي اتزان (HY + H2O ⇌ H3O+ + Y−) لأن الاتزان يميل إلى اليسار؛ أمثلة الجدولين 2-3 و2-4: HF ⇌ H+ + F−، CH3COOH ⇌ H+ + CH3COO−، H2CO3 ⇌ H+ + HCO3−، HClO ⇌ H+ + ClO−، والأحماض المتعددة البروتونات تُكتب على خطوات لكل منها Ka مختلفة.', null, 'approved', '2026-10-16'::timestamptz),
(402205, 4022, 'K3-C2-L2-O05', null, 5, 'أن يفسّر الطالب اختلاف قوة الأحماض باستعمال نظرية برونستد – لوري، مبيّنًا أن الحمض القوي تكون قاعدته المرافقة ضعيفة وأن الحمض الضعيف تكون قاعدته المرافقة قوية نسبيًا.', 'أن يفسّر الطالب اختلاف قوة الأحماض باستعمال نظرية برونستد – لوري، مبيّنًا أن الحمض القوي تكون قاعدته المرافقة ضعيفة وأن الحمض الضعيف تكون قاعدته المرافقة قوية نسبيًا.', '[]'::jsonb, 'أن يفسّر الطالب اختلاف قوة الأحماض باستعمال نظرية برونستد – لوري، مبيّنًا أن الحمض القوي تكون قاعدته المرافقة ضعيفة وأن الحمض الضعيف تكون قاعدته المرافقة قوية نسبيًا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["الحمض القوي","الحمض الضعيف","القاعدة المرافقة","موضع الاتزان"]'::jsonb, null, '[68,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص68 (قوة الحمض ونظرية برونستد – لوري): الحمض القوي HX قاعدته المرافقة X⁻ ضعيفة ويتأين بنسبة 100% تقريبًا لأن الماء قاعدة أقوى من X⁻ فيقع الاتزان إلى اليمين (سهم واحد)، أما الحمض الضعيف HY فيميل اتزانه إلى اليسار لأن قاعدته المرافقة Y⁻ أقوى من H2O في جذب H⁺ (مثال حمض الإيثانويك، سهما اتزان)؛ وسؤال التقويم 17 ص71 عن العلاقة بين قوة الحمض الضعيف وقوة قاعدته المرافقة.', null, 'approved', '2026-10-16'::timestamptz),
(402206, 4022, 'K3-C2-L2-O06', null, 6, 'أن يميّز الطالب بين القواعد القوية والقواعد الضعيفة من حيث درجة تأينها في المحاليل المائية المخففة، مع ذكر أمثلة على كل منهما.', 'أن يميّز الطالب بين القواعد القوية والقواعد الضعيفة من حيث درجة تأينها في المحاليل المائية المخففة، مع ذكر أمثلة على كل منهما.', '[]'::jsonb, 'أن يميّز الطالب بين القواعد القوية والقواعد الضعيفة من حيث درجة تأينها في المحاليل المائية المخففة، مع ذكر أمثلة على كل منهما.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["القاعدة القوية","القاعدة الضعيفة","التأين الكلي","التأين الجزئي"]'::jsonb, null, '[70,71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص70: القاعدة القوية تتحلل كليًا منتجة أيونات فلزية وأيونات هيدروكسيد مثل NaOH، والجدول 2-5 «معادلات التأين للقواعد القوية» (NaOH، KOH، RbOH، CsOH، Ca(OH)2، Ba(OH)2)؛ القاعدة الضعيفة تتأين جزئيًا فقط مكونة خليط اتزان مثل الميثيل أمين CH3NH2؛ وملخص الدرس ص71 (والهدف K3-C2-L2-O01 يقتصر على الأحماض).', null, 'approved', '2026-10-16'::timestamptz),
(402207, 4022, 'K3-C2-L2-O07', null, 7, 'أن يفسّر الطالب عدّ هيدروكسيد الكالسيوم Ca(OH)2 قاعدة قوية على الرغم من انخفاض ذائبيته في الماء.', 'أن يفسّر الطالب عدّ هيدروكسيد الكالسيوم Ca(OH)2 قاعدة قوية على الرغم من انخفاض ذائبيته في الماء.', '[]'::jsonb, 'أن يفسّر الطالب عدّ هيدروكسيد الكالسيوم Ca(OH)2 قاعدة قوية على الرغم من انخفاض ذائبيته في الماء.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["القاعدة القوية","الذائبية","ثابت حاصل الذائبية Ksp","هيدروكسيد الكالسيوم"]'::jsonb, null, '[70]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص70: هيدروكسيد الكالسيوم مصدر ضعيف لأيونات OH⁻ لأن ذائبيته منخفضة (Ksp = 6.5 × 10⁻⁶) فلا توجد إلا كمية قليلة من OH⁻ في المحلول المشبع، ومع ذلك يُعد هو وغيره من هيدروكسيدات الفلزات القليلة الذوبان قواعد قوية لأن كل ما يذوب منها يتأين كليًا.', null, 'approved', '2026-10-16'::timestamptz),
(402208, 4022, 'K3-C2-L2-O08', null, 8, 'أن يقارن الطالب بين قوى القواعد الضعيفة باستعمال قيم ثابت تأين القاعدة Kb.', 'أن يقارن الطالب بين قوى القواعد الضعيفة باستعمال قيم ثابت تأين القاعدة Kb.', '[]'::jsonb, 'أن يقارن الطالب بين قوى القواعد الضعيفة باستعمال قيم ثابت تأين القاعدة Kb.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مبادئ وتعميمات', '["ثابت تأين القاعدة Kb","القاعدة الضعيفة","قوة القاعدة"]'::jsonb, null, '[71]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص71: يُعرَّف Kb بأنه قيمة ثابت الاتزان لتأين القاعدة الضعيفة، و«كلما صغرت قيمة Kb كانت القاعدة أضعف»؛ والجدول 2-6 «ثوابت التأين لبعض القواعد الضعيفة»: إيثيل أمين 5.0 × 10⁻⁴، ميثيل أمين 4.3 × 10⁻⁴، الأمونيا 2.5 × 10⁻⁵، الأنيلين 4.3 × 10⁻¹⁰ عند 298 K؛ وسؤال التقويم 19 عن دلالة Kb للأنيلين (والهدف K3-C2-L2-O03 يقتصر على كتابة المعادلات والتعابير).', null, 'approved', '2026-10-16'::timestamptz),
(402301, 4023, 'K3-C2-L3-O01', null, 1, 'أن يرسم الطالب مدرج الحموضة بدلالة pH', 'أن يمثّل الطالب مدرج الرقم الهيدروجيني pH محدّدًا عليه مناطق الحمضية والتعادل والقاعدية.', '[]'::jsonb, 'أن يمثّل الطالب مدرج الرقم الهيدروجيني pH محدّدًا عليه مناطق الحمضية والتعادل والقاعدية.', 'تحديد ما يُرسم على المدرج ليصبح الهدف قابلًا للقياس، واستعمال «الرقم الهيدروجيني».', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مفاهيم', '["مدرج pH","الحمضية","القاعدية","التعادل","pOH"]'::jsonb, null, '[74,75]'::jsonb, 'مغطى', 'مدرج pH من 0 إلى 14 عند 298 K: المحاليل الحمضية pH أقل من 7، والقاعدية أكبر من 7، والمتعادلة = 7؛ تغير وحدة واحدة يمثل تغيرًا مقداره 10 مرات في [H+] (محلول pH = 3 تركيز H+ فيه عشرة أضعاف محلول pH = 4). الشكل 2-14 يبين قيم pH لمواد مألوفة (حمض البطارية، عصير الليمون، الحليب، الدم، ماء البحر، منظف الأفران)، والشكل 2-15 يربط [H+] وpH وpOH و[OH−].', null, 'approved', '2026-10-16'::timestamptz),
(402302, 4023, 'K3-C2-L3-O02', null, 2, 'أن يحسب الطالب قيمة كل من [OH⁻] و pH و pOH بمعرفة تركيز أيون [H⁺]', 'أن يحسب الطالب قيم [OH⁻] وpH وpOH لمحلول بمعلومية تركيز أيون الهيدروجين [H⁺].', '[]'::jsonb, 'أن يحسب الطالب قيم [OH⁻] وpH وpOH لمحلول بمعلومية تركيز أيون الهيدروجين [H⁺].', 'تحسين الصياغة («بمعلومية»، حذف الأقواس المكررة حول H+).', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["ثابت تأين الماء Kw","الرقم الهيدروجيني pH","الرقم الهيدروكسيدي pOH"]'::jsonb, null, '[72,73,74,75,76]'::jsonb, 'مغطى', 'Kw = [H+][OH−] = 1.0×10⁻¹⁴ عند 298 K؛ pH = −log[H+]، pOH = −log[OH−]، pH + pOH = 14.00. المثال 2-1: [H+] = 1.0×10⁻⁵ M ⇒ [OH−] = 1.0×10⁻⁹ M (القهوة حمضية)؛ المثال 2-2: [H+] = 1.0×10⁻⁷ M ⇒ pH = 7.00؛ المسألة 26 تطلب pH وpOH من [H+].', null, 'approved', '2026-10-16'::timestamptz),
(402303, 4023, 'K3-C2-L3-O03', null, 3, 'أن يحسب الطالب قيمة [OH⁻] بمعرفة [H⁺]', 'أن يحسب الطالب تركيز أيون الهيدروكسيد [OH⁻] بمعلومية تركيز أيون الهيدروجين [H⁺] باستعمال Kw.', '[]'::jsonb, 'أن يحسب الطالب تركيز أيون الهيدروكسيد [OH⁻] بمعلومية تركيز أيون الهيدروجين [H⁺] باستعمال Kw.', 'الهدف جزء من الهدف K3-C2-L3-O02؛ يُدمج فيه أو يُبقى هدفًا تمهيديًا مستقلًا.', 'دمج', 'مكرر', 'تطبيق', 'إجراءات', '["ثابت تأين الماء Kw","[H+]","[OH−]"]'::jsonb, null, '[72,73]'::jsonb, 'مغطى', 'Kw = [H+][OH−] = 1.0×10⁻¹⁴ (298 K) وتأين الماء ذاتيًا: H2O ⇌ H+ + OH−، و[H+] = [OH−] = 1.0×10⁻⁷ M في الماء النقي؛ المثال 2-1: [OH−] = Kw/[H+] = 1.0×10⁻¹⁴/1.0×10⁻⁵ = 1.0×10⁻⁹ mol/L؛ ووفق مبدأ لوتشاتلييه زيادة [H+] تقلل [OH−].', null, 'approved', '2026-10-16'::timestamptz),
(402304, 4023, 'K3-C2-L3-O04', null, 4, 'أن يحسب الطالب قيمة كل من pOH و [H⁺] و [OH⁻] بمعرفة قيمة pH', 'أن يحسب الطالب قيم pOH و[H⁺] و[OH⁻] لمحلول بمعلومية قيمة pH.', '[]'::jsonb, 'أن يحسب الطالب قيم pOH و[H⁺] و[OH⁻] لمحلول بمعلومية قيمة pH.', 'تحسين الصياغة («بمعلومية»).', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["الرقم الهيدروجيني pH","اللوغاريتم العكسي","pOH"]'::jsonb, null, '[77]'::jsonb, 'مغطى', 'المثال 2-4: pH = 7.40 ⇒ [H+] = 10^−pH = 4.0×10⁻⁸ M، pOH = 14.00 − 7.40 = 6.60، [OH−] = 10^−6.60 = 2.5×10⁻⁷ M؛ والمسائل 29–30 تطبيق على ذلك (ومنها pOH = 5.60).', null, 'approved', '2026-10-16'::timestamptz),
(402305, 4023, 'K3-C2-L3-O05', null, 5, 'أن يعرّف الطالب ثابت تأين الماء Kw بوصفه ثابت الاتزان للتأين الذاتي للماء.', 'أن يعرّف الطالب ثابت تأين الماء Kw بوصفه ثابت الاتزان للتأين الذاتي للماء.', '[]'::jsonb, 'أن يعرّف الطالب ثابت تأين الماء Kw بوصفه ثابت الاتزان للتأين الذاتي للماء.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["التأين الذاتي للماء","ثابت تأين الماء Kw","أيون الهيدرونيوم"]'::jsonb, null, '[58,72]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص58: ينتج الماء النقي أعدادًا متساوية من H⁺ وOH⁻ في عملية تسمى التأين الذاتي؛ ص72 (الشكل 2-13): Kw = [H⁺][OH⁻] وهو قيمة تعبر عن ثابت الاتزان للتأين الذاتي للماء، ولا يظهر H2O في المقام لثبات تركيزه، و[H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M للماء النقي، فـ Kw = 1.0 × 10⁻¹⁴ عند 298 K.', null, 'approved', '2026-10-16'::timestamptz),
(402306, 4023, 'K3-C2-L3-O06', null, 6, 'أن يفسّر الطالب العلاقة العكسية بين تركيز أيونات الهيدروجين وتركيز أيونات الهيدروكسيد في المحاليل المائية باستعمال مبدأ لوتشاتلييه وثبات قيمة Kw.', 'أن يفسّر الطالب العلاقة العكسية بين تركيز أيونات الهيدروجين وتركيز أيونات الهيدروكسيد في المحاليل المائية باستعمال مبدأ لوتشاتلييه وثبات قيمة Kw.', '[]'::jsonb, 'أن يفسّر الطالب العلاقة العكسية بين تركيز أيونات الهيدروجين وتركيز أيونات الهيدروكسيد في المحاليل المائية باستعمال مبدأ لوتشاتلييه وثبات قيمة Kw.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["ثابت تأين الماء Kw","مبدأ لوتشاتلييه","الاتزان"]'::jsonb, null, '[73,80]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص73 (Kw ومبدأ لوتشاتلييه): حاصل ضرب [H⁺] و[OH⁻] يساوي دائمًا 1.0 × 10⁻¹⁴ عند 298 K، فإذا زاد [H⁺] نقص [OH⁻]؛ إذ تتفاعل أيونات H⁺ المضافة مع OH⁻ لتكوين ماء فيقل تركيز OH⁻؛ وسؤال «ماذا قرأت؟» لماذا لا يتغير Kw عند زيادة [H⁺]، والسؤال 37 ص80 (تطبيق مبدأ لوتشاتلييه على حمض الإيثانويك).', null, 'approved', '2026-10-16'::timestamptz),
(402307, 4023, 'K3-C2-L3-O07', null, 7, 'أن يعرّف الطالب الرقم الهيدروجيني pH والرقم الهيدروكسيدي pOH.', 'أن يعرّف الطالب الرقم الهيدروجيني pH والرقم الهيدروكسيدي pOH.', '[]'::jsonb, 'أن يعرّف الطالب الرقم الهيدروجيني pH والرقم الهيدروكسيدي pOH.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["الرقم الهيدروجيني pH","الرقم الهيدروكسيدي pOH","اللوغاريتم"]'::jsonb, null, '[74,75]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص74: pH محلول ما هو سالب لوغاريتم تركيز أيون الهيدروجين pH = −log[H⁺]، وpOH هو سالب لوغاريتم تركيز أيون الهيدروكسيد pOH = −log[OH⁻]، وتغير وحدة واحدة يمثل تغيرًا مقداره 10 مرات في التركيز، ومجموع pH وpOH يساوي 14.00؛ ص75 الشكل 2-15 العلاقة بين pH و[H⁺] وpOH و[OH⁻].', null, 'approved', '2026-10-16'::timestamptz),
(402308, 4023, 'K3-C2-L3-O08', null, 8, 'أن يحسب الطالب قيمتي pH وpOH لمحاليل الأحماض القوية والقواعد القوية بمعلومية مولاريتها.', 'أن يحسب الطالب قيمتي pH وpOH لمحاليل الأحماض القوية والقواعد القوية بمعلومية مولاريتها.', '[]'::jsonb, 'أن يحسب الطالب قيمتي pH وpOH لمحاليل الأحماض القوية والقواعد القوية بمعلومية مولاريتها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["الحمض القوي","القاعدة القوية","المولارية","الرقم الهيدروجيني pH"]'::jsonb, null, '[76,78,80]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص78 (المولارية والرقم الهيدروجيني للأحماض والقواعد القوية، الشكل 2-17): في الأحماض القوية الأحادية البروتون يساوي [H⁺] مولارية الحمض (0.1 M HCl ← 0.1 mol H⁺/L)، وفي NaOH يساوي [OH⁻] مولارية المحلول، وفي Ca(OH)2 يكون [OH⁻] ضعف المولارية (7.5 × 10⁻⁴ M × 2 = 1.5 × 10⁻³ M)، ولا ينطبق ذلك على الأحماض والقواعد الضعيفة؛ تمارين 28 ص76 و40 ص80 (HI، HNO3، KOH، Mg(OH)2).', null, 'approved', '2026-10-16'::timestamptz),
(402309, 4023, 'K3-C2-L3-O09', null, 9, 'أن يحسب الطالب ثابت تأين الحمض الضعيف Ka بمعلومية قيمة pH لمحلوله وتركيزه الابتدائي.', 'أن يحسب الطالب ثابت تأين الحمض الضعيف Ka بمعلومية قيمة pH لمحلوله وتركيزه الابتدائي.', '[]'::jsonb, 'أن يحسب الطالب ثابت تأين الحمض الضعيف Ka بمعلومية قيمة pH لمحلوله وتركيزه الابتدائي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["ثابت تأين الحمض Ka","الرقم الهيدروجيني pH","الحمض الضعيف","تركيز الاتزان"]'::jsonb, null, '[78,79]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص78 (حساب Ka من الرقم الهيدروجيني): مثال HF تركيزه 0.100 M وpH = 3.20، يحسب [H⁺] من pH و[F⁻] = [H⁺] و[HF] عند الاتزان = التركيز الابتدائي − [H⁺]؛ ص79 المثال 2-5: حمض الميثانويك 0.100 M وpH = 2.38 ← [H⁺] = 4.2 × 10⁻³ M و[HCOOH] = 0.096 M وKa = 1.8 × 10⁻⁴؛ تمارين 31–33.', null, 'approved', '2026-10-16'::timestamptz),
(402310, 4023, 'K3-C2-L3-O10', null, 10, 'أن يقارن الطالب بين قياس الرقم الهيدروجيني pH باستعمال ورق الكاشف وباستعمال مقياس pH الرقمي من حيث طريقة القياس ودقته.', 'أن يقارن الطالب بين قياس الرقم الهيدروجيني pH باستعمال ورق الكاشف وباستعمال مقياس pH الرقمي من حيث طريقة القياس ودقته.', '[]'::jsonb, 'أن يقارن الطالب بين قياس الرقم الهيدروجيني pH باستعمال ورق الكاشف وباستعمال مقياس pH الرقمي من حيث طريقة القياس ودقته.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات', '["ورق الكاشف","ورق تباع الشمس","مقياس pH","الكاشف"]'::jsonb, null, '[80]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص80 (قياس الرقم الهيدروجيني، الشكل 2-18): ورق تباع الشمس وأوراق كاشف pH معالجة بكواشف يتغير لونها بتغير تركيز H⁺، ويقارن لونها بألوان كاشف pH المعياري على ورقة مدرجة فيعطي قيمة تقريبية، بينما يعطي مقياس pH الرقمي قراءة مباشرة أكثر دقة عند وضع أقطابه في المحلول.', null, 'approved', '2026-10-16'::timestamptz),
(402401, 4024, 'K3-C2-L4-O01', null, 1, 'أن يعرف الطالب المحلول التعادل', 'أن يعرّف الطالب تفاعل التعادل.', '[]'::jsonb, 'أن يعرّف الطالب تفاعل التعادل.', '«المحلول التعادل» خطأ في الصياغة؛ المقصود تفاعل التعادل كما في الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["تفاعل التعادل","الملح","المعادلة الأيونية النهائية"]'::jsonb, null, '[81,82]'::jsonb, 'مغطى', 'تفاعل التعادل تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً، والملح مركب أيوني يتكون من أيون موجب من قاعدة وأيون سالب من حمض (تفاعل إحلال مزدوج)؛ مثال Mg(OH)2 + 2HCl → MgCl2 + 2H2O (مضاد الحموضة)، والمعادلة الأيونية النهائية لتعادل حمض قوي وقاعدة قوية: H+ + OH− → H2O (الشكل 2-20).', null, 'approved', '2026-10-16'::timestamptz),
(402402, 4024, 'K3-C2-L4-O02', null, 2, 'أن يعرف الطالب الأدلة ( الكواشف)', 'أن يعرّف الطالب كواشف الأحماض والقواعد (الأدلّة).', '[]'::jsonb, 'أن يعرّف الطالب كواشف الأحماض والقواعد (الأدلّة).', 'إضافة الشدة واستعمال مصطلح الكتاب «كواشف الأحماض والقواعد».', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["كاشف الحمض والقاعدة","نقطة النهاية","نقطة التكافؤ","البروموثيمول الأزرق","الفينولفثالين"]'::jsonb, null, '[84,85]'::jsonb, 'مغطى', 'كواشف الأحماض والقواعد أصباغ كيميائية تتأثر ألوانها بالمحاليل الحمضية والقاعدية، ومعظمها أحماض ضعيفة (مثل البوليفينولات في الشاي)؛ نقطة النهاية هي النقطة التي يتغير عندها لون الكاشف، ويجب اختيار كاشف يتغير لونه عند نقطة التكافؤ: البروموثيمول الأزرق لمعايرة حمض قوي بقاعدة قوية، والفينولفثالين لحمض ضعيف بقاعدة قوية (الشكل 2-24).', null, 'approved', '2026-10-16'::timestamptz),
(402403, 4024, 'K3-C2-L4-O03', null, 3, 'أن يحسب الطالب مولارية محلول من بيانات المعايرة', 'أن يحسب الطالب مولارية محلول مجهول التركيز من بيانات المعايرة.', '[]'::jsonb, 'أن يحسب الطالب مولارية محلول مجهول التركيز من بيانات المعايرة.', 'توضيح المطلوب (محلول مجهول التركيز).', 'صياغة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["المعايرة","المحلول القياسي","نقطة التكافؤ","النسبة المولية","المولارية"]'::jsonb, null, '[82,83,85,86]'::jsonb, 'مغطى', 'المعايرة طريقة لتحديد تركيز محلول بتفاعله مع حجم معلوم من محلول قياسي معلوم التركيز، ونقطة التكافؤ يتساوى عندها عدد مولات H+ مع مولات OH−؛ الخطوات: mol = MB×VB ثم النسبة المولية من المعادلة الموزونة ثم MA = mol/VA. المثال 2-6: 18.28 mL NaOH (0.1000 M) تعادل 25.00 mL HCOOH ⇒ MA = 7.312×10⁻² mol/L.', null, 'approved', '2026-10-16'::timestamptz),
(402404, 4024, 'K3-C2-L4-O04', null, 4, 'أن يعرف الطالب تمية الأملاح', 'أن يعرّف الطالب تميّه الأملاح.', '[]'::jsonb, 'أن يعرّف الطالب تميّه الأملاح.', 'إضافة الشدة في «يعرّف» و«تميّه».', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["تميّه الأملاح","الأيونات السالبة","الأيونات الموجبة"]'::jsonb, null, '[87]'::jsonb, 'مغطى', 'تميّه الأملاح عملية تتفاعل فيها الأملاح مع الماء؛ حيث تستقبل الأيونات السالبة من الملح المتأين أيونات الهيدروجين من الماء، أو تمنح الأيونات الموجبة من الملح المتفكك أيونات الهيدروجين للماء (الشكل 2-26: كاشف البروموثيمول الأزرق في NH4Cl وNaNO3 وKF).', null, 'approved', '2026-10-16'::timestamptz),
(402405, 4024, 'K3-C2-L4-O05', null, 5, 'أن يصنف الطالب الاملاح إلى حمضية أو قاعدية أو متعادلة', 'أن يصنّف الطالب محاليل الأملاح إلى حمضية أو قاعدية أو متعادلة، ويكتب معادلات تميّهها.', '[]'::jsonb, 'أن يصنّف الطالب محاليل الأملاح إلى حمضية أو قاعدية أو متعادلة، ويكتب معادلات تميّهها.', 'تصحيح الهمزة («الأملاح») والتصنيف للمحاليل لا للأملاح، وإضافة كتابة معادلة التميه التي تطلبها المسألة 46.', 'صياغة', 'يحتاج تعديلًا', 'تحليل', 'مبادئ وتعميمات', '["تميّه الأملاح","ملح حمضي","ملح قاعدي","ملح متعادل"]'::jsonb, null, '[87,88]'::jsonb, 'مغطى', 'ملح من قاعدة قوية وحمض ضعيف (KF) محلوله قاعدي: F− + H2O ⇌ HF + OH−؛ ملح من قاعدة ضعيفة وحمض قوي (NH4Cl) محلوله حمضي: NH4+ + H2O ⇌ NH3 + H3O+؛ ملح من حمض قوي وقاعدة قوية (NaNO3) محلوله متعادل لأن Na+ وNO3− لا يتفاعلان مع الماء.', null, 'approved', '2026-10-16'::timestamptz),
(402406, 4024, 'K3-C2-L4-O06', null, 6, 'أن يعرف الطالب المحلول المنظم', 'أن يعرّف الطالب المحلول المنظّم.', '[]'::jsonb, 'أن يعرّف الطالب المحلول المنظّم.', 'إضافة الشدة.', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["المحلول المنظم","سعة المحلول المنظم","مقاومة تغير pH"]'::jsonb, null, '[88,89]'::jsonb, 'مغطى', 'المحاليل المنظمة محاليل تقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد؛ إضافة 0.01 mol HCl إلى 1 L ماء نقي تخفض pH من 7.0 إلى 2.0 وإضافة 0.01 mol NaOH ترفعه إلى 12.0، بينما في محلول منظم لا يتغير pH بأكثر من 0.1 وحدة. سعة المحلول المنظم: كمية الحمض أو القاعدة التي يستوعبها دون تغير مهم في pH.', null, 'approved', '2026-10-16'::timestamptz),
(402407, 4024, 'K3-C2-L4-O07', null, 7, 'أن يكتب الطالب مكونات المحلول المنظم', 'أن يحدّد الطالب مكوّنات المحلول المنظّم ويفسّر آلية مقاومته لتغير pH عند إضافة حمض أو قاعدة.', '[]'::jsonb, 'أن يحدّد الطالب مكوّنات المحلول المنظّم ويفسّر آلية مقاومته لتغير pH عند إضافة حمض أو قاعدة.', '«يكتب المكونات» أداء ضعيف؛ الكتاب يعرض المكونات وآلية العمل وفق مبدأ لوتشاتلييه.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["المحلول المنظم","الحمض الضعيف وقاعدته المرافقة","مبدأ لوتشاتلييه","الأزواج المترافقة"]'::jsonb, null, '[88,89]'::jsonb, 'مغطى', 'المحلول المنظم خليط من حمض ضعيف مع قاعدته المرافقة، أو قاعدة ضعيفة مع حمضها المرافق؛ مثال HF/NaF (0.1 M): إضافة H+ تزيح الاتزان HF ⇌ H+ + F− إلى اليسار، وإضافة OH− تستهلك H+ فيتأين مزيد من HF. يكون أكثر فاعلية عند تساوي تركيز الحمض وقاعدته المرافقة (H2PO4−/HPO4 2−: pH = 7.21)؛ الجدول 2-7: HF/F− 3.20، CH3COOH/CH3COO− 4.76، H2CO3/HCO3− 6.35، NH4+/NH3 9.4، C2H5NH3+/C2H5NH2 10.70.', null, 'approved', '2026-10-16'::timestamptz),
(402408, 4024, 'K3-C2-L4-O08', null, 8, 'أن يعدد الطالب مجالات استخدام المحاليل المنظمة في الحياة', 'أن يذكر الطالب أمثلة على أهمية المحاليل المنظّمة في حياة الكائنات الحية.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على أهمية المحاليل المنظّمة في حياة الكائنات الحية.', '«يعدّد مجالات الاستخدام» أوسع مما في الكتاب؛ الكتاب يعرض أمثلة الدم والعصارة المعدية وأحواض الأحياء المائية فقط.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["المحاليل المنظمة","pH الدم","نظام H2CO3/HCO3−","العصارة المعدية"]'::jsonb, null, '[88,90]'::jsonb, 'جزئي', 'يجب أن يبقى pH الدم بين 7.1 و7.7 ويحافظ عليه نظام H2CO3/HCO3− (CO2 + H2O ⇌ H2CO3 ⇌ H+ + HCO3−، مختبر حل المشكلات ص90)، وpH العصارة المعدية بين 1.6 و1.8، ولقناديل البحر يجب أن يبقى pH أحواض الأحياء المائية بين 8.1 و8.4 (الشكل 2-27)؛ لا يعرض الكتاب تطبيقات صناعية أو دوائية للمحاليل المنظمة، فهي إثراء.', null, 'approved', '2026-10-16'::timestamptz),
(402409, 4024, 'K3-C2-L4-O09', null, 9, 'أن يكتب الطالب المعادلة الكيميائية والمعادلة الأيونية الكاملة والمعادلة الأيونية النهائية لتفاعل تعادل حمض مع قاعدة، محدّدًا الأيونات المتفرجة.', 'أن يكتب الطالب المعادلة الكيميائية والمعادلة الأيونية الكاملة والمعادلة الأيونية النهائية لتفاعل تعادل حمض مع قاعدة، محدّدًا الأيونات المتفرجة.', '[]'::jsonb, 'أن يكتب الطالب المعادلة الكيميائية والمعادلة الأيونية الكاملة والمعادلة الأيونية النهائية لتفاعل تعادل حمض مع قاعدة، محدّدًا الأيونات المتفرجة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["تفاعل التعادل","الملح","المعادلة الأيونية الكاملة","المعادلة الأيونية النهائية","الأيونات المتفرجة"]'::jsonb, null, '[81,82,90]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص81: تفاعل Mg(OH)2 + 2HCl → MgCl2 + 2H2O (إحلال مزدوج) ومعادلة HCl + NaOH → NaCl + H2O؛ ص82: المعادلة الأيونية الكاملة وأيونات Na⁺ وCl⁻ المتفرجة، والمعادلة الأيونية النهائية H⁺(aq) + OH⁻(aq) → H2O(l) لتعادل حمض قوي مع قاعدة قوية (الشكل 2-20)، وسؤال «ماذا قرأت؟» لتعادل HNO3 مع KOH؛ والسؤال 48 ص90.', null, 'approved', '2026-10-16'::timestamptz),
(402410, 4024, 'K3-C2-L4-O10', null, 10, 'أن يصف الطالب خطوات معايرة حمض بقاعدة باستعمال محلول قياسي معلوم التركيز.', 'أن يصف الطالب خطوات معايرة حمض بقاعدة باستعمال محلول قياسي معلوم التركيز.', '[]'::jsonb, 'أن يصف الطالب خطوات معايرة حمض بقاعدة باستعمال محلول قياسي معلوم التركيز.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'إجراءات', '["المعايرة","المحلول القياسي","السحاحة","مقياس pH"]'::jsonb, null, '[82,83,85]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص82: المعايرة طريقة لتحديد تركيز محلول ما بتفاعل حجم معلوم منه مع محلول تركيزه معلوم (الشكل 2-21)؛ ص83 «كيف تتم معايرة حمض وقاعدة؟»: وضع حجم معين من المحلول المجهول وقياس pH الابتدائي، ملء السحاحة بالمحلول المعلوم التركيز (المحلول القياسي)، إضافة كاشف مناسب ثم أحجام معلومة من المحلول القياسي حتى نقطة التكافؤ؛ ص85 الشكل 2-25 (معايرة HCOOH بـ NaOH 0.1000 M) (والهدف K3-C2-L4-O03 خاص بالحساب).', null, 'approved', '2026-10-16'::timestamptz),
(402411, 4024, 'K3-C2-L4-O11', null, 11, 'أن يميّز الطالب بين نقطة التكافؤ ونقطة النهاية في المعايرة.', 'أن يميّز الطالب بين نقطة التكافؤ ونقطة النهاية في المعايرة.', '[]'::jsonb, 'أن يميّز الطالب بين نقطة التكافؤ ونقطة النهاية في المعايرة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["نقطة التكافؤ","نقطة النهاية","الكاشف"]'::jsonb, null, '[83,85,90]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص83: نقطة التكافؤ هي النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة؛ ص85: نقطة النهاية هي النقطة التي يتغير عندها لون الكاشف، وتسمى نقطة التكافؤ نقطة التعادل في تفاعل الأحماض والقواعد القوية، ولذلك يجب اختيار كاشف يتغير لونه عند نقطة التكافؤ؛ والسؤال 49 ص90 «اشرح الفرق بين نقطة تكافؤ ونقطة نهاية المعايرة».', null, 'approved', '2026-10-16'::timestamptz),
(402412, 4024, 'K3-C2-L4-O12', null, 12, 'أن يحلّل الطالب منحنيات المعايرة لتحديد موقع نقطة التكافؤ في معايرة حمض قوي وحمض ضعيف بقاعدة قوية.', 'أن يحلّل الطالب منحنيات المعايرة لتحديد موقع نقطة التكافؤ في معايرة حمض قوي وحمض ضعيف بقاعدة قوية.', '[]'::jsonb, 'أن يحلّل الطالب منحنيات المعايرة لتحديد موقع نقطة التكافؤ في معايرة حمض قوي وحمض ضعيف بقاعدة قوية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مبادئ وتعميمات', '["منحنى المعايرة","نقطة التكافؤ","تميه الأملاح"]'::jsonb, null, '[83]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص83 الشكل 2-22: (a) معايرة 50.0 mL HCl 0.100 M بـ NaOH 0.100 M، تبدأ pH = 1.00 وتزداد تدريجيًا ثم ترتفع ارتفاعًا حادًا عند نقطة التكافؤ (pH = 7)؛ (b) معايرة حمض الميثانويك الضعيف بـ NaOH تقع نقطة تكافئها بين pH 8 و9؛ يبين الكتاب أن بعض المعايرات لها نقاط تكافؤ أقل من 7 أو أكبر منها بسبب تفاعل الأملاح المتكونة مع الماء؛ وسؤال «اختبار الرسم البياني» لمقارنة المنحنيين.', null, 'approved', '2026-10-16'::timestamptz),
(402413, 4024, 'K3-C2-L4-O13', null, 13, 'أن يختار الطالب الكاشف المناسب لمعايرة معيّنة بالاعتماد على مدى pH الذي يتغير عنده لون الكاشف وقيمة pH عند نقطة التكافؤ.', 'أن يختار الطالب الكاشف المناسب لمعايرة معيّنة بالاعتماد على مدى pH الذي يتغير عنده لون الكاشف وقيمة pH عند نقطة التكافؤ.', '[]'::jsonb, 'أن يختار الطالب الكاشف المناسب لمعايرة معيّنة بالاعتماد على مدى pH الذي يتغير عنده لون الكاشف وقيمة pH عند نقطة التكافؤ.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["كواشف الأحماض والقواعد","مدى تغير لون الكاشف","نقطة التكافؤ"]'::jsonb, null, '[84,85]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص84 الشكل 2-24 «إن عملية اختيار الكاشف الصحيح مهمة جدًا؛ إذ يجب أن يغير الكاشف لونه عند نقطة التكافؤ التي لا تكون دائمًا عند pH = 7» مع مدى تغير لون كواشف عدة (الميثيل البرتقالي، البروموثيمول الأزرق، الفينولفثالين…)؛ البروموثيمول الأزرق مناسب لمعايرة حمض قوي بقاعدة قوية، والفينولفثالين لمعايرة حمض ضعيف بقاعدة قوية؛ ص85: الكواشف أحماض ضعيفة لكل منها مدى pH يتغير لونه عنده.', null, 'approved', '2026-10-16'::timestamptz),
(402414, 4024, 'K3-C2-L4-O14', null, 14, 'أن يقارن الطالب بين سلوك المحلول المنظم والمحلول غير المنظم عند إضافة كميات محدودة من حمض أو قاعدة.', 'أن يقارن الطالب بين سلوك المحلول المنظم والمحلول غير المنظم عند إضافة كميات محدودة من حمض أو قاعدة.', '[]'::jsonb, 'أن يقارن الطالب بين سلوك المحلول المنظم والمحلول غير المنظم عند إضافة كميات محدودة من حمض أو قاعدة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مفاهيم', '["المحلول المنظم","المحلول غير المنظم","الرقم الهيدروجيني pH"]'::jsonb, null, '[88,90]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص88: إضافة 0.01 mol HCl إلى 1 L من الماء النقي تخفض pH من 7.0 إلى 2.0، وإضافة 0.01 mol NaOH ترفعه إلى 12.0، بينما إضافة الكمية نفسها إلى 1 L من محلول منظم لا تغير pH بأكثر من 0.1 وحدة؛ والسؤال 50 ص90 للمقارنة بين محلول غير منظم ومحلول منظم لهما pH = 7؛ وهو من أهداف الدرس المعلنة ص81.', null, 'approved', '2026-10-16'::timestamptz),
(402415, 4024, 'K3-C2-L4-O15', null, 15, 'أن يعرّف الطالب سعة المحلول المنظم.', 'أن يعرّف الطالب سعة المحلول المنظم.', '[]'::jsonb, 'أن يعرّف الطالب سعة المحلول المنظم.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'مفاهيم', '["سعة المحلول المنظم","المحلول المنظم","تركيز مكونات المحلول المنظم"]'::jsonb, null, '[89]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص89: سعة المحلول المنظم هي كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH، وقدرته على مقاومة تغير pH تُتجاوز عند إضافة كمية كبيرة من الحمض أو القاعدة، و«كلما زادت تراكيز الجزيئات والأيونات المنظمة في المحلول زادت سعة المحلول المنظم».', null, 'approved', '2026-10-16'::timestamptz),
(402416, 4024, 'K3-C2-L4-O16', null, 16, 'أن يختار الطالب المحلول المنظم المناسب للمحافظة على قيمة pH معيّنة باستعمال قيم Ka للأزواج المترافقة.', 'أن يختار الطالب المحلول المنظم المناسب للمحافظة على قيمة pH معيّنة باستعمال قيم Ka للأزواج المترافقة.', '[]'::jsonb, 'أن يختار الطالب المحلول المنظم المناسب للمحافظة على قيمة pH معيّنة باستعمال قيم Ka للأزواج المترافقة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["اختيار المحلول المنظم","ثابت تأين الحمض Ka","الزوج المترافق","الرقم الهيدروجيني pH"]'::jsonb, null, '[89,90]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص89 (اختيار المحلول المنظم): يكون المحلول المنظم أكثر فاعلية عندما يتساوى تركيز الحمض وتركيز قاعدته المرافقة؛ مثال H2PO4⁻/HPO4²⁻ بكميتين متساويتين: Ka = 6.2 × 10⁻⁸ = [H⁺] فيكون pH = −log Ka = 7.21؛ الجدول 2-7 «المحاليل المنظمة والأزواج المرافقة» مع pH الأكثر فاعلية: HF/F⁻ 3.20، CH3COOH/CH3COO⁻ 4.76، H2CO3/HCO3⁻ 6.35، H2PO4⁻/HPO4²⁻ 7.21، NH4⁺/NH3 9.4، C2H5NH3⁺/C2H5NH2 10.70؛ والسؤال 52 ص90 (محلول منظم pH له 9.4).', null, 'approved', '2026-10-16'::timestamptz),
(403101, 4031, 'K3-C3-L1-O01', null, 1, 'أن يعرف الطالب عملية الأكسدة و لاختزال قديما.', 'أن يعرّف الطالب كلًّا من الأكسدة والاختزال بدلالة انتقال الإلكترونات، مقارنًا بالمفهوم القديم للأكسدة (الاتحاد بالأكسجين).', '[]'::jsonb, 'أن يعرّف الطالب كلًّا من الأكسدة والاختزال بدلالة انتقال الإلكترونات، مقارنًا بالمفهوم القديم للأكسدة (الاتحاد بالأكسجين).', 'تصحيح «و لاختزال» إلى «والاختزال» وهمزة «قديمًا»؛ والكتاب يعرض المفهوم القديم للأكسدة فقط (الاتحاد بالأكسجين) ويركّز على التعريف الحديث (فقد الإلكترونات واكتسابها)، فقصر الهدف على المفهوم القديم يغفل التعريف المعتمد.', 'صياغة', 'يحتاج تعديلًا', 'تذكر', 'مفاهيم', '["الأكسدة","الاختزال","تفاعل الأكسدة والاختزال","انتقال الإلكترونات"]'::jsonb, null, '[104,105]'::jsonb, 'جزئي', 'يذكر الكتاب أن كلمة الأكسدة أُطلقت فيما مضى على التفاعلات التي تتضمن اتحاد المادة بالأكسجين، ثم يعرّف الأكسدة حاليًا بفقد الإلكترونات (Na → Na⁺ + e⁻) والاختزال باكتسابها (Cl₂ + 2e⁻ → 2Cl⁻) وتفاعل الأكسدة والاختزال بانتقال الإلكترونات. لا يورد الكتاب مفهومًا قديمًا للاختزال (إزالة الأكسجين)، فالهدف بصيغته الأصلية مغطى جزئيًا.', null, 'approved', '2026-10-16'::timestamptz),
(403102, 4031, 'K3-C3-L1-O02', null, 2, 'أن يحدد الطالب لعامل المؤكسد والعامل المختزل في المعادلة الكيميائية.', 'أن يحدد الطالب العامل المؤكسد والعامل المختزل في معادلة تفاعل أكسدة واختزال.', '[]'::jsonb, 'أن يحدد الطالب العامل المؤكسد والعامل المختزل في معادلة تفاعل أكسدة واختزال.', 'تصحيح «لعامل» إلى «العامل» وتخصيص المعادلة بتفاعل الأكسدة والاختزال.', 'إملائي', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["العامل المؤكسد","العامل المختزل","المادة المتأكسدة","المادة المختزلة"]'::jsonb, null, '[107,108,109,112]'::jsonb, 'مغطى', 'يعرّف الكتاب العامل المؤكسد بأنه المادة التي تؤكسد غيرها باكتسابها الإلكترونات، والعامل المختزل بأنه المادة التي تختزل غيرها بفقدها الإلكترونات، ويحددهما في تفاعل K مع Cl₂؛ ويطبّق ذلك في المثال 1-3 والمسائل التدريبية 2–4 (مثل Fe + 2Ag⁺، Mg + I₂، H₂S + Cl₂).', null, 'approved', '2026-10-16'::timestamptz),
(403103, 4031, 'K3-C3-L1-O03', null, 3, 'أن يقارن الطالب ين العامل المؤكسد والعامل المختزل.', 'أن يقارن الطالب بين العامل المؤكسد والعامل المختزل من حيث انتقال الإلكترونات والتغير في عدد التأكسد.', '[]'::jsonb, 'أن يقارن الطالب بين العامل المؤكسد والعامل المختزل من حيث انتقال الإلكترونات والتغير في عدد التأكسد.', 'تصحيح «ين» إلى «بين» وتحديد أوجه المقارنة لجعل الهدف قابلًا للقياس.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["العامل المؤكسد","العامل المختزل","اكتساب الإلكترونات","فقد الإلكترونات","عدد التأكسد"]'::jsonb, null, '[107]'::jsonb, 'مغطى', 'يلخص الجدول 1-3 (ملخص تفاعلات الأكسدة والاختزال) المقارنة: في الأكسدة تفقد X الإلكترونات ويزيد عدد تأكسدها وهي العامل المختزل، وفي الاختزال تكتسب Y الإلكترونات ويقل عدد تأكسدها وهي العامل المؤكسد.', null, 'approved', '2026-10-16'::timestamptz),
(403104, 4031, 'K3-C3-L1-O04', null, 4, 'أن يعرف الطالب عدد التأكسد', 'أن يعرّف الطالب عدد التأكسد.', '[]'::jsonb, 'أن يعرّف الطالب عدد التأكسد.', 'ضبط «يعرّف» بالتشديد لرفع اللبس وإضافة النقطة.', 'إملائي', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["عدد التأكسد"]'::jsonb, null, '[106,110]'::jsonb, 'مغطى', 'يعرّف الكتاب عدد التأكسد للذرة في المركب الأيوني بعدد الإلكترونات التي فقدتها أو اكتسبتها عند تكوين الأيون، ويصفه أداةً لتتبع حركة الإلكترونات، ويبين أن إشارته تُكتب قبل العدد (+3) بخلاف شحنة الأيون (3+)، مع رمزه (n) في ص110.', null, 'approved', '2026-10-16'::timestamptz),
(403105, 4031, 'K3-C3-L1-O05', null, 5, 'أن يحسب الطالب عدد الأكسدة لعنصر ما في مركب أو أيون.', 'أن يحسب الطالب عدد التأكسد لعنصر في مركب أو أيون متعدد الذرات باستعمال قواعد تحديد أعداد التأكسد.', '[]'::jsonb, 'أن يحسب الطالب عدد التأكسد لعنصر في مركب أو أيون متعدد الذرات باستعمال قواعد تحديد أعداد التأكسد.', 'توحيد المصطلح مع الكتاب («عدد التأكسد» بدل «عدد الأكسدة») وربط الحساب بالقواعد.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["عدد التأكسد","قواعد تحديد أعداد التأكسد","المركب المتعادل","الأيون متعدد الذرات"]'::jsonb, null, '[110,111,112]'::jsonb, 'مغطى', 'يعرض الجدول 2-3 تسع قواعد: الذرة غير المتحدة صفر، الأيون أحادي الذرة = شحنته، الأكثر كهروسالبية يأخذ الشحنة السالبة، الفلور −1 دائمًا، الأكسجين −2 عدا فوق الأكاسيد (−1) وOF₂ (+2)، الهيدروجين +1 عدا الهيدريدات (−1)، فلزات المجموعتين 1 و2 والألومنيوم +1 و+2 و+3، مجموع الأعداد في المركب المتعادل صفر وفي الأيون متعدد الذرات يساوي شحنته؛ والمثال 2-3 يحسب n للكلور في KClO₃ (+5) وللكبريت في SO₃²⁻ (+4)، والمسائل 5–8 والجدول 3-3 والتقويم 12–13.', null, 'approved', '2026-10-16'::timestamptz),
(403106, 4031, 'K3-C3-L1-O06', null, 6, 'ان يوضح الطالب علاقة تفاعلات الاكسدة والاختزال بالكهروسالبية.', 'أن يوضح الطالب علاقة الكهروسالبية بتفاعلات الأكسدة والاختزال التي تتضمن مركبات جزيئية (تساهمية)، ويتوقع قوة العامل المؤكسد أو المختزل من موقع العنصر في الجدول الدوري.', '[]'::jsonb, 'أن يوضح الطالب علاقة الكهروسالبية بتفاعلات الأكسدة والاختزال التي تتضمن مركبات جزيئية (تساهمية)، ويتوقع قوة العامل المؤكسد أو المختزل من موقع العنصر في الجدول الدوري.', 'تصحيح همزتي «أن» و«الأكسدة»، وتحديد مضمون العلاقة كما يعرضها الكتاب.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["الكهروسالبية","المركبات الجزيئية","العامل المؤكسد القوي","العامل المختزل القوي","تدرج الكهروسالبية في الجدول الدوري"]'::jsonb, null, '[108]'::jsonb, 'مغطى', 'في تفاعل N₂ + 3H₂ → 2NH₃ لا تتكون أيونات، ويُعدّ النيتروجين (كهروسالبيته 3.04) قد اختُزل والهيدروجين (2.20) قد تأكسد لأن الذرة الأكثر كهروسالبية تجذب الإلكترونات المشتركة؛ ويبين الشكل 4-3 أن عناصر المجموعتين 1 و2 منخفضة الكهروسالبية عوامل مختزلة قوية، وعناصر المجموعة 17 والأكسجين عوامل مؤكسدة قوية.', null, 'approved', '2026-10-16'::timestamptz),
(403107, 4031, 'K3-C3-L1-O07', null, 7, 'أن يحدد الطالب المادة التي تأكسدت والمادة التي اختُزلت في تفاعل أكسدة واختزال بتتبّع التغير في أعداد التأكسد، مستنتجًا أن الأكسدة يصاحبها زيادة في عدد التأكسد والاختزال يصاحبه نقصان فيه.', 'أن يحدد الطالب المادة التي تأكسدت والمادة التي اختُزلت في تفاعل أكسدة واختزال بتتبّع التغير في أعداد التأكسد، مستنتجًا أن الأكسدة يصاحبها زيادة في عدد التأكسد والاختزال يصاحبه نقصان فيه.', '[]'::jsonb, 'أن يحدد الطالب المادة التي تأكسدت والمادة التي اختُزلت في تفاعل أكسدة واختزال بتتبّع التغير في أعداد التأكسد، مستنتجًا أن الأكسدة يصاحبها زيادة في عدد التأكسد والاختزال يصاحبه نقصان فيه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مبادئ وتعميمات', '["الأكسدة","الاختزال","عدد التأكسد","التغير في عدد التأكسد","المادة المتأكسدة","المادة المختزلة"]'::jsonb, null, '[106,109,111,112]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص106: تأكسدت ذرات البوتاسيوم من الصفر إلى +1 واختُزلت ذرات الكلور من الصفر إلى −1، «فكل ذرة أو أيون عند اختزاله يقل عدد تأكسده، وعندما تتأكسد يزيد عدد تأكسدها»؛ ص112 فقرة «أعداد التأكسد في تفاعلات الأكسدة والاختزال»: في 2KBr + Cl₂ يتغير عدد تأكسد البروم من −1 إلى صفر (تأكسد) والكلور من صفر إلى −1 (اختزال)، مع الخلاصة نفسها في ملخص الدرس؛ المثال 1-3 (Al مع Fe³⁺) والمسائل 2 و8 و11 (تحديد التغير الكلي في عدد تأكسد كل عنصر).', null, 'approved', '2026-10-16'::timestamptz),
(403108, 4031, 'K3-C3-L1-O08', null, 8, 'أن يفسر الطالب لماذا تحدث عمليتا الأكسدة والاختزال معًا دائمًا، في ضوء تساوي عدد الإلكترونات المفقودة والمكتسبة.', 'أن يفسر الطالب لماذا تحدث عمليتا الأكسدة والاختزال معًا دائمًا، في ضوء تساوي عدد الإلكترونات المفقودة والمكتسبة.', '[]'::jsonb, 'أن يفسر الطالب لماذا تحدث عمليتا الأكسدة والاختزال معًا دائمًا، في ضوء تساوي عدد الإلكترونات المفقودة والمكتسبة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["الأكسدة","الاختزال","تلازم الأكسدة والاختزال","انتقال الإلكترونات"]'::jsonb, null, '[105,112]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص105: «حتى يحدث تفاعل الأكسدة يجب أن تُكتسب الإلكترونات التي تفقدها المادة المتأكسدة من قبل ذرات أو أيونات مادة أخرى... فالأكسدة والاختزال عمليتان مترافقتان متكاملتان؛ فلا يحدث تفاعل الأكسدة إلا إذا حدث تفاعل اختزال»، مع مثال Na وCl₂؛ وسؤال التقويم 9 ص112: «فسّر لماذا يجب أن يحدث تفاعلا الأكسدة والاختزال معًا دائمًا».', null, 'approved', '2026-10-16'::timestamptz),
(403109, 4031, 'K3-C3-L1-O09', null, 9, 'أن يذكر الطالب أمثلة على تفاعلات الأكسدة والاختزال وتطبيقاتها في الحياة اليومية، مثل صدأ الحديد وطرائق حمايته، وعمل مبيض الغسيل عاملًا مؤكسدًا، وإزالة الشوائب من الفلزات.', 'أن يذكر الطالب أمثلة على تفاعلات الأكسدة والاختزال وتطبيقاتها في الحياة اليومية، مثل صدأ الحديد وطرائق حمايته، وعمل مبيض الغسيل عاملًا مؤكسدًا، وإزالة الشوائب من الفلزات.', '[]'::jsonb, 'أن يذكر الطالب أمثلة على تفاعلات الأكسدة والاختزال وتطبيقاتها في الحياة اليومية، مثل صدأ الحديد وطرائق حمايته، وعمل مبيض الغسيل عاملًا مؤكسدًا، وإزالة الشوائب من الفلزات.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["تطبيقات الأكسدة والاختزال","الصدأ","هيبوكلوريت الصوديوم (المبيض)","إزالة الشوائب من الفلزات","العامل المؤكسد"]'::jsonb, null, '[104,107,109]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص104: ضوء العصا الضوئية ناتج عن تفاعل تنتقل فيه الإلكترونات؛ ص107: «من التطبيقات الشائعة على تفاعلات الأكسدة والاختزال إزالة الشوائب من الفلزات»، ومبيض الغسيل NaClO عامل مؤكسد يؤكسد البقع والأصباغ، مع تجربة «إزالة الشوائب من الفضة» برقائق الألومنيوم؛ ص109 «واقع الكيمياء في الحياة»: تأكسد الحديد في الهواء الرطب مكوّنًا الصدأ Fe₂O₃ وحمايته بالطلاء والدهان والمواد البلاستيكية.', null, 'approved', '2026-10-16'::timestamptz),
(403201, 4032, 'K3-C3-L2-O01', null, 1, 'أن يزن الطالب تفاعل أكسدة واختزال في وسط حامضي و قاعدي.', 'أن يزن الطالب معادلات تفاعلات الأكسدة والاختزال في الوسطين الحمضي والقاعدي باستعمال طريقة عدد التأكسد وطريقة نصف التفاعل.', '["أن يزن الطالب معادلة أكسدة واختزال باستعمال طريقة عدد التأكسد.","أن يزن الطالب معادلة أكسدة واختزال أيونية كلية في وسط حمضي.","أن يزن الطالب معادلة أكسدة واختزال أيونية كلية في وسط قاعدي.","أن يزن الطالب معادلة أكسدة واختزال باستعمال طريقة نصف التفاعل."]'::jsonb, 'أن يزن الطالب معادلات تفاعلات الأكسدة والاختزال في الوسطين الحمضي والقاعدي باستعمال طريقة عدد التأكسد وطريقة نصف التفاعل.', 'تصحيح «حامضي» إلى مصطلح الكتاب «حمضي» وحذف المسافة في «و قاعدي»؛ والهدف يجمع وسطين وطريقتين مختلفتين فيُقسَّم لتمييز النواتج القابلة للقياس.', 'تقسيم', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["وزن معادلات الأكسدة والاختزال","طريقة عدد التأكسد","المعادلة الأيونية الكلية","الأيونات المتفرجة","الوسط الحمضي","الوسط القاعدي","نصف التفاعل","طريقة نصف التفاعل"]'::jsonb, null, '[113,114,115,116,117,118,119,120]'::jsonb, 'مغطى', 'يشرح الكتاب طريقة عدد التأكسد (الجدول 4-3، المثال 3-3: Cu + HNO₃) بمساواة الزيادة الكلية في أعداد التأكسد بالنقصان، ووزن المعادلات الأيونية الكلية في الوسط الحمضي بإضافة H⁺ وH₂O (المثال 4-3: ClO₄⁻ + Br⁻)، وطريقة نصف التفاعل (الجدول 6-3، المثال 5-3: KMnO₄ + SO₂ في وسط حمضي). أما الوسط القاعدي فيُذكر نصًّا فقط (إضافة OH⁻ وH₂O إلى طرفي المعادلة ص115) مع مسائل تدريبية (22، 25، 69b، 79b) دون مثال محلول؛ لذا فالجزء القاعدي أضعف تغطية.', null, 'approved', '2026-10-16'::timestamptz),
(403202, 4032, 'K3-C3-L2-O02', null, 2, 'أن يفسر الطالب الأساس الذي تقوم عليه طريقة عدد التأكسد (تساوي مجموع الزيادة في أعداد التأكسد مع مجموع النقصان فيها)، ويرتّب خطواتها الخمس ويطبقها في وزن معادلة أكسدة واختزال جزيئية.', 'أن يفسر الطالب الأساس الذي تقوم عليه طريقة عدد التأكسد (تساوي مجموع الزيادة في أعداد التأكسد مع مجموع النقصان فيها)، ويرتّب خطواتها الخمس ويطبقها في وزن معادلة أكسدة واختزال جزيئية.', '[]'::jsonb, 'أن يفسر الطالب الأساس الذي تقوم عليه طريقة عدد التأكسد (تساوي مجموع الزيادة في أعداد التأكسد مع مجموع النقصان فيها)، ويرتّب خطواتها الخمس ويطبقها في وزن معادلة أكسدة واختزال جزيئية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["طريقة عدد التأكسد","التغير في عدد التأكسد","ضبط المعاملات","الطريقة التقليدية في الوزن"]'::jsonb, null, '[113,114,120]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص113: «يجب أن يكون مجموع الزيادة في عدد التأكسد مساويًا لمجموع الانخفاض في أعداد التأكسد للذرات المشتركة في التفاعل»، والجدول 4-3 يسرد الخطوات: تحديد أعداد التأكسد، تحديد الذرات المتأكسدة والمختزلة، تحديد التغير، مساواة التغير بضبط المعاملات، إكمال الوزن بالطريقة التقليدية؛ المثال 3-3 (Cu + HNO₃ → Cu(NO₃)₂ + NO₂ + H₂O)، والمسائل 15–18، وسؤال التقويم 28 «فسّر خطوات طريقة عدد التأكسد».', null, 'approved', '2026-10-16'::timestamptz),
(403203, 4032, 'K3-C3-L2-O03', null, 3, 'أن يكتب الطالب المعادلة الأيونية الكلية لتفاعل أكسدة واختزال من معادلته الكيميائية الكاملة، محددًا الأيونات المتفرجة وحاذفًا إياها.', 'أن يكتب الطالب المعادلة الأيونية الكلية لتفاعل أكسدة واختزال من معادلته الكيميائية الكاملة، محددًا الأيونات المتفرجة وحاذفًا إياها.', '[]'::jsonb, 'أن يكتب الطالب المعادلة الأيونية الكلية لتفاعل أكسدة واختزال من معادلته الكيميائية الكاملة، محددًا الأيونات المتفرجة وحاذفًا إياها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["المعادلة الأيونية الكلية","الأيونات المتفرجة","التأين الكلي للحمض القوي","تفكك المركبات الأيونية"]'::jsonb, null, '[112,115,118,119]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص115 «وزن معادلات الأكسدة والاختزال الأيونية الكلية»: كتابة Cu + 4HNO₃ في صورة أيونات (Cu + 4H⁺ + 4NO₃⁻ ...) لأن HNO₃ حمض قوي يتأين كليًّا وCu(NO₃)₂ تتفكك، ثم حذف أيوني النترات المتفرجين؛ ص112: أيون البوتاسيوم لا يتغير عدد تأكسده فيُعدّ أيونًا متفرجًا؛ الخطوة 1 في الجدول 6-3 «اكتب المعادلة الأيونية الكلية للتفاعل، مهملًا الأيونات المتفرجة» (Fe + CuSO₄)، والمثال 5-3 (حذف K⁺).', null, 'approved', '2026-10-16'::timestamptz),
(403204, 4032, 'K3-C3-L2-O04', null, 4, 'أن يكمل الطالب وزن معادلة أكسدة واختزال أيونية كلية بإضافة العدد الكافي من أيونات H⁺ وجزيئات H₂O في الوسط الحمضي، أو أيونات OH⁻ وجزيئات H₂O في الوسط القاعدي، متحققًا من تساوي عدد الذرات والشحنة الكلية في طرفي المعادلة.', 'أن يكمل الطالب وزن معادلة أكسدة واختزال أيونية كلية بإضافة العدد الكافي من أيونات H⁺ وجزيئات H₂O في الوسط الحمضي، أو أيونات OH⁻ وجزيئات H₂O في الوسط القاعدي، متحققًا من تساوي عدد الذرات والشحنة الكلية في طرفي المعادلة.', '[]'::jsonb, 'أن يكمل الطالب وزن معادلة أكسدة واختزال أيونية كلية بإضافة العدد الكافي من أيونات H⁺ وجزيئات H₂O في الوسط الحمضي، أو أيونات OH⁻ وجزيئات H₂O في الوسط القاعدي، متحققًا من تساوي عدد الذرات والشحنة الكلية في طرفي المعادلة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["الوسط الحمضي","الوسط القاعدي","أيونات الهيدروجين","أيونات الهيدروكسيد","وزن الشحنة","المعادلة الأيونية الكلية"]'::jsonb, null, '[115,116,119,120]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص115: أيونات H⁺ وجزيئات الماء متوافرة في المحلول وتشارك متفاعلات أو نواتج، وفي المحاليل القاعدية «يمكنك إضافة أيونات الهيدروكسيد OH⁻ وجزيئات الماء إلى طرفي المعادلة»؛ المثال 4-3 (ClO₄⁻ + Br⁻ في وسط حمضي: إضافة 8H⁺ و4H₂O، والتحقق من تساوي الشحنة الكلية)؛ المثال 5-3 (إضافة H₂O وH⁺ لوزن الأكسجين والشحنة)؛ ملخص ص120؛ المسائل 19–21 و23–24 (حمضي) و22 و25 (قاعدي)، وسؤال التقويم 27 عن أهمية معرفة ظروف التفاعل في المحلول المائي.', null, 'approved', '2026-10-16'::timestamptz),
(403205, 4032, 'K3-C3-L2-O05', null, 5, 'أن يعرّف الطالب نصف التفاعل، ويكتب نصف تفاعل الأكسدة ونصف تفاعل الاختزال لتفاعل أكسدة واختزال معطى.', 'أن يعرّف الطالب نصف التفاعل، ويكتب نصف تفاعل الأكسدة ونصف تفاعل الاختزال لتفاعل أكسدة واختزال معطى.', '[]'::jsonb, 'أن يعرّف الطالب نصف التفاعل، ويكتب نصف تفاعل الأكسدة ونصف تفاعل الاختزال لتفاعل أكسدة واختزال معطى.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["نصف التفاعل","نصف تفاعل الأكسدة","نصف تفاعل الاختزال"]'::jsonb, null, '[117,120]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص117: «يمثل كل نصف تفاعل أحد جزأي تفاعل الأكسدة والاختزال؛ أي تفاعل الأكسدة أو تفاعل الاختزال»، مع مثال 2Fe + 3Cl₂ (Fe → Fe³⁺ + 3e⁻ ، Cl₂ + 2e⁻ → 2Cl⁻)، والجدول 5-3 لأنصاف تفاعلات تأكسد الحديد مع O₂ وF₂ وHBr وAgNO₃ وCuSO₄؛ ملخص ص120 «نصف التفاعل هو أحد جزأي تفاعل الأكسدة والاختزال»؛ سؤالا التقويم 29 و30 (كتابة نصفي تفاعل Pb + Pd(NO₃)₂).', null, 'approved', '2026-10-16'::timestamptz),
(403206, 4032, 'K3-C3-L2-O06', null, 6, 'أن يطبق الطالب خطوات طريقة نصف التفاعل في وزن معادلة أكسدة واختزال: وزن الذرات والشحنات في كل نصف، ومساواة عدد الإلكترونات المفقودة بالمكتسبة باستعمال المضاعف المشترك الأصغر، ثم جمع النصفين وتبسيط الناتج وإعادة الأيونات المتفرجة.', 'أن يطبق الطالب خطوات طريقة نصف التفاعل في وزن معادلة أكسدة واختزال: وزن الذرات والشحنات في كل نصف، ومساواة عدد الإلكترونات المفقودة بالمكتسبة باستعمال المضاعف المشترك الأصغر، ثم جمع النصفين وتبسيط الناتج وإعادة الأيونات المتفرجة.', '[]'::jsonb, 'أن يطبق الطالب خطوات طريقة نصف التفاعل في وزن معادلة أكسدة واختزال: وزن الذرات والشحنات في كل نصف، ومساواة عدد الإلكترونات المفقودة بالمكتسبة باستعمال المضاعف المشترك الأصغر، ثم جمع النصفين وتبسيط الناتج وإعادة الأيونات المتفرجة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["طريقة نصف التفاعل","وزن الشحنات","المضاعف المشترك الأصغر","جمع أنصاف التفاعلات","الأيونات المتفرجة"]'::jsonb, null, '[118,119,120]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). الجدول 6-3 ص118 يسرد خطوات طريقة نصف التفاعل مطبقة على Fe + CuSO₄ (2Fe + 3Cu²⁺ → 3Cu + 2Fe³⁺)؛ المثال 5-3 ص119 (KMnO₄ + SO₂ في وسط حمضي): المضاعف المشترك الأصغر لـ 2 و5 هو 10، ثم جمع النصفين وحذف المواد المتشابهة وإعادة K⁺؛ المسائل 23–25، وسؤال التقويم 31 (أقل عدد من أيونات Sn²⁺ وAu³⁺ حتى لا تتبقى إلكترونات).', null, 'approved', '2026-10-16'::timestamptz),
(403207, 4032, 'K3-C3-L2-O07', null, 7, 'أن يختار الطالب الطريقة المناسبة لوزن معادلة أكسدة واختزال (عدد التأكسد أو نصف التفاعل) بعد تحليل المعادلة: تحديد المواد المتأكسدة والمختزلة، وتكرار ظهورها في طرفي المعادلة، ونوع الوسط حمضيًّا أم قاعديًّا.', 'أن يختار الطالب الطريقة المناسبة لوزن معادلة أكسدة واختزال (عدد التأكسد أو نصف التفاعل) بعد تحليل المعادلة: تحديد المواد المتأكسدة والمختزلة، وتكرار ظهورها في طرفي المعادلة، ونوع الوسط حمضيًّا أم قاعديًّا.', '[]'::jsonb, 'أن يختار الطالب الطريقة المناسبة لوزن معادلة أكسدة واختزال (عدد التأكسد أو نصف التفاعل) بعد تحليل المعادلة: تحديد المواد المتأكسدة والمختزلة، وتكرار ظهورها في طرفي المعادلة، ونوع الوسط حمضيًّا أم قاعديًّا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات', '["اختيار طريقة الوزن","طريقة عدد التأكسد","طريقة نصف التفاعل","الطريقة التقليدية في الوزن","الوسط الحمضي","الوسط القاعدي"]'::jsonb, null, '[113,120]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص120 «استراتيجية حل المسألة: وزن معادلات الأكسدة والاختزال»: مخطط يبدأ بتحديد المواد المتأكسدة والمختزلة، وسؤال «هل تظهر المواد التي تأكسدت أو اختزلت أكثر من مرة في طرفي المعادلة؟ وهل يحدث التفاعل في وسط حمضي أم قاعدي؟»، ثم يتفرع إلى خطوات طريقة عدد التأكسد وخطوات طريقة نصف التفاعل، مع تطبيق P₄ → HPO₃²⁻ + PH₃؛ وص113 والملخص: «يصعب وزن معظم معادلات الأكسدة والاختزال باستعمال الطريقة التقليدية» (الشكل 6-3)؛ وسؤال التقويم 32.', null, 'approved', '2026-10-16'::timestamptz),
(404101, 4041, 'K3-C4-L1-O01', null, 1, 'ان يعرف الطالب الكيمياء الكهربائية.', 'أن يعرّف الطالب الكيمياء الكهربائية.', '[]'::jsonb, 'أن يعرّف الطالب الكيمياء الكهربائية.', 'تصحيح همزة «أن» وضبط الفعل «يعرّف» بمعنى يذكر التعريف.', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الكيمياء الكهربائية","الأكسدة والاختزال","تحول الطاقة"]'::jsonb, null, '[134]'::jsonb, 'مغطى', 'يعرّف الكتاب الكيمياء الكهربائية بأنها دراسة عمليات الأكسدة والاختزال التي تتحول من خلالها الطاقة الكيميائية إلى طاقة كهربائية وبالعكس، تحت عنوان «الأكسدة والاختزال في الكيمياء الكهربائية».', null, 'approved', '2026-10-16'::timestamptz),
(404102, 4041, 'K3-C4-L1-O02', null, 2, 'ان يعرف الطالب الخلية الجلفانية.', 'أن يعرّف الطالب الخلية الجلفانية.', '[]'::jsonb, 'أن يعرّف الطالب الخلية الجلفانية.', 'تصحيح همزة «أن» وضبط الفعل «يعرّف».', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الخلية الجلفانية","الخلية الكهروكيميائية","تفاعل الأكسدة والاختزال التلقائي"]'::jsonb, null, '[135,136]'::jsonb, 'مغطى', 'يعرّف الكتاب الخلية الجلفانية بأنها نوع من الخلايا الكهروكيميائية تحول الطاقة الكيميائية إلى طاقة كهربائية بواسطة تفاعل أكسدة واختزال تلقائي (وتسمى الخلايا الفولتية نسبة إلى فولتا)، ويشرح نصف الخلية والأنود (المصعد) موقع الأكسدة والكاثود (المهبط) موقع الاختزال.', null, 'approved', '2026-10-16'::timestamptz),
(404103, 4041, 'K3-C4-L1-O03', null, 3, 'أن يكتب الطالب رمز الخلية الجلفانية', 'أن يكتب الطالب رمز الخلية الجلفانية لتفاعل أكسدة واختزال معطى.', '[]'::jsonb, 'أن يكتب الطالب رمز الخلية الجلفانية لتفاعل أكسدة واختزال معطى.', 'إضافة همزة «أن» وتحديد المعطى ليكون الهدف قابلًا للقياس.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["رمز الخلية","نصف خلية الأنود","نصف خلية الكاثود","القنطرة الملحية (||)"]'::jsonb, null, '[139,140,141]'::jsonb, 'مغطى', 'يقدّم الكتاب «رمز الخلية» مثل H2|H+(1M)||Cu2+(1M)|Cu وZn|Zn2+(1M)||H+(1M)|H2، ويبين في المثال 4-1 قاعدة الكتابة: نصف تفاعل الأكسدة أولًا (المادة المتفاعلة ثم الناتجة) يسارًا ثم نصف الاختزال يمينًا ويُفصل بينهما بخطين عموديين، مثل Fe|Fe2+(1M)||I2|I-(1M).', null, 'approved', '2026-10-16'::timestamptz),
(404104, 4041, 'K3-C4-L1-O04', null, 4, 'ان يعدد الطالب فوائد القنطرة الملحية.', 'أن يوضح الطالب وظائف القنطرة الملحية في الخلية الجلفانية.', '[]'::jsonb, 'أن يوضح الطالب وظائف القنطرة الملحية في الخلية الجلفانية.', 'تصحيح همزة «أن»؛ واستبدال «فوائد» بـ«وظائف» الأدق علميًا.', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["القنطرة الملحية","تراكم الأيونات","إكمال الدائرة","محلول إلكتروليتي KCl"]'::jsonb, null, '[135]'::jsonb, 'مغطى', 'يبين الكتاب أن القنطرة الملحية ممر لتدفق الأيونات من جهة إلى أخرى، أنبوب يحوي محلولًا إلكتروليتيًا (مثل KCl) في جل، تمنع تراكم أيونات الخارصين الموجبة حول الأنود وأيونات الكبريتات السالبة حول الكاثود الذي يوقف التفاعل، وتكمل الدائرة دون اختلاط المحلولين (الشكل 4-2).', null, 'approved', '2026-10-16'::timestamptz),
(404105, 4041, 'K3-C4-L1-O05', null, 5, 'ان يفسر الطالب سبب اختيار العلماء لقطب الهيدروجين القياسي عند قياس جهود الأقطاب الغير معلومة.', 'أن يفسر الطالب سبب استعمال قطب الهيدروجين القياسي مرجعًا عند قياس جهود الأقطاب غير المعلومة.', '[]'::jsonb, 'أن يفسر الطالب سبب استعمال قطب الهيدروجين القياسي مرجعًا عند قياس جهود الأقطاب غير المعلومة.', 'تصحيح «الغير معلومة» إلى «غير المعلومة» وهمزة «أن».', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["قطب الهيدروجين القياسي","جهد الاختزال القياسي","القطب المرجعي","الظروف القياسية"]'::jsonb, null, '[137,138]'::jsonb, 'مغطى', 'يذكر الكتاب أن جهد اختزال القطب لا يمكن تحديده مباشرة لأن نصف تفاعل الاختزال لا بد أن يقترن بنصف تفاعل أكسدة، لذا قرر الكيميائيون قياس جهود الأقطاب جميعها مقابل قطب واحد هو قطب الهيدروجين القياسي (بلاتين في HCl تركيزه 1M مع H2 عند 1atm و25°C) وجُعل جهده 0.000 V، ويعمل مصعدًا أو مهبطًا حسب نصف الخلية الموصول به. ملاحظة: يسمي الكتاب ظروف 25°C و1atm «STP» وهو تجوز.', null, 'approved', '2026-10-16'::timestamptz),
(404106, 4041, 'K3-C4-L1-O06', null, 6, 'ان يحسب الطالب جهد القياسي بعد تحديد التفاعل الكلي للخلية ثم كتابة رمز الخلية مع الرسم.', 'أن يحسب الطالب الجهد القياسي لخلية جلفانية باستعمال جدول جهود الاختزال القياسية بعد تحديد التفاعل الكلي للخلية.', '["أن يحدد الطالب نصفي تفاعل الأكسدة والاختزال والتفاعل الكلي لخلية جلفانية من جدول جهود الاختزال القياسية.","أن يحسب الطالب الجهد القياسي للخلية باستعمال العلاقة E°cell = E°cathode − E°anode.","أن يكتب الطالب رمز الخلية الجلفانية.","أن يرسم الطالب مخططًا لخلية جلفانية يحدد عليه الأنود والكاثود واتجاه تدفق الإلكترونات والقنطرة الملحية."]'::jsonb, 'أن يحسب الطالب الجهد القياسي لخلية جلفانية باستعمال جدول جهود الاختزال القياسية بعد تحديد التفاعل الكلي للخلية.', 'الهدف يجمع أربعة نواتج (تحديد التفاعل، حساب الجهد، كتابة الرمز، الرسم)؛ وتصحيح «جهد القياسي» إلى «الجهد القياسي». كتابة الرمز مكررة مع K3-C4-L1-O03.', 'تقسيم', 'يحتاج تعديلًا', 'تطبيق', 'إجراءات', '["جهد الخلية القياسي","E°cell = E°cathode − E°anode","التفاعل الكلي","رمز الخلية","جدول جهود الاختزال القياسية"]'::jsonb, null, '[139,140,141,142]'::jsonb, 'جزئي', 'يشرح الكتاب حساب الجهد بالعلاقة E°cell = E°cathode − E°anode، مثل خلية Zn–Cu: +0.342 − (−0.762) = +1.104 V (الشكل 4-7)، والمثال 4-1: I2/Fe: +0.536 − (−0.447) = +0.983 V مع كتابة التفاعل الكلي والرمز ومسائل تدريبية 1–4؛ أما الرسم فيظهر في أشكال الكتاب (4-2، 4-6) ولا يُعلَّم إجراءً مستقلًا، ولذلك فالتغطية جزئية لجزء الرسم.', null, 'approved', '2026-10-16'::timestamptz),
(404107, 4041, 'K3-C4-L1-O07', null, 7, 'ان يوضح الطالب استعمال جهود الاختزال القياسية.', 'أن يستعمل الطالب جهود الاختزال القياسية للتنبؤ بتلقائية تفاعل أكسدة واختزال تحت الظروف القياسية.', '[]'::jsonb, 'أن يستعمل الطالب جهود الاختزال القياسية للتنبؤ بتلقائية تفاعل أكسدة واختزال تحت الظروف القياسية.', '«يوضح استعمال» غير محدد وغير قابل للقياس؛ أعيدت الصياغة لتحديد الاستعمال الوارد في الكتاب.', 'صياغة', 'يحتاج تعديلًا', 'تطبيق', 'مبادئ وتعميمات', '["جهود الاختزال القياسية","التلقائية","إشارة جهد الخلية","اتجاه تدفق الإلكترونات"]'::jsonb, null, '[138,142,143]'::jsonb, 'مغطى', 'يوضح الكتاب استعمالين للجدول 4-1: حساب الجهد القياسي للخلايا الجلفانية، والتنبؤ بتلقائية التفاعل؛ فالإلكترونات تتدفق من نصف الخلية الأقل جهد اختزال إلى الأكبر، وإذا كان الجهد المحسوب موجبًا فالتفاعل تلقائي وإذا كان سالبًا فغير تلقائي (مسائل 5–9، واستراتيجية حل المسألة ص143).', null, 'approved', '2026-10-16'::timestamptz),
(404108, 4041, 'K3-C4-L1-O08', null, 8, 'أن يعرّف الطالب كلًّا من: الخلية الكهروكيميائية، ونصف الخلية، والأنود (المصعد)، والكاثود (المهبط).', 'أن يعرّف الطالب كلًّا من: الخلية الكهروكيميائية، ونصف الخلية، والأنود (المصعد)، والكاثود (المهبط).', '[]'::jsonb, 'أن يعرّف الطالب كلًّا من: الخلية الكهروكيميائية، ونصف الخلية، والأنود (المصعد)، والكاثود (المهبط).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["الخلية الكهروكيميائية","نصف الخلية","الأنود","الكاثود","القطب"]'::jsonb, null, '[135,136]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يعرّف الكتاب الخلية الكهروكيميائية بأنها جهاز يستعمل تفاعل الأكسدة والاختزال لإنتاج طاقة كهربائية أو يستعمل الطاقة الكهربائية لإحداث تفاعل كيميائي (ص135)، ثم يبين تحت «كيمياء الخلايا الجلفانية» أن الخلية تتكون من جزأين يسمى كل منهما نصف الخلية يحتوي على قطب ومحلول أيونات، وأن القطب الذي تحدث عنده الأكسدة يسمى الأنود (المصعد) والذي يحدث عنده الاختزال يسمى الكاثود (المهبط)، مع الشكل 4-2 لخلية الخارصين–النحاس (ص136)؛ والمصطلحات واردة في قائمة المفردات الجديدة للقسم 4-1.', null, 'approved', '2026-10-16'::timestamptz),
(404109, 4041, 'K3-C4-L1-O09', null, 9, 'أن يفسر الطالب جهد الخلية بوصفه فرقًا في طاقة الوضع الكهربائية بين القطبين يدفع الإلكترونات من الأنود إلى الكاثود، ويحدد وحدة قياسه.', 'أن يفسر الطالب جهد الخلية بوصفه فرقًا في طاقة الوضع الكهربائية بين القطبين يدفع الإلكترونات من الأنود إلى الكاثود، ويحدد وحدة قياسه.', '[]'::jsonb, 'أن يفسر الطالب جهد الخلية بوصفه فرقًا في طاقة الوضع الكهربائية بين القطبين يدفع الإلكترونات من الأنود إلى الكاثود، ويحدد وحدة قياسه.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["جهد الخلية","طاقة الوضع الكهربائية","الفولت","القوة الدافعة الكهربائية"]'::jsonb, null, '[136,137]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «الخلايا الجلفانية والطاقة» يوضح الكتاب أن الإلكترونات المتكونة عند الأنود تُدفع نحو الكاثود بالقوة الدافعة الكهربائية الناشئة عن فرق طاقة الوضع الكهربائية بين القطبين، وتعرف بجهد الخلية، ووحدتها الفولت، وأنه كلما زاد الفرق في قابلية مادتي القطبين لاكتساب الإلكترونات زاد جهد الخلية؛ مع تشبيه الأفعوانية في الشكل 4-4 ومثال الغواص (ص136–137).', null, 'approved', '2026-10-16'::timestamptz),
(404110, 4041, 'K3-C4-L1-O10', null, 10, 'أن يعرّف الطالب جهد الاختزال وجهد الاختزال القياسي E°، محددًا الظروف القياسية التي يُقاس عندها (تركيز 1M، و25°C، و1atm).', 'أن يعرّف الطالب جهد الاختزال وجهد الاختزال القياسي E°، محددًا الظروف القياسية التي يُقاس عندها (تركيز 1M، و25°C، و1atm).', '[]'::jsonb, 'أن يعرّف الطالب جهد الاختزال وجهد الاختزال القياسي E°، محددًا الظروف القياسية التي يُقاس عندها (تركيز 1M، و25°C، و1atm).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["جهد الاختزال","جهد الاختزال القياسي","الظروف القياسية"]'::jsonb, null, '[137,138]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يعرّف الكتاب جهد الاختزال بأنه مدى قابلية المادة لاكتساب الإلكترونات، ويبين أنه لا يمكن قياسه مباشرة لأن نصف تفاعل الاختزال يقترن دائمًا بنصف تفاعل أكسدة (ص137)، وتحت «جهود نصف الخلية» ينص على وجوب قياس جهد القطب تحت الظروف القياسية بغمسه في محلول أيوناته بتركيز 1M عند 25°C و1atm، وأن الصفر فوق الرمز E° يشير إلى ذلك، مع الجدول 4-1 «جهود الاختزال القياسية» (ص138).', null, 'approved', '2026-10-16'::timestamptz),
(404111, 4041, 'K3-C4-L1-O11', null, 11, 'أن يفسر الطالب دلالة إشارة جهد الاختزال القياسي لقطب ما (موجبة أو سالبة) عند قياسه مقابل قطب الهيدروجين القياسي، مستعملًا قطبي النحاس والخارصين مثالين.', 'أن يفسر الطالب دلالة إشارة جهد الاختزال القياسي لقطب ما (موجبة أو سالبة) عند قياسه مقابل قطب الهيدروجين القياسي، مستعملًا قطبي النحاس والخارصين مثالين.', '[]'::jsonb, 'أن يفسر الطالب دلالة إشارة جهد الاختزال القياسي لقطب ما (موجبة أو سالبة) عند قياسه مقابل قطب الهيدروجين القياسي، مستعملًا قطبي النحاس والخارصين مثالين.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["جهد الاختزال القياسي","قطب الهيدروجين القياسي","إشارة الجهد","اتجاه تدفق الإلكترونات"]'::jsonb, null, '[139,140]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «تحديد جهود اختزال الخلية الكهروكيميائية» يعرض الكتاب توصيل قطب Cu²⁺|Cu بقطب الهيدروجين القياسي فتتدفق الإلكترونات نحو النحاس ويكون E° = +0.342 V، ثم توصيل قطب Zn²⁺|Zn فتتدفق الإلكترونات مبتعدة عن الخارصين ويكون E° = −0.762 V، ويفسر الإشارة السالبة بأن أيونات الهيدروجين تكتسب الإلكترونات أسهل من أيونات الخارصين (الشكل 4-6a,b والشكل 4-7، ص139–140).', null, 'approved', '2026-10-16'::timestamptz),
(404201, 4042, 'K3-C4-L2-O01', null, 1, 'ان يميز الطالب بين البطاريات الأولية والثانوية وتعطي مثالين على كل نوع.', 'أن يميز الطالب بين البطاريات الأولية والبطاريات الثانوية، ويعطي مثالين على كل نوع.', '[]'::jsonb, 'أن يميز الطالب بين البطاريات الأولية والبطاريات الثانوية، ويعطي مثالين على كل نوع.', 'تصحيح همزة «أن» وتوحيد الضمير «تعطي» إلى «يعطي».', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["البطارية الأولية","البطارية الثانوية","بطاريات التخزين","التفاعل العكسي"]'::jsonb, null, '[146,153]'::jsonb, 'مغطى', 'يعرّف الكتاب البطاريات الأولية بأنها تنتج طاقة من تفاعل لا يحدث عكسيًا بسهولة (خلايا الخارصين والكربون والقلوية والفضة)، والثانوية بأنها تعتمد على تفاعل عكسي فيمكن شحنها (بطارية السيارة والحاسوب المحمول وبطاريات NiCad وبطارية المركم الرصاصي الحمضية)؛ وهذا الهدف يطابق نص أهداف الدرس في الكتاب.', null, 'approved', '2026-10-16'::timestamptz),
(404202, 4042, 'K3-C4-L2-O02', null, 2, 'ان يفسر الطالب تركيب خلية الوقود ( الهيدروجين – الاكسجين ) وعملها.', 'أن يصف الطالب تركيب خلية الوقود (الهيدروجين – الأكسجين) وآلية عملها.', '[]'::jsonb, 'أن يصف الطالب تركيب خلية الوقود (الهيدروجين – الأكسجين) وآلية عملها.', 'تصحيح الهمزات؛ و«يصف» أنسب لتركيب الخلية من «يفسر» (هدف الكتاب: «تفسر تركيب خلية الوقود وعملها»).', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["خلية الوقود","أكسدة الهيدروجين","اختزال الأكسجين","المحلول القلوي KOH","غشاء تبادل البروتون PEM"]'::jsonb, null, '[148,149]'::jsonb, 'مغطى', 'يشرح الكتاب أن لخلية الوقود أنودًا وكاثودًا من وعاءين أجوفين من كربون مسامي، ومحلولًا موصلًا قلويًا من KOH، ويكتب نصفي التفاعل: 2H2 + 4OH- → 4H2O + 4e- عند الأنود وO2 + 2H2O + 4e- → 4OH- عند الكاثود، والتفاعل الكلي 2H2 + O2 → 2H2O، ويذكر غشاء تبادل البروتون PEM (الشكل 4-13).', null, 'approved', '2026-10-16'::timestamptz),
(404203, 4042, 'K3-C4-L2-O03', null, 3, 'ان يعرف الطالب التآكل.', 'أن يعرّف الطالب التآكل.', '[]'::jsonb, 'أن يعرّف الطالب التآكل.', 'تصحيح همزة «أن» وضبط الفعل.', 'إملائي', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["التآكل","الصدأ","الأكسدة والاختزال"]'::jsonb, null, '[150]'::jsonb, 'مغطى', 'يعرّف الكتاب التآكل بأنه خسارة الفلز الناتجة عن تفاعل أكسدة واختزال بين الفلز والمواد التي في البيئة، ومثاله تآكل الحديد المعروف بالصدأ.', null, 'approved', '2026-10-16'::timestamptz),
(404204, 4042, 'K3-C4-L2-O04', null, 4, 'ان يصف الطالب عملية تآكل الحديد وطرائق حمايته من التآكل', 'أن يصف الطالب عملية تآكل الحديد بوصفها خلية جلفانية، ويذكر طرائق حمايته من التآكل.', '["أن يصف الطالب عملية تآكل الحديد بكتابة تفاعلات الأنود والكاثود والتفاعل الكلي.","أن يوضح الطالب طرائق حماية الحديد من التآكل (الطلاء، والأنود المضحي، والجلفنة)."]'::jsonb, 'أن يصف الطالب عملية تآكل الحديد بوصفها خلية جلفانية، ويذكر طرائق حمايته من التآكل.', 'الهدف يجمع ناتجين متمايزين (آلية التآكل وطرائق الحماية)؛ مع تصحيح الهمزة.', 'تقسيم', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["تآكل الحديد","الصدأ Fe2O3","الأنود المضحي","الجلفنة","الطلاء"]'::jsonb, null, '[150,151,152,153]'::jsonb, 'مغطى', 'يُدرَّس تآكل الحديد في الدرس 4-2 (البطاريات): يصبح الشق في سطح الحديد أنودًا (Fe → Fe2+ + 2e-) ويقع الكاثود عند حافة قطرة الماء (O2 + 4H+ + 4e- → 2H2O)، ثم يتكوّن الصدأ Fe2O3 والتفاعل الكلي 4Fe + 3O2 → 2Fe2O3، والتآكل أسرع في الماء المالح؛ وطرائق المنع: الطلاء، والأنود المضحي (Mg أو Al أو Ti مع هياكل السفن والأنابيب المدفونة، الشكل 4-17)، والجلفنة بالخارصين (الشكل 4-18).', null, 'approved', '2026-10-16'::timestamptz),
(404205, 4042, 'K3-C4-L2-O05', null, 5, 'ان يتعرف الطالب على الاقطاب في البطاريات المختلفة', 'أن يحدد الطالب الأنود والكاثود والمحلول الموصل (الإلكتروليت) في كل من: خلية الخارصين والكربون الجافة، والبطارية القلوية، وبطارية الفضة، وبطارية NiCad، وبطارية المركم الرصاصي، وبطارية الليثيوم.', '[]'::jsonb, 'أن يحدد الطالب الأنود والكاثود والمحلول الموصل (الإلكتروليت) في كل من: خلية الخارصين والكربون الجافة، والبطارية القلوية، وبطارية الفضة، وبطارية NiCad، وبطارية المركم الرصاصي، وبطارية الليثيوم.', '«يتعرف على» فعل غير قابل للقياس؛ ويُقترح دمج هذا الهدف مع K3-C4-L2-O06 لأنهما يتناولان مكونات البطاريات نفسها.', 'دمج', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الأنود","الكاثود","الكاثود غير الفعال","البطارية الجافة","البطارية القلوية","بطارية الفضة","بطارية NiCad","المركم الرصاصي","بطارية الليثيوم"]'::jsonb, null, '[144,145,146,147,148]'::jsonb, 'مغطى', 'يحدد الكتاب أقطاب كل بطارية: الخارصين والكربون (أنود حافظة الخارصين، كاثود عمود الكربون غير الفعال)، القلوية (أنود مسحوق الخارصين، كاثود MnO2)، الفضة (أنود خارصين، كاثود Ag2O)، NiCad (أنود كادميوم، كاثود NiO(OH))، المركم الرصاصي (أنود Pb، كاثود PbO2)، الليثيوم (أنود ليثيوم، وبعضها كاثود MnO2)، مع نصف التفاعلات.', null, 'approved', '2026-10-16'::timestamptz),
(404206, 4042, 'K3-C4-L2-O06', null, 6, 'ان يتعرف الطالب على الالكتروليتات في البطاريات المختلفة', 'أن يحدد الطالب المحلول الموصل (الإلكتروليت) في البطاريات المختلفة.', '[]'::jsonb, 'أن يحدد الطالب المحلول الموصل (الإلكتروليت) في البطاريات المختلفة.', '«يتعرف على» فعل غير قابل للقياس؛ وهذا الهدف جزء من مكونات البطارية فيُدمج مع K3-C4-L2-O05.', 'دمج', 'يحتاج تعديلًا', 'تذكر', 'حقائق ومصطلحات', '["الإلكتروليت","العجينة الرطبة","هيدروكسيد البوتاسيوم","حمض الكبريتيك"]'::jsonb, null, '[144,145,146,147,149]'::jsonb, 'مغطى', 'يذكر الكتاب الإلكتروليت: في الخلية الجافة عجينة رطبة من ZnCl2 وMnO2 وNH4Cl، وفي القلوية عجينة KOH، وفي NiCad محلول KOH (الشكل 4-10)، وفي المركم الرصاصي محلول حمض الكبريتيك، وفي خلية الوقود محلول KOH أو غشاء PEM؛ ولا يحدد إلكتروليت بطاريات الليثيوم.', null, 'approved', '2026-10-16'::timestamptz),
(404207, 4042, 'K3-C4-L2-O07', null, 7, 'ان يعلل الطالب تفضيل البطارية القلوية على خلية الكربون الخارصين', 'أن يعلل الطالب تفضيل البطارية القلوية على خلية الخارصين والكربون الجافة.', '[]'::jsonb, 'أن يعلل الطالب تفضيل البطارية القلوية على خلية الخارصين والكربون الجافة.', 'تصحيح همزة «أن» واستعمال اسم الخلية كما في الكتاب «خلية الخارصين والكربون».', 'صياغة', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["البطارية القلوية","خلية الخارصين والكربون","مساحة السطح","الكفاءة"]'::jsonb, null, '[145]'::jsonb, 'مغطى', 'يذكر الكتاب أن الخلية القلوية أكثر كفاءة فحلت محل خلية الخارصين والكربون: الخارصين فيها مسحوق يوفر مساحة سطح أكبر، ولا تحتاج إلى عمود كربون فتصنع بأحجام صغيرة، بينما ينخفض جهد خلية الخارصين والكربون (1.5 V) عند تكوّن غاز الأمونيا (الشكل 4-9).', null, 'approved', '2026-10-16'::timestamptz),
(404208, 4042, 'K3-C4-L2-O08', null, 8, 'ان يعلل الطالب خلية الروقود لاتنفذ مثل سائر البطاريات', 'أن يعلل الطالب عدم نفاد خلية الوقود مثل سائر البطاريات.', '[]'::jsonb, 'أن يعلل الطالب عدم نفاد خلية الوقود مثل سائر البطاريات.', 'تصحيح «الروقود لاتنفذ» إلى «الوقود لا تنفد» وإعادة الصياغة لتستقيم العبارة.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["خلية الوقود","التزويد المستمر بالوقود","مصدر خارجي"]'::jsonb, null, '[148,149]'::jsonb, 'مغطى', 'ينص الكتاب على أن خلية الوقود تُزوَّد بالوقود باستمرار من مصدر خارجي، لذا لا تنفد مثل سائر البطاريات وتستمر في إنتاج الكهرباء ما دام الوقود متوافرًا.', null, 'approved', '2026-10-16'::timestamptz),
(404209, 4042, 'K3-C4-L2-O09', null, 9, 'أن يعرّف الطالب كلًّا من البطارية والخلية الجافة.', 'أن يعرّف الطالب كلًّا من البطارية والخلية الجافة.', '[]'::jsonb, 'أن يعرّف الطالب كلًّا من البطارية والخلية الجافة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["البطارية","الخلية الجافة","الخلية الجلفانية"]'::jsonb, null, '[144]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «الخلايا الجافة» يعرّف الكتاب البطارية بأنها خلية جلفانية أو أكثر في عبوة واحدة تنتج التيار الكهربائي، والخلية الجافة بأنها خلية جلفانية يكون المحلول الموصل فيها عجينة رطبة، مع الشكل 4-8 لخلية الخارصين والكربون الجافة؛ والمصطلحان واردان في المفردات الجديدة للقسم 4-2 (ص144).', null, 'approved', '2026-10-16'::timestamptz),
(404210, 4042, 'K3-C4-L2-O10', null, 10, 'أن يكتب الطالب نصفي تفاعل الأنود والكاثود في كل من: خلية الخارصين والكربون الجافة، والبطارية القلوية، وبطارية الفضة، وبطارية NiCad، وبطارية المركم الرصاصي.', 'أن يكتب الطالب نصفي تفاعل الأنود والكاثود في كل من: خلية الخارصين والكربون الجافة، والبطارية القلوية، وبطارية الفضة، وبطارية NiCad، وبطارية المركم الرصاصي.', '[]'::jsonb, 'أن يكتب الطالب نصفي تفاعل الأنود والكاثود في كل من: خلية الخارصين والكربون الجافة، والبطارية القلوية، وبطارية الفضة، وبطارية NiCad، وبطارية المركم الرصاصي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["أنصاف التفاعلات","تفاعل الأنود","تفاعل الكاثود","البطاريات"]'::jsonb, null, '[144,145,146]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يورد الكتاب أنصاف التفاعلات لكل بطارية: Zn → Zn²⁺ + 2e⁻ و2NH₄⁺ + 2MnO₂ + 2e⁻ → Mn₂O₃ + 2NH₃ + H₂O للخلية الجافة (ص144)؛ Zn + 2OH⁻ → ZnO + H₂O + 2e⁻ وMnO₂ + 2H₂O + 2e⁻ → Mn(OH)₂ + 2OH⁻ للقلوية، وAg₂O + H₂O + 2e⁻ → 2Ag + 2OH⁻ لكاثود بطارية الفضة (ص145)؛ Cd + 2OH⁻ → Cd(OH)₂ + 2e⁻ وNiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻ لبطارية NiCad، وPb + SO₄²⁻ → PbSO₄ + 2e⁻ وPbO₂ + 4H⁺ + SO₄²⁻ + 2e⁻ → PbSO₄ + 2H₂O مع التفاعل الكلي للمركم الرصاصي (ص146).', null, 'approved', '2026-10-16'::timestamptz),
(404211, 4042, 'K3-C4-L2-O11', null, 11, 'أن يوضح الطالب دور كل من عمود الكربون (الكاثود غير الفعال) والفواصل المسامية في خلية الخارصين والكربون الجافة، وسبب انخفاض جهدها عند نفادها.', 'أن يوضح الطالب دور كل من عمود الكربون (الكاثود غير الفعال) والفواصل المسامية في خلية الخارصين والكربون الجافة، وسبب انخفاض جهدها عند نفادها.', '[]'::jsonb, 'أن يوضح الطالب دور كل من عمود الكربون (الكاثود غير الفعال) والفواصل المسامية في خلية الخارصين والكربون الجافة، وسبب انخفاض جهدها عند نفادها.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الخلية الجافة","الكاثود غير الفعال","الفواصل المسامية","القنطرة الملحية"]'::jsonb, null, '[144,145]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يبين الكتاب أن عمود الكربون في مركز الخلية الجافة يسمى الكاثود غير الفعال لأنه لا يسهم في تفاعل الأكسدة والاختزال لكنه يوصل الإلكترونات، وأن الاختزال يحدث داخل العجينة (ص144)، وأن الفواصل المسامية تعمل عمل القنطرة الملحية للسماح بحركة الأيونات، وأن الخلية تنتج 1.5 V حتى يبدأ انطلاق الأمونيا غازًا فينخفض الجهد إلى مستوى يجعل البطارية غير نافعة (ص145).', null, 'approved', '2026-10-16'::timestamptz),
(404212, 4042, 'K3-C4-L2-O12', null, 12, 'أن يصف الطالب ما يحدث في بطارية المركم الرصاصي عند توليد التيار وعند إعادة الشحن، محددًا المواد التي تتأكسد والتي تُختزل في كل حالة.', 'أن يصف الطالب ما يحدث في بطارية المركم الرصاصي عند توليد التيار وعند إعادة الشحن، محددًا المواد التي تتأكسد والتي تُختزل في كل حالة.', '[]'::jsonb, 'أن يصف الطالب ما يحدث في بطارية المركم الرصاصي عند توليد التيار وعند إعادة الشحن، محددًا المواد التي تتأكسد والتي تُختزل في كل حالة.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["بطارية المركم الرصاصي","إعادة الشحن","حمض الكبريتيك","كبريتات الرصاص II"]'::jsonb, null, '[146,147]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يصف الكتاب تركيب بطارية السيارة (6 خلايا × 2V = 12V، أنود من الرصاص وكاثود من PbO₂ ومحلول حمض الكبريتيك) وتأكسد Pb من 0 إلى +2 واختزال Pb من +4 إلى +2 وتكوّن PbSO₄ الصلبة (ص146)، ويبين أن حمض الكبريتيك يُستهلك أثناء توليد التيار وأن التفاعل ينعكس عند الشحن لينتج Pb وPbO₂ وحمض الكبريتيك، مع سؤال «ماذا قرأت؟» عن المواد التي تتأكسد وتختزل عند الشحن والشكل 4-11 (ص147).', null, 'approved', '2026-10-16'::timestamptz),
(404213, 4042, 'K3-C4-L2-O13', null, 13, 'أن يعلل الطالب اختيار الليثيوم لصناعة البطاريات، ويذكر مزايا بطاريات الليثيوم.', 'أن يعلل الطالب اختيار الليثيوم لصناعة البطاريات، ويذكر مزايا بطاريات الليثيوم.', '[]'::jsonb, 'أن يعلل الطالب اختيار الليثيوم لصناعة البطاريات، ويذكر مزايا بطاريات الليثيوم.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["بطاريات الليثيوم","جهد الاختزال القياسي","خفة الوزن"]'::jsonb, null, '[147,148]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «بطاريات الليثيوم» يبين الكتاب أن المهندسين ركزوا على الليثيوم لأنه أخف فلز معروف وله أقل جهد اختزال قياسي (−3.04 V) بين العناصر الفلزية، فتولد البطارية التي تؤكسده جهدًا أكبر بنحو 2.3 V من المشابهة التي تؤكسد الخارصين، وأنها قد تكون أولية أو ثانوية، وتنتج 3 V مقارنة بـ1.5 V للخارصين والكربون وتستمر فترة أطول، مع سؤال «اذكر ثلاث مزايا لبطاريات الليثيوم» والشكل 4-12 (ص147–148).', null, 'approved', '2026-10-16'::timestamptz),
(404301, 4043, 'K3-C4-L3-O01', null, 1, 'أن يصف الطالب كيف يمكن عكس تفاعل الاكسدة والاختزال التلقائي في الخلية الكهروكيميائية', 'أن يصف الطالب كيف يمكن عكس تفاعل الأكسدة والاختزال التلقائي في الخلية الكهروكيميائية.', '[]'::jsonb, 'أن يصف الطالب كيف يمكن عكس تفاعل الأكسدة والاختزال التلقائي في الخلية الكهروكيميائية.', 'تصحيح همزة «الأكسدة».', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مفاهيم', '["التحليل الكهربائي","خلية التحليل الكهربائي","التفاعل غير التلقائي","مصدر طاقة خارجي","إعادة الشحن"]'::jsonb, null, '[154]'::jsonb, 'مغطى', 'يشرح الكتاب أن الخلية يمكن تجديدها بتزويدها بتيار في الاتجاه المعاكس من مصدر طاقة خارجي لأن التفاعل العكسي غير تلقائي، ويعرّف التحليل الكهربائي بأنه استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي، وخلية التحليل الكهربائي، ومثاله إعادة شحن البطارية الثانوية (الشكل 4-19).', null, 'approved', '2026-10-16'::timestamptz),
(404302, 4043, 'K3-C4-L3-O02', null, 2, 'أن يقارن الطالب التفاعلات المرتبطة مع التحليل الكهربائي لمصهور كلوريد الصوديوم بالتفاعلات المرتبطة مع التحليل الكهربائي لماء البحر.', 'أن يقارن الطالب بين التفاعلات المصاحبة للتحليل الكهربائي لمصهور كلوريد الصوديوم والتفاعلات المصاحبة للتحليل الكهربائي لماء البحر من حيث تفاعلات الأنود والكاثود والنواتج.', '[]'::jsonb, 'أن يقارن الطالب بين التفاعلات المصاحبة للتحليل الكهربائي لمصهور كلوريد الصوديوم والتفاعلات المصاحبة للتحليل الكهربائي لماء البحر من حيث تفاعلات الأنود والكاثود والنواتج.', 'تصحيح «الاكسدة» وتحديد أوجه المقارنة لتكون قابلة للقياس.', 'صياغة', 'يحتاج تعديلًا', 'تحليل', 'مفاهيم', '["خلية داون","مصهور NaCl","ماء البحر","الاختزال التفضيلي","Na وCl2 وH2 وNaOH"]'::jsonb, null, '[155,156,158]'::jsonb, 'مغطى', 'يعرض الكتاب خلية داون: عند الأنود 2Cl- → Cl2 + 2e- وعند الكاثود Na+ + e- → Na، والكلي 2Na+ + 2Cl- → 2Na + Cl2؛ وفي ماء البحر يُختزل الماء بدل Na+ (2H2O + 2e- → H2 + 2OH-) ويتأكسد Cl- إلى Cl2، والكلي 2H2O + 2NaCl → H2 + Cl2 + 2NaOH (الشكل 4-21)، وتلخص الخلاصة اختلاف النواتج؛ وهو نص هدف الكتاب نفسه.', null, 'approved', '2026-10-16'::timestamptz),
(404303, 4043, 'K3-C4-L3-O03', null, 3, 'ان يقارن الطالب بين الخلية الجلفانية والتحليل الكهربائي', 'أن يقارن الطالب بين الخلية الجلفانية وخلية التحليل الكهربائي من حيث تحول الطاقة وتلقائية التفاعل ومصدر الطاقة.', '[]'::jsonb, 'أن يقارن الطالب بين الخلية الجلفانية وخلية التحليل الكهربائي من حيث تحول الطاقة وتلقائية التفاعل ومصدر الطاقة.', 'المقارنة بين «خلية» و«عملية» غير متكافئة؛ فصُحح الطرف الثاني إلى «خلية التحليل الكهربائي» وحُددت أوجه المقارنة.', 'صياغة', 'يحتاج تعديلًا', 'تحليل', 'مفاهيم', '["الخلية الجلفانية","خلية التحليل الكهربائي","التلقائية","تحول الطاقة"]'::jsonb, null, '[154,155]'::jsonb, 'مغطى', 'يقارن الكتاب الخليتين في الشكل 4-19 (خلية Zn–Cu جلفانية تضيء مصباحًا بتفاعل تلقائي، وخلية تحليل بمصدر جهد خارجي يعكس تدفق الإلكترونات)، وينص في «تطبيقات التحليل الكهربائي» على أن الخلايا الجلفانية تحول الطاقة الكيميائية إلى كهربائية نتيجة تفاعل تلقائي، بينما تستعمل خلايا التحليل الكهربائي الطاقة الكهربائية لإحداث تفاعل غير تلقائي.', null, 'approved', '2026-10-16'::timestamptz),
(404304, 4043, 'K3-C4-L3-O04', null, 4, 'ان يعلل الطالب عدم انتاج الصوديوم من التحليل الكهربائي لماء البحر', 'أن يعلل الطالب عدم إنتاج الصوديوم من التحليل الكهربائي لماء البحر.', '[]'::jsonb, 'أن يعلل الطالب عدم إنتاج الصوديوم من التحليل الكهربائي لماء البحر.', 'تصحيح همزتي «أن» و«إنتاج».', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["ماء البحر","الاختزال التفضيلي","جهد الاختزال"]'::jsonb, null, '[156]'::jsonb, 'مغطى', 'ينص الكتاب على أن اختزال أيونات Na+ لا يحدث في ماء البحر لأن اختزال الهيدروجين في جزيئات الماء أسهل حدوثًا فيحدث الاختزال التفضيلي للماء، وتعلق الشكل 4-21: لا ينتج الصوديوم لأن جزيئات الماء لديها ميل للاختزال أكثر من الصوديوم.', null, 'approved', '2026-10-16'::timestamptz),
(404305, 4043, 'K3-C4-L3-O05', null, 5, 'ان يعلل الطالب سبب توصيل محلول و او مصهور ملح الطعام للتيار الكهربائي', 'أن يعلل الطالب توصيل محلول ملح الطعام أو مصهوره للتيار الكهربائي.', '[]'::jsonb, 'أن يعلل الطالب توصيل محلول ملح الطعام أو مصهوره للتيار الكهربائي.', 'تصحيح «و او» إلى «أو» والهمزات وتحسين الصياغة.', 'إملائي', 'يحتاج تعديلًا', 'فهم', 'مبادئ وتعميمات', '["المركبات الأيونية","الأيونات الحرة الحركة","المصهور","المحلول المائي"]'::jsonb, null, '[155]'::jsonb, 'مغطى', 'يذكر الكتاب ضمن خلية داون أن المركبات الأيونية لا يمكنها توصيل التيار الكهربائي إلا عندما تكون أيوناتها حرة الحركة، وذلك عند ذوبانها في الماء أو انصهارها، ويسأل: لماذا يجب أن يكون كلوريد الصوديوم مصهورًا في خلية داون؟', null, 'approved', '2026-10-16'::timestamptz),
(404306, 4043, 'K3-C4-L3-O06', null, 6, 'أن يعرّف الطالب التحليل الكهربائي وخلية التحليل الكهربائي.', 'أن يعرّف الطالب التحليل الكهربائي وخلية التحليل الكهربائي.', '[]'::jsonb, 'أن يعرّف الطالب التحليل الكهربائي وخلية التحليل الكهربائي.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["التحليل الكهربائي","خلية التحليل الكهربائي","التفاعل غير التلقائي"]'::jsonb, null, '[154]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يعرّف الكتاب التحليل الكهربائي بأنه استعمال الطاقة الكهربائية لإحداث تفاعل كيميائي، وخلية التحليل الكهربائي بأنها الخلية الكهروكيميائية التي يحدث فيها تحليل كهربائي، ومثالها البطارية الثانوية عند إعادة شحنها؛ والمصطلحان في المفردات الجديدة للقسم 4-3 مع الشكل 4-19 (ص154).', null, 'approved', '2026-10-16'::timestamptz),
(404307, 4043, 'K3-C4-L3-O07', null, 7, 'أن يكتب الطالب المعادلة الكلية للتحليل الكهربائي للماء، ويبين علاقته بتفاعل خلية الوقود وأهميته في إنتاج الهيدروجين.', 'أن يكتب الطالب المعادلة الكلية للتحليل الكهربائي للماء، ويبين علاقته بتفاعل خلية الوقود وأهميته في إنتاج الهيدروجين.', '[]'::jsonb, 'أن يكتب الطالب المعادلة الكلية للتحليل الكهربائي للماء، ويبين علاقته بتفاعل خلية الوقود وأهميته في إنتاج الهيدروجين.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تطبيق', 'إجراءات', '["التحليل الكهربائي للماء","خلية الوقود","إنتاج الهيدروجين"]'::jsonb, null, '[155]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «تطبيقات التحليل الكهربائي» يذكر الكتاب أن من الأمثلة الشائعة التحليل الكهربائي للماء 2H₂O → 2H₂ + O₂، وأنه عكس احتراق الهيدروجين في خلية الوقود، وأنه إحدى طرائق إنتاج الهيدروجين لاستعمالات تجارية، مع تجربة عملية «تحليل الماء كهربائيًّا» (ص155).', null, 'approved', '2026-10-16'::timestamptz),
(404308, 4043, 'K3-C4-L3-O08', null, 8, 'أن يذكر الطالب استعمالات نواتج التحليل الكهربائي لمصهور كلوريد الصوديوم (خلية داون) ولماء البحر.', 'أن يذكر الطالب استعمالات نواتج التحليل الكهربائي لمصهور كلوريد الصوديوم (خلية داون) ولماء البحر.', '[]'::jsonb, 'أن يذكر الطالب استعمالات نواتج التحليل الكهربائي لمصهور كلوريد الصوديوم (خلية داون) ولماء البحر.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["خلية داون","الصوديوم","الكلور","هيدروكسيد الصوديوم","الهيدروجين"]'::jsonb, null, '[155,156]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). يبين الكتاب أهمية خلية داون (الشكل 4-20) بالدور الذي يؤديه الصوديوم والكلور: استعمال الكلور في تنقية مياه الشرب والسباحة والمبيضات ومعالجة الورق والبلاستيك والمبيدات والأصباغ، واستعمال الصوديوم مبرِّدًا في المفاعلات النووية وفي مصابيح الصوديوم الغازية (ص155)، ثم يذكر أن الهيدروجين والكلور وهيدروكسيد الصوديوم الناتجة عن التحليل الكهربائي لماء البحر مواد ذات أهمية تجارية، وأن الكلور يستعمل في صناعة بوليمر كلوريد الفينيل للأنابيب (الشكل 4-21، ص156).', null, 'approved', '2026-10-16'::timestamptz),
(404309, 4043, 'K3-C4-L3-O09', null, 9, 'أن يصف الطالب إنتاج الألومنيوم بطريقة هول–هيروليت، محددًا مكونات الخلية وتفاعلي الأنود والكاثود.', 'أن يصف الطالب إنتاج الألومنيوم بطريقة هول–هيروليت، محددًا مكونات الخلية وتفاعلي الأنود والكاثود.', '[]'::jsonb, 'أن يصف الطالب إنتاج الألومنيوم بطريقة هول–هيروليت، محددًا مكونات الخلية وتفاعلي الأنود والكاثود.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["إنتاج الألومنيوم","عملية هول–هيروليت","البوكسيت","الكريوليت","أقطاب الجرافيت"]'::jsonb, null, '[156,157]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «إنتاج الألومنيوم» يعرض الكتاب تاريخ العملية (هول وهيروليت 1886م) ثم يصف إذابة أكسيد الألومنيوم المستخلص من البوكسيت Al₂O₃·2H₂O في مصهور الكريوليت Na₃AlF₆ عند 1000°C، وبطانة الجرافيت كاثودًا يحدث عنده Al³⁺ + 3e⁻ → Al، وأصابع الجرافيت أنودًا يحدث عنده 2O²⁻ → O₂ + 4e⁻ ثم تفاعل الأكسجين مع الكربون C + O₂ → CO₂، مع الشكل 4-22 وسؤال «فسر لماذا يجب استبدال قضبان الجرافيت باستمرار» (ص156–157).', null, 'approved', '2026-10-16'::timestamptz),
(404310, 4043, 'K3-C4-L3-O10', null, 10, 'أن يعلل الطالب أهمية إعادة تدوير الألومنيوم بالرجوع إلى استهلاك عملية هول–هيروليت للطاقة الكهربائية.', 'أن يعلل الطالب أهمية إعادة تدوير الألومنيوم بالرجوع إلى استهلاك عملية هول–هيروليت للطاقة الكهربائية.', '[]'::jsonb, 'أن يعلل الطالب أهمية إعادة تدوير الألومنيوم بالرجوع إلى استهلاك عملية هول–هيروليت للطاقة الكهربائية.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وتعميمات', '["إعادة تدوير الألومنيوم","استهلاك الطاقة","عملية هول–هيروليت"]'::jsonb, null, '[157,158]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ينص الكتاب على أن عملية هول–هيروليت تستهلك كميات ضخمة من الطاقة الكهربائية فتقام المصانع قرب محطات الطاقة، وأن الكمية الهائلة من الكهرباء اللازمة لإنتاج الألومنيوم من خامه هي السبب الأولي لإعادة تدويره، إذ لا يحتاج الألومنيوم المعاد تدويره إلا إلى حرارة صهره، مع الشكل 4-22 (ص157)، وسؤال التقويم 25 «أهمية إعادة تدوير الألومنيوم» (ص158).', null, 'approved', '2026-10-16'::timestamptz),
(404311, 4043, 'K3-C4-L3-O11', null, 11, 'أن يصف الطالب تنقية النحاس بالتحليل الكهربائي، محددًا الأنود والكاثود والمحلول والتفاعل عند كل قطب ومصير الشوائب.', 'أن يصف الطالب تنقية النحاس بالتحليل الكهربائي، محددًا الأنود والكاثود والمحلول والتفاعل عند كل قطب ومصير الشوائب.', '[]'::jsonb, 'أن يصف الطالب تنقية النحاس بالتحليل الكهربائي، محددًا الأنود والكاثود والمحلول والتفاعل عند كل قطب ومصير الشوائب.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["تنقية الفلزات","تنقية النحاس","التحليل الكهربائي","كبريتات النحاس II"]'::jsonb, null, '[157,158]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «تنقية الخامات» يبين الكتاب استخلاص النحاس من خاماته (الكالكوبايرايت والكالكوسايت والملاكايت) بتسخين الكبريتيدات Cu₂S + O₂ → 2Cu + SO₂ (ص157)، ثم تنقيته بصب النحاس غير النقي في قوالب تعمل أنودًا في خلية تحليل كهربائي محلولها كبريتات النحاس II وكاثودها شريحة رقيقة من النحاس النقي؛ فيتأكسد النحاس غير النقي عند الأنود وتختزل أيوناته عند الكاثود وتترسب الشوائب في قاع الخلية، مع سؤال التقويم 24 (ص158).', null, 'approved', '2026-10-16'::timestamptz),
(404312, 4043, 'K3-C4-L3-O12', null, 12, 'أن يصف الطالب الطلاء الكهربائي لجسم بفلز (مثل الفضة)، محددًا الأنود والكاثود ونصفي التفاعل عندهما.', 'أن يصف الطالب الطلاء الكهربائي لجسم بفلز (مثل الفضة)، محددًا الأنود والكاثود ونصفي التفاعل عندهما.', '[]'::jsonb, 'أن يصف الطالب الطلاء الكهربائي لجسم بفلز (مثل الفضة)، محددًا الأنود والكاثود ونصفي التفاعل عندهما.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["الطلاء الكهربائي","الطلاء بالفضة","خلية التحليل الكهربائي"]'::jsonb, null, '[158]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). تحت «الطلاء بالكهرباء» يبين الكتاب أن الجسم المراد طلاؤه يوصل بكاثود خلية تحليل كهربائي ويكون الأنود قطعة فضة نقية، فتتأكسد الفضة عند الأنود Ag → Ag⁺ + e⁻ وتختزل أيونات الفضة عند الكاثود Ag⁺ + e⁻ → Ag مكونة طبقة رقيقة تغلف الجسم، مع ضرورة التحكم في شدة التيار، وأمثلة الطلاء بالذهب والنيكل والكروم (الشكل 4-23)، وسؤال التقويم 26 عن الأنود والكاثود في خلية الطلاء بالذهب (ص158).', null, 'approved', '2026-10-16'::timestamptz)
on conflict do nothing;

insert into public.supplements (objective_id, memo_basis, supplement, key_points, misconceptions, scientific_notes, confidence) values
(401107, 'يذكر الكتاب (ص14، الشكل 1-1) أن المخلوط المعلق يحتوي على جسيمات يمكن أن تترسب بالترويق؛ وذلك بتركه فترة دون تحريك، وأن الترشيح يفصل الجسيمات المعلقة، دون تعريف مستقل للترويق.', 'الترويق طريقة لفصل مكونات المخلوط المعلق، تعتمد على ترك المخلوط فترة دون تحريك حتى تترسب جسيماته الكبيرة نسبيًّا في القاع بفعل الجاذبية، ثم يُسكب السائل الرائق الذي فوقها بهدوء في وعاء آخر دون إثارة الراسب. ينجح الترويق لأن جسيمات المعلق كبيرة وثقيلة نسبيًّا، أما جسيمات المحلول فلا تترسب لأنها ذائبة، وجسيمات المخلوط الغروي لا تترسب أيضًا؛ لذلك لا يصلح الترويق لفصلهما. مثال: عند ترك الماء الموحل فترة دون تحريك يترسب الطين في القاع ويصبح الماء فوقه أكثر صفاءً، فيُسكب بعيدًا عن الراسب. وغالبًا ما يكون الفصل بالترويق غير تام، فيُتبَع بالترشيح لإزالة ما بقي من جسيمات معلقة.', '["الترويق: ترك المخلوط المعلق دون تحريك حتى تترسب جسيماته، ثم سكب السائل الرائق فوق الراسب.","يعتمد على ترسب الجسيمات الكبيرة بفعل الجاذبية.","يصلح للمخلوط المعلق فقط، ولا يفصل مكونات المحلول أو المخلوط الغروي.","الفصل بالترويق غير تام غالبًا، ويمكن إتباعه بالترشيح."]'::jsonb, '["أن الترويق يفصل المادة المذابة عن المذيب في المحلول (مثل الملح من الماء).","أن الترويق والترشيح طريقة واحدة؛ فالترويق يعتمد على الترسب والسكب، والترشيح على ورقة الترشيح.","أن السائل الناتج من الترويق نقي تمامًا."]'::jsonb, 'يُستعمل مصطلح «الترويق» أحيانًا للدلالة على مرحلة الترسيب وحدها، وأحيانًا على السكب بعدها؛ والكتاب يستعمله بمعنى الترسيب بترك المخلوط دون تحريك، فيُقدَّم السكب امتدادًا لذلك المعنى لا تعارضًا معه.', 'high'),
(401110, 'يصنف الكتاب الضباب هباءً جويًّا سائلًا (الجدول 1-1)، ويذكر أن تأثير تندال يُلاحظ عند مرور الضوء خلال الضباب (ص16)، ويطرح قيادة السيارة في الضباب سؤالًا في التقويم 1-1 (س4، ص18) دون شرح في المتن.', 'الضباب مخلوط فيه قطيرات ماء صغيرة منتشرة في الهواء. عندما يسقط ضوء مصابيح السيارة على هذه القطيرات فإنها تشتته في اتجاهات مختلفة (تأثير تندال)، فيرتد جزء من الضوء المشتت نحو عيني السائق، فيرى أمامه ما يشبه ستارة مضيئة تحجب الطريق والأجسام البعيدة، وتقل قدرته على تمييزها. وتكون القيادة بالأنوار العالية أصعب؛ لأن حزمتها قوية وموجهة إلى الأمام والأعلى، فتسقط على عدد أكبر من قطيرات الضباب أمام السيارة وفي مستوى نظر السائق، فيزداد الضوء المشتت المرتد نحوه. أما الأنوار المنخفضة فموجهة إلى أسفل نحو سطح الطريق، فيقل الضوء المشتت في مستوى عيني السائق؛ لذلك يُنصح في الضباب باستعمال الأنوار المنخفضة أو مصابيح الضباب المثبتة في أسفل السيارة.', '["قطيرات الماء في الضباب تشتت الضوء (تأثير تندال).","الضوء المشتت المرتد نحو السائق يحجب الرؤية ويقلل وضوح الطريق.","الأنوار العالية تضيء عددًا أكبر من القطيرات في مستوى النظر فيزداد التشتت المرتد.","الأنوار المنخفضة ومصابيح الضباب تقلل الضوء المشتت أمام عيني السائق."]'::jsonb, '["أن الضباب يمتص الضوء فقط؛ والسبب الرئيس لضعف الرؤية هو تشتيت الضوء.","أن زيادة شدة الإضاءة تحسن الرؤية دائمًا في الضباب.","أن تأثير تندال يحدث في المحاليل أيضًا؛ فالمحاليل لا تُظهر هذه الظاهرة."]'::jsonb, 'قد يكون كثير من قطيرات الضباب الحقيقي أكبر من المدى المعتاد لجسيمات الغرويات، لكن الكتاب يصنف الضباب هباءً جويًّا سائلًا، والتفسير بتشتيت القطيرات للضوء صحيح في الحالتين. وتشتيت الضوء هو السبب الرئيس، وتسهم عوامل أخرى كضعف التباين في صعوبة الرؤية.', 'high'),
(402118, 'يذكر الكتاب (ص65) أن بعض الأكاسيد تتحد مع الماء مكوّنة قواعد؛ فأكسيد الكالسيوم CaO (الجير الحي) يكوّن هيدروكسيد الكالسيوم Ca(OH)2 (الجير المطفأ)، وأن أكاسيد العناصر الفلزية عمومًا تكوّن القواعد، دون استعمال مصطلح «أنهيدريد قاعدي».', 'الأنهيدريد القاعدي أكسيد فلزي يتحد مع الماء فيكوّن قاعدة (هيدروكسيدًا فلزيًّا). وكلمة «أنهيدريد» تعني «بلا ماء»؛ أي أن الأكسيد يمثل القاعدة بعد نزع الماء منها. ومن أشهر الأمثلة أكاسيد فلزات المجموعتين 1 و2:
CaO(s) + H2O(l) → Ca(OH)2(aq)
Na2O(s) + H2O(l) → 2NaOH(aq)
ويقابله الأنهيدريد الحمضي، وهو أكسيد لافلزي يتحد مع الماء مكوّنًا حمضًا، مثل SO3 الذي يكوّن H2SO4. ويتفاعل الأنهيدريد القاعدي مع الأحماض مكوّنًا ملحًا وماءً، فمثلًا: MgO + 2HCl → MgCl2 + H2O، ويتفاعل مع الأنهيدريد الحمضي مكوّنًا ملحًا، مثل تفاعل MgO مع SO3 لتكوين MgSO4 الذي يذكره الكتاب.', '["الأنهيدريد القاعدي: أكسيد فلز يكوّن قاعدة عند اتحاده بالماء.","مثال: CaO + H2O → Ca(OH)2 (الجير الحي يتحول إلى الجير المطفأ).","الأنهيدريد الحمضي يقابله: أكسيد لافلز يكوّن حمضًا مع الماء، مثل SO3.","يتفاعل الأنهيدريد القاعدي مع الأحماض مكوّنًا ملحًا وماءً."]'::jsonb, '["أن الأنهيدريد القاعدي يحتوي على أيون OH− في صيغته.","أن كل الأكاسيد تكوّن قواعد مع الماء؛ فأكاسيد اللافلزات تكوّن أحماضًا.","أن كل أكسيد فلزي يذوب في الماء بالضرورة."]'::jsonb, 'بعض أكاسيد الفلزات لا تذوب في الماء تقريبًا (مثل CuO وFe2O3)، لكنها تُعد قاعدية لتفاعلها مع الأحماض. وبعض الأكاسيد مترددة تسلك سلوك الحمض والقاعدة معًا (مثل Al2O3 وZnO)، فلا تنطبق عليها القاعدة العامة «أكسيد الفلز = قاعدي» تمامًا.', 'high'),
(402408, 'يعرض الكتاب أهمية المحاليل المنظمة في الكائنات الحية: الحفاظ على pH الدم بين 7.1 و7.7 بنظام H2CO3/HCO3−، وpH العصارة المعدية بين 1.6 و1.8، وpH أحواض الأحياء المائية بين 8.1 و8.4 (ص88، 90)، دون تطبيقات صناعية أو طبية أو مخبرية.', 'المحلول المنظم يقاوم التغير في قيمة pH عند إضافة كميات قليلة من حمض أو قاعدة، لذلك يُستعمل في كل مجال يحتاج إلى pH ثابت تقريبًا، ومن ذلك:
1. المختبرات: معايرة أجهزة قياس pH بمحاليل منظمة معلومة القيمة، والحفاظ على pH مناسب في التجارب الحيوية؛ لأن الإنزيمات لا تعمل بكفاءة إلا ضمن مدى محدد من pH.
2. الطب والصيدلة: تُضاف محاليل منظمة إلى بعض الأدوية وقطرات العين والمحاليل الوريدية لتبقى قيمة pH مناسبة للجسم ولثبات الدواء.
3. الصناعات الغذائية ومستحضرات العناية: ضبط pH بعض الأغذية والمشروبات والشامبو ومستحضرات البشرة.
4. الصناعة: عمليات تتأثر بقيمة pH مثل التخمير والصباغة والطلاء الكهربائي.
وفي جسم الإنسان يعد نظام H2CO3/HCO3− في الدم مثالًا مهمًّا، كما ورد في الكتاب.', '["تُستعمل المحاليل المنظمة حيثما يلزم الحفاظ على pH شبه ثابت.","المختبر: معايرة أجهزة قياس pH، وحماية عمل الإنزيمات في التجارب.","الطب والصيدلة: الأدوية وقطرات العين والمحاليل الوريدية.","الغذاء ومستحضرات العناية والصناعة كالتخمير والصباغة.","في الجسم: نظام H2CO3/HCO3− يحافظ على pH الدم."]'::jsonb, '["أن المحلول المنظم يبقي pH ثابتًا مهما أضيف إليه من حمض أو قاعدة؛ فله سعة محدودة.","أن pH المحلول المنظم يساوي 7 دائمًا؛ فهناك محاليل منظمة حمضية وأخرى قاعدية.","أن أي خليط من حمض وقاعدة يكوّن محلولًا منظمًا؛ فالمحلول المنظم يتكون عادة من حمض ضعيف وقاعدته المرافقة أو قاعدة ضعيفة وحمضها المرافق."]'::jsonb, 'الأمثلة الصناعية والطبية المذكورة إثراء عام لا يتضمنه الكتاب؛ ولم تُذكر قيم pH محددة لها تجنبًا لاختلافها من منتج إلى آخر.', 'medium'),
(403101, 'يذكر الكتاب (ص104–105) أن كلمة الأكسدة أُطلقت فيما مضى على التفاعلات التي تتضمن اتحاد المادة بالأكسجين، ثم يعرّف الأكسدة بفقد الإلكترونات والاختزال باكتسابها، ولا يورد المفهوم القديم للاختزال.', 'قديمًا عرّف الكيميائيون الأكسدة بأنها اتحاد المادة بالأكسجين، مثل احتراق المغنيسيوم: 2Mg + O2 → 2MgO، وصدأ الحديد. وعرّفوا الاختزال بأنه نزع الأكسجين من المركب، وارتبط ذلك باستخلاص الفلزات من خاماتها (أكاسيدها)، مثل:
CuO + H2 → Cu + H2O
Fe2O3 + 3CO → 2Fe + 3CO2
ففي التفاعل الأول اختُزل أكسيد النحاس(II) إلى نحاس، وتأكسد الهيدروجين إلى ماء؛ أي أن الأكسدة والاختزال يحدثان معًا. ثم وُسّع المفهوم ليشمل تفاعلات لا يدخل فيها الأكسجين، مثل 2Na + Cl2 → 2NaCl، فأصبحت الأكسدة فقد الإلكترونات، والاختزال اكتسابها، كما في الكتاب. والتعريف الحديث يشمل القديم؛ ففي تكوين MgO يفقد Mg إلكترونين فيتأكسد إلى Mg2+، ويكتسبهما الأكسجين فيُختزل إلى O2−.', '["الأكسدة قديمًا: اتحاد المادة بالأكسجين.","الاختزال قديمًا: نزع الأكسجين من المركب، كاختزال أكاسيد الفلزات إلى فلزات.","الأكسدة والاختزال يحدثان معًا في التفاعل نفسه.","التعريف الحديث بانتقال الإلكترونات أعم ويشمل التفاعلات التي لا يدخلها الأكسجين."]'::jsonb, '["أن الأكسدة تحتاج دائمًا إلى وجود الأكسجين.","أن الأكسدة يمكن أن تحدث وحدها دون اختزال.","أن المفهومين القديم والحديث متعارضان؛ والصحيح أن الحديث يوسّع القديم ويشمله."]'::jsonb, 'المفهوم القديم محدود لأنه لا يفسر تفاعلات مثل تكوين NaCl من Na وCl2، ولذلك اعتُمد تعريف انتقال الإلكترونات. وتذكر بعض المراجع أيضًا تعريفًا تاريخيًّا بدلالة الهيدروجين (الاختزال: اكتساب الهيدروجين)، ولا يتناوله الكتاب.', 'high'),
(404106, 'يشرح الكتاب حساب الجهد بالعلاقة E°cell = E°cathode − E°anode، ومنها خلية Zn–Cu: ‎+0.342 − (−0.762) = +1.104 V (الشكل 4-7)، والمثال 4-1 (I2/Fe = +0.983 V) مع التفاعل الكلي ورمز الخلية Zn | Zn2+ || Cu2+ | Cu، ويعرض رسوم الخلايا في أشكاله (4-2، 4-6) دون خطوات لرسمها.', 'خطوات رسم خلية جلفانية، مثل خلية الخارصين–النحاس:
1. ارسم كأسين: في الأول قطب خارصين Zn مغموس في محلول أيونات Zn2+ (1M)، وفي الثاني قطب نحاس Cu مغموس في محلول أيونات Cu2+ (1M).
2. حدد الأنود والكاثود من جدول جهود الاختزال القياسية: القطب الأعلى جهد اختزال (Cu: +0.342 V) هو الكاثود، ويحدث عنده الاختزال، والآخر (Zn: −0.762 V) هو الأنود، وتحدث عنده الأكسدة.
3. صِل القطبين بسلك خارجي عليه مقياس جهد (فولتميتر)، وارسم سهم انتقال الإلكترونات في السلك من الأنود (Zn) إلى الكاثود (Cu).
4. صِل المحلولين بقنطرة ملحية، تتحرك عبرها الأيونات السالبة نحو نصف خلية الأنود، والموجبة نحو نصف خلية الكاثود.
5. اكتب نصفي التفاعل تحت كل كأس، والتفاعل الكلي: Zn + Cu2+ → Zn2+ + Cu، والرمز: Zn | Zn2+ || Cu2+ | Cu، والجهد: E°cell = +1.104 V.
لاحظ أن الأنود يُكتب يسار الرمز، وأنه يقابل نصف الخلية اليسرى في الرسم عادة.', '["الكاثود: نصف الخلية ذات جهد الاختزال القياسي الأعلى، ويحدث عنده الاختزال.","الأنود: يحدث عنده التأكسد، ويُكتب يسار رمز الخلية.","الإلكترونات تنتقل في السلك الخارجي من الأنود إلى الكاثود.","القنطرة الملحية تكمل الدائرة: الأيونات السالبة نحو الأنود والموجبة نحو الكاثود.","E°cell = E°cathode − E°anode، ولخلية Zn–Cu تساوي +1.104 V."]'::jsonb, '["أن الإلكترونات تنتقل عبر القنطرة الملحية؛ والصحيح أن الأيونات هي التي تنتقل فيها، والإلكترونات في السلك فقط.","ضرب قيم E° في معاملات المعادلة عند موازنة الإلكترونات؛ فجهد الاختزال لا يتغير بتغير المعاملات.","عكس إشارة E° للأنود ثم طرحها في العلاقة نفسها، فيُطرح مرتين.","أن الأنود في الخلية الجلفانية هو القطب الموجب؛ والصحيح أنه القطب السالب في الخلية الجلفانية."]'::jsonb, 'قيم E° في الكتاب قياسية: تراكيز 1M وضغط 1 atm للغازات و25°C؛ ويختلف جهد الخلية عن القيمة القياسية إذا تغيرت هذه الظروف. وتُعد إشارة الأنود سالبة في الخلية الجلفانية، وتنعكس الإشارتان في خلايا التحليل الكهربائي.', 'high')
on conflict do nothing;

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-10-16'::timestamptz
from public.objectives o where o.code like 'K3-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-10-16'::timestamptz
from public.objectives o where o.code like 'K3-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

commit;
